// ── Atlante / layer "Documentato" ─────────────────────────────────────
// Documentato NON è un quinto status: è un flag parallelo alla piramide
// misterioso→ricercato→avvistato→catturato. Dice "lo conosco", non "l'ho visto".
// Non tocca mai la logica di ranking degli status.
const DOCUMENTED_META = { label:'Documentato', short:'DOC.', c:'#9DD3FF', bg:'rgba(157,211,255,.14)', border:'1.5px solid rgba(157,211,255,.55)', dot:'#9DD3FF', desc:'Specie studiata nell\'Atlante: la conosci, ma non l\'hai ancora incontrata sul campo.' };
const DOCUMENTED_FILTER_VALUE = 'documentato';
// Mappa condivisa a livello modulo (stesso pattern di ANIMALS): la fonte di
// verità resta lo stato React nel componente principale, che la sincronizza.
let DOCUMENTED_MAP = {};
function setModuleDocumentedMap(map) { DOCUMENTED_MAP = map || {}; }
function getLocalDocumentedKey(userId) { return `animaldex_documented_${userId || 'guest'}`; }
function getLocalDocumentedMap(userId) {
  if (typeof window === 'undefined') return {};
  try { return JSON.parse(localStorage.getItem(getLocalDocumentedKey(userId)) || '{}') || {}; } catch { return {}; }
}
function saveLocalDocumentedMap(userId, map = {}) {
  if (typeof window === 'undefined') return;
  try { localStorage.setItem(getLocalDocumentedKey(userId), JSON.stringify(map || {})); } catch {}
}
function isAnimalDocumented(animal, documentedMap = DOCUMENTED_MAP) {
  if (!animal) return false;
  if (animal.documented) return true;
  return !!documentedMap?.[String(animal.id)];
}
function getLocalDateKey(date = new Date()) {
  const d = date instanceof Date ? date : new Date(date);
  if (Number.isNaN(d.getTime())) return '';
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}
function isAnimalDocumentedToday(animalId, documentedMap = DOCUMENTED_MAP) {
  const raw = documentedMap?.[String(animalId)];
  if (!raw || raw === true) return false;
  const docDay = getLocalDateKey(new Date(raw));
  return !!docDay && docDay === getLocalDateKey();
}
function canViewAnimalGameStats(animal, status, documentedMap = DOCUMENTED_MAP) {
  if (isRevealedStatus(status)) return true;
  return isAnimalDocumentedToday(animal?.id, documentedMap);
}
function dailyAtlasSeed() {
  const d = new Date();
  return d.getFullYear() * 372 + (d.getMonth() + 1) * 31 + d.getDate();
}
// Scoperta del giorno: una specie mondiale (misteriosa e non documentata),
// deterministica per data, uguale per tutta la giornata.
function getDailyAtlasDiscovery(animals = ANIMALS, documentedMap = DOCUMENTED_MAP, statusMap = {}, visitedCountries = []) {
  const seed = dailyAtlasSeed();
  let best = null;
  let bestScore = -1;
  for (const a of animals || []) {
    if (!a?.image_url) continue;
    if (documentedMap?.[String(a.id)]) continue;
    if (getResolvedAnimalStatus(a, statusMap, visitedCountries) !== 'misterioso') continue;
    const score = Math.abs(Math.sin(seed * 7919 + Number(a.id || a.no || 0) * 104729));
    if (score > bestScore) { bestScore = score; best = a; }
  }
  return best;
}
// La scoperta resta la stessa per tutta la giornata anche dopo che è stata
// documentata (CTA "Scopri" per aprire la scheda invece di cambiar subito specie).
function getDailyAtlasDiscoveryStable(userId, animals = ANIMALS, documentedMap = DOCUMENTED_MAP, statusMap = {}, visitedCountries = []) {
  const key = `animaldex_atlas_daily_${userId || 'guest'}`;
  const today = new Date().toISOString().slice(0, 10);
  if (typeof window !== 'undefined') {
    try {
      const raw = JSON.parse(localStorage.getItem(key) || 'null');
      if (raw?.date === today && raw.animalId) {
        const found = (animals || []).find(a => String(a.id) === String(raw.animalId));
        if (found) return found;
      }
    } catch {}
  }
  const pick = getDailyAtlasDiscovery(animals, documentedMap, statusMap, visitedCountries);
  if (pick && typeof window !== 'undefined') {
    try { localStorage.setItem(key, JSON.stringify({ date:today, animalId:String(pick.id) })); } catch {}
  }
  return pick;
}

// ── Spedizioni a ondate ───────────────────────────────────────────────
// Un paese visitato è un "diario" (sempre libero). La Spedizione rivela le
// specie a ondate progressive. Paesi senza entry (legacy/onboarding) sono
// interamente rivelati.
const EXPEDITION_WAVE_SIZE = 30;
const EXPEDITION_WAVE_ADVANCE = { seen:10, captured:3 };
const EXPEDITION_ALL_WAVES = 99;
const EXPEDITION_CREDIT_MAX = 3;
let EXPEDITION_STATE = {};
function setModuleExpeditionState(state) { EXPEDITION_STATE = state || {}; }
function getExpeditionStateKey(userId) { return `animaldex_expeditions_${userId || 'guest'}`; }
function getLocalExpeditionState(userId) {
  if (typeof window === 'undefined') return {};
  try { return JSON.parse(localStorage.getItem(getExpeditionStateKey(userId)) || '{}') || {}; } catch { return {}; }
}
function saveLocalExpeditionState(userId, state = {}) {
  if (typeof window === 'undefined') return;
  try { localStorage.setItem(getExpeditionStateKey(userId), JSON.stringify(state || {})); } catch {}
}
const expeditionWaveCache = new Map();
function getCountryWaveAnimalIds(iso, animals = ANIMALS) {
  const code = String(iso || '').toUpperCase();
  const key = `${code}:${(animals || []).length}`;
  if (expeditionWaveCache.has(key)) return expeditionWaveCache.get(key);
  const rows = (animals || [])
    .filter(a => getAnimalCountryCodes(a).some(c => String(c).toUpperCase() === code))
    .sort((a, b) =>
      ((RARITY[a.rarity]?.s || 1) - (RARITY[b.rarity]?.s || 1))
      || (getObservationCount(b) - getObservationCount(a))
      || (Number(a.id || a.no || 0) - Number(b.id || b.no || 0))
    );
  const ids = rows.map(r => String(r.id));
  expeditionWaveCache.set(key, ids);
  return ids;
}
function getCountryWaveCount(iso, animals = ANIMALS) {
  return Math.max(1, Math.ceil(getCountryWaveAnimalIds(iso, animals).length / EXPEDITION_WAVE_SIZE));
}
function getRevealedWaves(iso, expeditionState = EXPEDITION_STATE) {
  const entry = expeditionState?.[String(iso || '').toUpperCase()];
  if (!entry) return EXPEDITION_ALL_WAVES;
  return Math.max(0, Number(entry.revealedWaves ?? 1));
}
const expeditionRevealedSetCache = new Map();
function getRevealedIdSetForCountry(iso, animals = ANIMALS, expeditionState = EXPEDITION_STATE) {
  const code = String(iso || '').toUpperCase();
  const revealed = getRevealedWaves(code, expeditionState);
  const key = `${code}:${revealed}:${(animals || []).length}`;
  if (expeditionRevealedSetCache.has(key)) return expeditionRevealedSetCache.get(key);
  const ids = getCountryWaveAnimalIds(code, animals);
  const limit = revealed >= EXPEDITION_ALL_WAVES ? ids.length : Math.min(ids.length, Math.max(0, revealed) * EXPEDITION_WAVE_SIZE);
  const set = new Set(ids.slice(0, limit));
  expeditionRevealedSetCache.set(key, set);
  if (expeditionRevealedSetCache.size > 400) expeditionRevealedSetCache.clear();
  return set;
}
// Progresso dell'ondata corrente di un paese: quante specie della finestra
// rivelata sono avvistate/catturate, e se l'ondata successiva va aperta.
function getExpeditionProgress(iso, statusMap = {}, expeditionState = EXPEDITION_STATE, animals = ANIMALS) {
  const code = String(iso || '').toUpperCase();
  const ids = getCountryWaveAnimalIds(code, animals);
  const waveCount = Math.max(1, Math.ceil(ids.length / EXPEDITION_WAVE_SIZE));
  const revealedRaw = getRevealedWaves(code, expeditionState);
  const revealed = Math.min(revealedRaw >= EXPEDITION_ALL_WAVES ? waveCount : revealedRaw, waveCount);
  const complete = revealed >= waveCount;
  let seenInWave = 0;
  let capturedInWave = 0;
  if (!complete && revealed > 0) {
    const start = (revealed - 1) * EXPEDITION_WAVE_SIZE;
    const windowIds = ids.slice(start, revealed * EXPEDITION_WAVE_SIZE);
    for (const id of windowIds) {
      const s = normalizeAnimalStatus(statusMap?.[id]);
      if (s === 'avvistato') seenInWave += 1;
      if (s === 'catturato') { seenInWave += 1; capturedInWave += 1; }
    }
  }
  const shouldAdvance = !complete && revealed > 0 && (seenInWave >= EXPEDITION_WAVE_ADVANCE.seen || capturedInWave >= EXPEDITION_WAVE_ADVANCE.captured);
  return { totalSpecies:ids.length, waveCount, revealedWaves:revealed, pending:revealedRaw <= 0, complete, seenInWave, capturedInWave, shouldAdvance };
}
// Crediti attivazione Spedizioni (free: 1 al mese, accumulabili fino a 3).
function getExpeditionCreditsKey(userId) { return `animaldex_expedition_credits_${userId || 'guest'}`; }
function currentYearMonth() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}
function monthsBetweenYearMonths(fromYm, toYm) {
  const [fy, fm] = String(fromYm || '').split('-').map(Number);
  const [ty, tm] = String(toYm || '').split('-').map(Number);
  if (!fy || !ty) return 0;
  return Math.max(0, (ty - fy) * 12 + (tm - fm));
}
function loadExpeditionCredits(userId) {
  if (typeof window === 'undefined') return { credits:EXPEDITION_CREDIT_MAX, lastMonth:currentYearMonth() };
  const nowYm = currentYearMonth();
  try {
    const raw = JSON.parse(localStorage.getItem(getExpeditionCreditsKey(userId)) || 'null');
    if (!raw || !raw.lastMonth) {
      const fresh = { credits:1, lastMonth:nowYm };
      localStorage.setItem(getExpeditionCreditsKey(userId), JSON.stringify(fresh));
      return fresh;
    }
    const accrued = monthsBetweenYearMonths(raw.lastMonth, nowYm);
    const next = { credits:Math.min(EXPEDITION_CREDIT_MAX, Math.max(0, Number(raw.credits || 0)) + accrued), lastMonth:nowYm };
    if (accrued > 0) localStorage.setItem(getExpeditionCreditsKey(userId), JSON.stringify(next));
    return next;
  } catch {
    return { credits:1, lastMonth:nowYm };
  }
}
function consumeExpeditionCredit(userId) {
  const state = loadExpeditionCredits(userId);
  if (state.credits <= 0) return false;
  const next = { ...state, credits:state.credits - 1 };
  try { localStorage.setItem(getExpeditionCreditsKey(userId), JSON.stringify(next)); } catch {}
  return true;
}

// ── Quota riconoscimenti AI (le catture passano solo da qui) ─────────
// Free: 5/mese. Regalo di Spedizione: +10 per 14 giorni a ogni attivazione,
// consumato per primo. Le foto giudicate inutilizzabili non consumano quota.
const AI_RECOGNITION_MONTHLY_FREE = 5;
const EXPEDITION_GIFT_RECOGNITIONS = 10;
const EXPEDITION_GIFT_DAYS = 14;
function getAiUsageKey(userId) { return `animaldex_ai_usage_${userId || 'guest'}_${currentYearMonth()}`; }
function getAiGiftKey(userId) { return `animaldex_ai_gift_${userId || 'guest'}`; }
function getAiGift(userId) {
  if (typeof window === 'undefined') return null;
  try {
    const raw = JSON.parse(localStorage.getItem(getAiGiftKey(userId)) || 'null');
    if (!raw || Number(raw.expiresAt || 0) < Date.now() || Number(raw.remaining || 0) <= 0) return null;
    return raw;
  } catch { return null; }
}
function grantExpeditionGift(userId) {
  if (typeof window === 'undefined') return null;
  const gift = { remaining:EXPEDITION_GIFT_RECOGNITIONS, expiresAt:Date.now() + EXPEDITION_GIFT_DAYS * 24 * 60 * 60 * 1000 };
  try { localStorage.setItem(getAiGiftKey(userId), JSON.stringify(gift)); } catch {}
  return gift;
}
function getAiRecognitionAllowance(userId) {
  let used = 0;
  try { used = Number(localStorage.getItem(getAiUsageKey(userId)) || 0); } catch {}
  const gift = getAiGift(userId);
  const giftRemaining = gift ? Math.max(0, Number(gift.remaining || 0)) : 0;
  const baseRemaining = Math.max(0, AI_RECOGNITION_MONTHLY_FREE - used);
  return { used, baseRemaining, giftRemaining, remaining:baseRemaining + giftRemaining, giftExpiresAt:gift?.expiresAt || null };
}
function consumeAiRecognition(userId) {
  const gift = getAiGift(userId);
  if (gift) {
    const next = { ...gift, remaining:Math.max(0, Number(gift.remaining || 0) - 1) };
    try { localStorage.setItem(getAiGiftKey(userId), JSON.stringify(next)); } catch {}
    return;
  }
  try {
    const key = getAiUsageKey(userId);
    localStorage.setItem(key, String(Number(localStorage.getItem(key) || 0) + 1));
  } catch {}
}
function getAnimalImageUrl(animal) {
  return animal?.image_url || (LOCAL_ANIMALS.find(x => Number(x.id) === Number(animal?.id) || x.sci === animal?.sci)?.image_url || '');
}
function getAnimalGridImageUrl(animal) {
  const imageUrl = getAnimalImageUrl(animal);
  if (!imageUrl || /^(https?:|data:|blob:)/i.test(imageUrl)) return imageUrl;

  const cleanUrl = String(imageUrl).split('#')[0].split('?')[0];
  const filename = cleanUrl.split('/').pop();
  if (!filename) return imageUrl;

  const basename = filename.replace(/\.[^.]+$/, '');
  return `/animals/thumbs/${basename}.webp`;
}

function useImagePixelBounds(src) {
  const [bounds, setBounds] = useState(null);
  useEffect(() => {
    let alive = true;
    if (!src || typeof window === 'undefined') { setBounds(null); return; }
    const img = new Image();
    img.crossOrigin = 'anonymous';
    img.onload = () => {
      if (!alive) return;
      const w = img.naturalWidth || 1;
      const h = img.naturalHeight || 1;
      try {
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d', { willReadFrequently:true });
        ctx.drawImage(img, 0, 0);
        const data = ctx.getImageData(0, 0, w, h).data;
        let minX=w, minY=h, maxX=0, maxY=0, found=false;
        for (let y=0; y<h; y += 1) {
          for (let x=0; x<w; x += 1) {
            if (data[(y*w+x)*4+3] > 12) {
              found = true;
              minX = Math.min(minX, x); minY = Math.min(minY, y);
              maxX = Math.max(maxX, x); maxY = Math.max(maxY, y);
            }
          }
        }
        setBounds(found ? { naturalWidth:w, naturalHeight:h, x:minX, y:minY, width:maxX-minX+1, height:maxY-minY+1 } : { naturalWidth:w, naturalHeight:h, x:0, y:0, width:w, height:h });
      } catch {
        setBounds({ naturalWidth:w, naturalHeight:h, x:0, y:0, width:w, height:h });
      }
    };
    img.onerror = () => alive && setBounds(null);
    img.src = src;
    return () => { alive = false; };
  }, [src]);
  return bounds;
}
const QUICK_SEEN_REJECT_COOLDOWN_DAYS = 14;
const QUICK_SEEN_REJECTED_KEY = 'animaldex_quick_seen_rejected_until';
function getQuickSeenRejectedMap() {
  try {
    const raw = JSON.parse(localStorage.getItem(QUICK_SEEN_REJECTED_KEY) || '{}') || {};
    const now = Date.now();
    const clean = {};
    Object.entries(raw).forEach(([id, until]) => {
      const ts = Number(until || 0);
      if (ts > now) clean[id] = ts;
    });
    if (Object.keys(clean).length !== Object.keys(raw).length) localStorage.setItem(QUICK_SEEN_REJECTED_KEY, JSON.stringify(clean));
    return clean;
  } catch { return {}; }
}
function rejectQuickSeenForCooldown(id) {
  if (!id) return;
  try {
    const map = getQuickSeenRejectedMap();
    const until = Date.now() + QUICK_SEEN_REJECT_COOLDOWN_DAYS * 24 * 60 * 60 * 1000;
    map[String(id)] = until;
    localStorage.setItem(QUICK_SEEN_REJECTED_KEY, JSON.stringify(map));
  } catch {}
}
function isQuickSeenRejected(id) {
  const map = getQuickSeenRejectedMap();
  return Number(map[String(id)] || 0) > Date.now();
}
function quickSeenDailyShuffleScore(animal) {
  const d = new Date();
  const seed = Number(`${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}`);
  const n = Number(animal?.id || animal?.no || 0);
  return ((n * 9301 + seed * 49297) % 233280) / 233280;
}
function getAnimalVisitedCountryMatches(animal, visitedCountries = []) {
  const visited = (visitedCountries || []).map(c => String(c).toUpperCase());
  const available = new Set(getAnimalCountryCodes(animal).map(c => String(c).toUpperCase()));
  return visited.filter(code => available.has(code));
}
function getQuickSeenCandidates(animals, statusMap, visitedCountries) {
  const visited = (visitedCountries || []).map(c => String(c).toUpperCase()).filter(Boolean);
  return (animals || [])
    .map(a => {
      const local = LOCAL_ANIMALS.find(x => Number(x.id) === Number(a.id) || x.sci === a.sci) || {};
      const merged = { ...local, ...a, image_url:a.image_url || local.image_url || local.img || '' };
      const matchedVisitedCountries = getAnimalVisitedCountryMatches(merged, visited);
      return {
        ...merged,
        status:getResolvedAnimalStatus(merged, statusMap, visitedCountries),
        matchedVisitedCountries,
        countryMatchCount:matchedVisitedCountries.length,
        observationCount:getObservationCount(merged),
        rarityScore:RARITY[merged.rarity]?.s || 1,
      };
    })
    .filter(a => a.status === 'ricercato')
    .filter(a => visited.length > 0 && a.countryMatchCount > 0)
    .filter(a => !isQuickSeenRejected(a.id))
    .filter(a => !!a.image_url)
    .sort((a,b) => (a.rarityScore - b.rarityScore) || (b.observationCount - a.observationCount) || (quickSeenDailyShuffleScore(a) - quickSeenDailyShuffleScore(b)))
    .slice(0, QUICK_SEEN_DAILY_LIMIT * 3);
}
function track(eventName, payload = {}) {
  apexDebugLog('[track]', eventName, payload);
}

function getAnimaldexSessionId() {
  if (typeof window === 'undefined') return '';
  const key = 'animaldex_session_id';
  try {
    const existing = window.sessionStorage.getItem(key);
    if (existing) return existing;
    const id = `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    window.sessionStorage.setItem(key, id);
    return id;
  } catch {
    return '';
  }
}

async function trackUserEvent(user, eventName, payload = {}, profile = null) {
  track(eventName, payload);
  if (!user?.id) return;
  if (profile && profile.consent_analytics === false) return;
  try {
    const cleanPayload = payload && typeof payload === 'object' ? { ...payload } : {};
    await supabase.from('user_events').insert({
      user_id: user.id,
      event_name: eventName,
      source_screen: cleanPayload.source_screen || cleanPayload.source || null,
      session_id: getAnimaldexSessionId() || null,
      app_version: process.env.REACT_APP_VERSION || null,
      plan: profile?.plan_key || profile?.plan || 'free',
      animal_id: cleanPayload.animal_id || null,
      previous_status: cleanPayload.previous_status || null,
      next_status: cleanPayload.next_status || null,
      rarity: cleanPayload.rarity || null,
      country_iso: cleanPayload.country_iso || cleanPayload.iso || null,
      payload: cleanPayload,
    });
  } catch (err) {
    console.warn('[Apex] tracking evento non salvato:', err);
  }
}



function appStatusToSupabase(status) {
  const s = normalizeAnimalStatus(status);
  if (s === 'misterioso') return 'locked';
  if (s === 'ricercato') return 'unlocked';
  if (s === 'avvistato') return 'seen';
  if (s === 'catturato') return 'collected';
  return 'locked';
}

function supabaseStatusToApp(status) {
  const s = String(status || '').toLowerCase().trim();
  if (s === 'locked') return 'misterioso';
  if (s === 'unlocked') return 'ricercato';
  if (s === 'seen') return 'avvistato';
  if (s === 'collected') return 'catturato';
  return normalizeAnimalStatus(s);
}

function getRawValue(raw, keys, fallback = undefined) {
  if (!raw || typeof raw !== 'object') return fallback;
  for (const k of keys) {
    if (raw[k] !== undefined && raw[k] !== null) return raw[k];
  }
  return fallback;
}

function toArraySafe(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.filter(Boolean);
  if (typeof value === 'string') return value.split(/[;,|]/).map(v => v.trim()).filter(Boolean);
  return [];
}

function normalizeSupabaseAnimal(row, userAnimal) {
  const raw = patchAnimalTaxonomy(row?.raw && typeof row.raw === 'object' ? row.raw : {});
  const geoRow = Array.isArray(row?.animal_geo) ? row.animal_geo[0] : row?.animal_geo;
  const rawGeo = raw?.geo && typeof raw.geo === 'object' ? raw.geo : {};
  const rawGeoFromRow = geoRow?.raw_geo && typeof geoRow.raw_geo === 'object' ? geoRow.raw_geo : {};
  const geo = { ...rawGeo, ...rawGeoFromRow, ...(geoRow || {}) };
  const geoIso = geo?.iso;
  const geoIsoValues = geoIso && typeof geoIso === 'object'
    ? [...toArraySafe(geoIso.primary), ...toArraySafe(geoIso.iucn), ...toArraySafe(geoIso.observed), ...toArraySafe(geoIso.geoson_range)]
    : toArraySafe(geoIso);
  const countries = normalizeIsoList([
    ...geoIsoValues,
    ...toArraySafe(raw?.distribution?.countries_present),
    ...toArraySafe(raw?.countries_present),
    ...toArraySafe(raw?.iso),
  ]);
  const categories = toArraySafe(getRawValue(raw, ['categories', 'category_ids', 'badges', 'abilities'], []));
  const status = supabaseStatusToApp(userAnimal?.unlock_status || 'locked');

  return {
    ...raw,
    ...row,
    desc: row?.description || raw.desc || raw.description || '',
    description: row?.description || raw.description || raw.desc || '',
    image_url: row?.image_url || raw.image_url || raw.img || '',
    com: row?.com || raw.com || raw.name || '',
    sci: row?.sci || raw.sci || raw.scientific_name || '',
    com_en: row?.com_en || raw.com_en || '',
    no: row?.no || raw.no || String(row?.id || '').padStart(3, '0'),
    cls: row?.cls || raw.cls || raw.class || '',
    ord: row?.ord || raw.ord || raw.order || '',
    fam: row?.fam || raw.fam || raw.family || '',
    gen: row?.gen || raw.gen || raw.genus || '',
    phy: row?.phy || raw.phy || raw.phylum || '',
    kin: row?.kin || raw.kin || raw.kingdom || 'Animalia',
    rarity: row?.rarity || raw.rarity || 'Comune',
    cons: raw.cons || raw.iucn || raw.conservation || 'DD',
    trophic: raw.trophic || raw.trophic_level || '2',
    wt: raw.wt || raw.weight || '',
    ln: raw.ln || raw.length || '',
    stats: raw.stats || {},
    categories,
    cat_curiosities: raw.cat_curiosities || raw.category_curiosities || {},
    distribution: {
      ...(raw.distribution || {}),
      countries_present: countries,
    },
    geo: geo || null,
    bioregions_v4: toArraySafe(geo?.bioregions_v4 || rawGeo?.bioregions_v4 || raw.bioregions_v4),
    map_bioregion_ids_v4: toArraySafe(geo?.map_bioregion_ids_v4 || rawGeo?.map_bioregion_ids_v4 || raw.map_bioregion_ids_v4),
    map_bioregion_domains_v4: toArraySafe(geo?.map_bioregion_domains_v4 || rawGeo?.map_bioregion_domains_v4 || raw.map_bioregion_domains_v4),
    map_profile: geo?.map_profile || raw.map_profile || '',
    confidence: geo?.confidence || geo?.bioregion_confidence || raw.confidence || '',
    bio_regions: toArraySafe(geo?.bio_regions || raw.bio_regions),
    game_regions: toArraySafe(geo?.game_regions || raw.game_regions),
    habitats: toArraySafe(geo?.habitats || geo?.habitat_ids || raw.habitats || raw.habitat),
    userStatus: userAnimal?.unlock_status || 'locked',
    userAnimal: userAnimal || null,
    status,
  };
}

function normalizeLocalAnimal(a) {
  const patched = patchAnimalTaxonomy(a || {});
  const next = {
    ...patched,
    geo: a.geo || null,
    bioregions_v4: toArraySafe(a.bioregions_v4 || a.geo?.bioregions_v4),
    map_bioregion_ids_v4: toArraySafe(a.map_bioregion_ids_v4 || a.geo?.map_bioregion_ids_v4),
    map_bioregion_domains_v4: toArraySafe(a.map_bioregion_domains_v4 || a.geo?.map_bioregion_domains_v4),
    confidence: a.confidence || a.geo?.confidence || a.geo?.bioregion_confidence || '',
    map_profile: a.map_profile || a.geo?.map_profile || '',
    bio_regions: toArraySafe(a.bio_regions || a.geo?.bio_regions),
    game_regions: toArraySafe(a.game_regions || a.geo?.game_regions),
    habitats: toArraySafe(a.habitats || a.habitat || a.geo?.habitats || a.geo?.habitat_ids),
    userStatus: appStatusToSupabase(a.status),
    status: normalizeAnimalStatus(a.status),
  };
  next._searchText = getAnimalSearchText(next);
  return next;
}

function buildUniqueFilterOptions(values, color='#7AC7FF') {
  return Array.from(new Set(values.flatMap(v => toArraySafe(v)).filter(Boolean))).sort().map(v => ({
    value:v,
    label:prettyFilterLabel(v),
    c:color,
    bg:`${color}22`,
  }));
}

let ANIMAL_GRID_FILTER_OPTS = {
  mapProfile:[],
  bioRegion:[],
  gameRegion:[],
  habitat:[],
};

function rebuildAnimalGridFilterOptions(list = []) {
  ANIMAL_GRID_FILTER_OPTS = {
    mapProfile: buildUniqueFilterOptions(list.map(a => a.map_profile || a.geo?.map_profile), '#5BBEF8'),
    bioRegion: buildUniqueFilterOptions(list.map(a => a.bio_regions || a.geo?.bio_regions), '#6CE5C7'),
    gameRegion: buildUniqueFilterOptions(list.map(a => a.game_regions || a.geo?.game_regions), '#B860F8'),
    habitat: buildUniqueFilterOptions(list.map(a => a.habitats || a.habitat || a.geo?.habitats), '#F0A840'),
  };
}

function hydrateLocalAnimalIndexes(list = []) {
  const normalized = (Array.isArray(list) ? list : []).map(item => normalizeLocalAnimal(item));
  LOCAL_ANIMALS = normalized;
  ANIMALS = normalized;
  LOCAL_ANIMAL_BY_ID = Object.fromEntries(normalized.map(a => [a.id, a]));
  rebuildAnimalGridFilterOptions(normalized);
  invalidateComparatorBenchmarksCache();
  invalidateLifeAnimalsCache();
  const warmComparatorBenchmarks = () => getCachedComparatorBenchmarks(normalized);
  const warmLifeIndex = () => ensureLifeAnimalsIndex(normalized);
  if (typeof requestIdleCallback === 'function') {
    requestIdleCallback(warmComparatorBenchmarks, { timeout: 800 });
    requestIdleCallback(warmLifeIndex, { timeout: 2200 });
  } else {
    setTimeout(warmComparatorBenchmarks, 0);
    setTimeout(warmLifeIndex, 250);
  }
  return LOCAL_ANIMALS;
}

async function loadLocalAnimalsData() {
  if (LOCAL_ANIMALS.length) return LOCAL_ANIMALS;
  if (!localAnimalsLoadPromise) {
    localAnimalsLoadPromise = import('./animals-data-grid')
      .then(module => hydrateLocalAnimalIndexes(module.ANIMALS || []))
      .catch(err => {
        console.warn('[Apex] Dataset grid non disponibile, uso dataset completo:', err);
        return import('./animals-data').then(module => hydrateLocalAnimalIndexes(module.ANIMALS || []));
      })
      .catch(err => {
        localAnimalsLoadPromise = null;
        throw err;
      });
  }
  return localAnimalsLoadPromise;
}

function hydrateFullAnimalIndexes(fullList = []) {
  LOCAL_ANIMAL_FULL_BY_ID = Object.fromEntries((fullList || []).map(a => [a.id, a]));
  LOCAL_ANIMALS = (fullList || []).map(full => {
    const prev = LOCAL_ANIMAL_BY_ID[full.id];
    return normalizeLocalAnimal({
      ...full,
      status: prev?.status ?? full.status,
      userStatus: prev?.userStatus ?? appStatusToSupabase(prev?.status ?? full.status),
    });
  });
  ANIMALS = LOCAL_ANIMALS;
  LOCAL_ANIMAL_BY_ID = Object.fromEntries(LOCAL_ANIMALS.map(a => [a.id, a]));
  rebuildAnimalGridFilterOptions(LOCAL_ANIMALS);
  invalidateComparatorBenchmarksCache();
  invalidateLifeAnimalsCache();
  const warmLifeIndex = () => ensureLifeAnimalsIndex(LOCAL_ANIMALS);
  if (typeof requestIdleCallback === 'function') requestIdleCallback(warmLifeIndex, { timeout: 1200 });
  else setTimeout(warmLifeIndex, 0);
  return LOCAL_ANIMALS;
}

function queueFullAnimalsHydration() {
  if (fullAnimalsLoadPromise) return fullAnimalsLoadPromise;
  if (Object.keys(LOCAL_ANIMAL_FULL_BY_ID).length) return Promise.resolve(LOCAL_ANIMALS);
  fullAnimalsLoadPromise = import('./animals-data')
    .then(module => hydrateFullAnimalIndexes(module.ANIMALS || []))
    .catch(err => {
      console.warn('[Apex] Dataset completo non caricato:', err);
      fullAnimalsLoadPromise = null;
      return LOCAL_ANIMALS;
    });
  return fullAnimalsLoadPromise;
}

function getEnrichedAnimal(animal) {
  if (!animal?.id) return animal;
  const full = LOCAL_ANIMAL_FULL_BY_ID[animal.id];
  if (!full) return animal;
  return normalizeLocalAnimal({
    ...full,
    ...animal,
    status: animal.status ?? full.status,
    userStatus: animal.userStatus ?? full.userStatus,
  });
}

function mergeRemoteWithLocalBioregions(remoteList = []) {
  return (remoteList || []).map(remote => {
    const local = LOCAL_ANIMAL_BY_ID[remote.id];
    if (!local) return remote;
    const remoteIds = getAnimalBioregionIdsV4(remote);
    const hasStats = remote.stats && Object.keys(remote.stats || {}).length > 0;
    const hasCats = remote.categories && remote.categories.length > 0;
    const remoteCountries = getAnimalCountryCodes(remote);
    const localCountries = getAnimalCountryCodes(local);
    const bestCountries = localCountries.length > remoteCountries.length ? localCountries : normalizeIsoList([...remoteCountries, ...localCountries]);
    const enrichedRemote = {
      ...remote,
      foodweb: remote.foodweb || local.foodweb || null,
      lifespan: remote.lifespan ?? local.lifespan,
      wt: remote.wt || local.wt || '',
      ln: remote.ln || local.ln || '',
      trophic: remote.trophic || local.trophic,
      stats: hasStats ? remote.stats : (local.stats || {}),
      categories: hasCats ? remote.categories : (local.categories || []),
      cat_curiosities: Object.keys(remote.cat_curiosities || {}).length ? remote.cat_curiosities : (local.cat_curiosities || {}),
      distribution: {
        ...(local.distribution || {}),
        ...(remote.distribution || {}),
        countries_present: bestCountries,
      },
    };
    if (remoteIds.length) return enrichedRemote;
    return {
      ...enrichedRemote,
      geo:{ ...(remote.geo || {}), ...(local.geo || {}) },
      bioregions_v4: local.bioregions_v4 || [],
      map_bioregion_ids_v4: local.map_bioregion_ids_v4 || [],
      map_bioregion_domains_v4: local.map_bioregion_domains_v4 || [],
      bio_regions: remote.bio_regions?.length ? remote.bio_regions : local.bio_regions,
      game_regions: remote.game_regions?.length ? remote.game_regions : local.game_regions,
      habitats: remote.habitats?.length ? remote.habitats : local.habitats,
    };
  });
}
function applyCachedUserStatuses(list = [], userId) {
  const cached = getLocalUserStatusMap(userId);
  if (!Object.keys(cached).length) return list;
  return (list || []).map(a => {
    const cachedStatus = cached[a.id] ?? cached[String(a.id)];
    if (!cachedStatus) return a;
    const currentRank = ANIMAL_STATUS_ORDER.indexOf(normalizeAnimalStatus(a.status));
    const cachedRank = ANIMAL_STATUS_ORDER.indexOf(normalizeAnimalStatus(cachedStatus));
    if (cachedRank <= currentRank) return a;
    return { ...a, status:normalizeAnimalStatus(cachedStatus), userStatus:appStatusToSupabase(cachedStatus) };
  });
}

function buildLocalAnimalSnapshot(userId, statusMapOverride = {}, remoteUserStatusMap = {}) {
  if (!LOCAL_ANIMALS.length || !userId) return null;
  const sourceAnimals = applyCachedUserStatuses(LOCAL_ANIMALS.map(normalizeLocalAnimal), userId);
  const remoteStatusMap = Object.fromEntries(sourceAnimals.map(a => [a.id, normalizeAnimalStatus(a.status)]));
  const nextStatusMap = mergeStatusMapsByRank(remoteStatusMap, remoteUserStatusMap, getLocalUserStatusMap(userId), statusMapOverride);
  const nextAnimals = sourceAnimals.map(a => {
    const status = nextStatusMap[a.id] || normalizeAnimalStatus(a.status);
    const base = a._searchText ? a : { ...a, _searchText:getAnimalSearchText(a) };
    return { ...base, status, userStatus:appStatusToSupabase(status) };
  });
  return { nextAnimals, nextStatusMap };
}

async function ensureUserProfile(user) {
  if (!user?.id) return false;

  const username = getDefaultUsernameFromUser(user);

  try {
    const { data, error } = await supabase
      .from('user_profiles')
      .select('user_id, username, nickname')
      .eq('user_id', user.id)
      .maybeSingle();

    if (error && error.code !== 'PGRST116') throw error;
    if (data) {
      if (!data.username || !data.nickname) {
        await supabase
          .from('user_profiles')
          .update({
            username:data.username || username,
            nickname:data.nickname || data.username || username,
            updated_at:new Date().toISOString(),
          })
          .eq('user_id', user.id);
      }
      return true;
    }

    const { error: insertError } = await supabase
      .from('user_profiles')
      .upsert(
        { user_id: user.id, username, nickname:username },
        { onConflict:'user_id' }
      );

    // In signup con conferma email attiva Supabase può restituire un user non ancora utilizzabile
    // lato FK/RLS. Non blocchiamo l'app: riproveremo dopo login/sessione valida.
    if (insertError) {
      console.warn('[Apex] Profilo non ancora creabile:', insertError);
      return false;
    }

    return true;
  } catch (err) {
    console.warn('[Apex] ensureUserProfile skipped:', err);
    return false;
  }
}

function hasLocalUserProgress(userId) {
  if (!userId || typeof window === 'undefined') return false;
  try {
    if (Object.keys(getLocalUserStatusMap(userId)).length > 0) return true;
    if (normalizeIsoList(getVisitedCountries()).length > 0) return true;
    if (getAwardUnlockSet().size > 0) return true;
    if (Object.keys(getLocalDocumentedMap(userId)).length > 0) return true;
    return false;
  } catch {
    return false;
  }
}

function resolveProfileFirstTimeFlags(profile = {}, userId) {
  const resolvedUserId = userId || profile?.user_id;
  const local = normalizeProfileQuestionnaire(getProfileDemographicsLocal(resolvedUserId));
  const dbOnboarding = Boolean(profile?.onboarding_completed);
  const dbTutorial = Boolean(profile?.has_completed_tutorial);
  const localOnboarding = Boolean(local.onboarding_completed);
  const localTutorial = Boolean(local.has_completed_tutorial);
  const hasProgress = hasLocalUserProgress(resolvedUserId);
  const hasStatuses = resolvedUserId ? Object.keys(getLocalUserStatusMap(resolvedUserId)).length > 0 : false;

  const onboarding_completed = dbOnboarding || localOnboarding || hasProgress;
  const has_completed_tutorial = dbTutorial || localTutorial || (onboarding_completed && hasStatuses);

  if (resolvedUserId && hasProgress && (!dbOnboarding || !dbTutorial) && (onboarding_completed || has_completed_tutorial)) {
    persistProfileDemographicsLocal(resolvedUserId, {
      onboarding_completed,
      has_completed_tutorial,
      onboarding_completed_at: profile?.onboarding_completed_at || local.onboarding_completed_at || null,
      tutorial_completed_at: profile?.tutorial_completed_at || local.tutorial_completed_at || null,
    });
  }

  return {
    onboarding_completed,
    has_completed_tutorial,
    onboarding_completed_at: profile?.onboarding_completed_at || local.onboarding_completed_at || null,
    tutorial_completed_at: profile?.tutorial_completed_at || local.tutorial_completed_at || null,
  };
}

async function fetchUserProfile(user) {
  if (!user?.id) return null;
  try {
    const { data, error } = await supabase
      .from('user_profiles')
      .select('*')
      .eq('user_id', user.id)
      .maybeSingle();

    if (error && error.code !== 'PGRST116') throw error;

    const username = getDefaultUsernameFromUser(user);
    if (!data) {
      return mergeProfileDemographics({
        user_id: user.id,
        username,
        nickname: username,
        first_login_reward_shown: false,
      }, user.id);
    }

    return mergeProfileDemographics({
      ...data,
      nickname: data.nickname || data.username || username,
      onboarding_completed: Boolean(data.onboarding_completed),
      has_completed_tutorial: Boolean(data.has_completed_tutorial),
      tutorial_completed_at: data.tutorial_completed_at || null,
      first_login_reward_shown: Boolean(data.first_login_reward_shown),
    }, user.id);
  } catch (err) {
    console.warn('[Apex] fetchUserProfile fallback:', err);
    return buildFallbackProfile(user, false);
  }
}

function withTimeout(promiseLike, ms, fallbackValue, label='timeout') {
  let timer;
  const safePromise = Promise.resolve(promiseLike);
  return Promise.race([
    safePromise.finally(() => clearTimeout(timer)),
    new Promise(resolve => {
      timer = setTimeout(() => {
        apexDebugWarn(`[Apex] ${label} dopo ${ms}ms`);
        resolve(fallbackValue);
      }, ms);
    })
  ]);
}

function getSupabaseProjectRef() {
  try {
    const host = new URL(process.env.REACT_APP_SUPABASE_URL || '').hostname;
    return host.split('.')[0] || 'sconosciuto';
  } catch {
    return 'sconosciuto';
  }
}

let cachedSupabaseAccessToken = '';
let cachedSupabaseAccessTokenExpiresAt = 0;

function syncSupabaseAccessTokenCache(session) {
  const token = session?.access_token || '';
  if (!token) {
    cachedSupabaseAccessToken = '';
    cachedSupabaseAccessTokenExpiresAt = 0;
    return '';
  }
  cachedSupabaseAccessToken = token;
  cachedSupabaseAccessTokenExpiresAt = session?.expires_at ? session.expires_at * 1000 : Date.now() + 3600000;
  return token;
}

function clearSupabaseAccessTokenCache() {
  cachedSupabaseAccessToken = '';
  cachedSupabaseAccessTokenExpiresAt = 0;
}

function readSupabaseAccessTokenFromStorage() {
  if (typeof window === 'undefined') return '';
  try {
    const ref = getSupabaseProjectRef();
    const keys = [
      `sb-${ref}-auth-token`,
      ...Object.keys(window.localStorage || {}).filter(key => key.includes(ref) && key.includes('auth-token')),
    ];
    for (const key of keys) {
      const raw = window.localStorage.getItem(key);
      if (!raw) continue;
      const parsed = JSON.parse(raw);
      const token = parsed?.access_token || parsed?.currentSession?.access_token || '';
      if (token) return token;
    }
  } catch {}
  return '';
}

async function getSupabaseAccessToken(maxWaitMs = 6000, preferredToken = '') {
  const preferred = String(preferredToken || '').trim();
  if (preferred) return syncSupabaseAccessTokenCache({ access_token:preferred, expires_at:Math.floor(Date.now() / 1000) + 3600 });

  const now = Date.now();
  if (cachedSupabaseAccessToken && cachedSupabaseAccessTokenExpiresAt > now + 30000) {
    return cachedSupabaseAccessToken;
  }

  const storedToken = readSupabaseAccessTokenFromStorage();
  if (storedToken) {
    cachedSupabaseAccessToken = storedToken;
    cachedSupabaseAccessTokenExpiresAt = now + 3600000;
    return storedToken;
  }

  const sessionResult = await withTimeout(
    supabase.auth.getSession(),
    maxWaitMs,
    { data:{ session:null }, error:null },
    'getSession'
  );
  let token = sessionResult?.data?.session?.access_token || '';
  if (token) return syncSupabaseAccessTokenCache(sessionResult.data.session);

  const refreshResult = await withTimeout(
    supabase.auth.refreshSession(),
    Math.max(2500, Math.floor(maxWaitMs * 0.7)),
    { data:{ session:null }, error:null },
    'refreshSession'
  );
  token = refreshResult?.data?.session?.access_token || '';
  if (token) return syncSupabaseAccessTokenCache(refreshResult.data.session);

  return readSupabaseAccessTokenFromStorage();
}

function createSocialSearchError(message, code, meta = {}) {
  const err = new Error(message);
  err.code = code;
  err.searchDebug = {
    ref:getSupabaseProjectRef(),
    ...meta,
  };
  return err;
}

async function runTimedSupabaseRequest(builder, ms, fallbackValue, label='supabase request') {
  const timeoutFallback = fallbackValue ?? { data:null, error:{ message:`${label} timeout`, code:'TIMEOUT' } };
  if (!builder || typeof builder.abortSignal !== 'function' || typeof AbortController === 'undefined') {
    return withTimeout(builder, ms, timeoutFallback, label);
  }
  const controller = new AbortController();
  let timer;
  const request = builder.abortSignal(controller.signal);
  try {
    return await Promise.race([
      request,
      new Promise(resolve => {
        timer = setTimeout(() => {
          apexDebugWarn(`[Apex] ${label} dopo ${ms}ms`);
          controller.abort();
          resolve(timeoutFallback);
        }, ms);
      }),
    ]);
  } catch (err) {
    const msg = String(err?.name || err?.message || '');
    if (/AbortError|aborted|abort/i.test(msg)) return timeoutFallback;
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

async function runTimedFetch(url, options = {}, ms = 8000, label='fetch', externalSignal = null) {
  if (typeof fetch === 'undefined') return null;
  if (externalSignal?.aborted) return null;
  if (typeof AbortController === 'undefined') {
    return withTimeout(fetch(url, options), ms, null, label);
  }
  const controller = new AbortController();
  const onExternalAbort = () => controller.abort();
  externalSignal?.addEventListener?.('abort', onExternalAbort);
  let timer;
  try {
    return await Promise.race([
      fetch(url, { ...options, signal:controller.signal }),
      new Promise(resolve => {
        timer = setTimeout(() => {
          apexDebugWarn(`[Apex] ${label} dopo ${ms}ms`);
          controller.abort();
          resolve(null);
        }, ms);
      }),
    ]);
  } catch (err) {
    const msg = String(err?.name || err?.message || '');
    if (/AbortError|aborted|abort/i.test(msg)) return null;
    throw err;
  } finally {
    clearTimeout(timer);
    externalSignal?.removeEventListener?.('abort', onExternalAbort);
  }
}

const PROFILE_DEMOGRAPHICS_STORAGE_PREFIX = 'animaldex_profile_demographics_';
function getProfileDemographicsLocal(userId) {
  if (!userId || typeof window === 'undefined') return {};
  try {
    const raw = localStorage.getItem(`${PROFILE_DEMOGRAPHICS_STORAGE_PREFIX}${userId}`);
    return raw ? JSON.parse(raw) || {} : {};
  } catch {
    return {};
  }
}
function normalizeProfileQuestionnaire(data = {}) {
  return {
    date_of_birth: data?.date_of_birth || data?.dob || '',
    residence_country: data?.residence_country || data?.country || '',
    gender: data?.gender || '',
    nationality: data?.nationality || '',
    phone: data?.phone || '',
    onboarding_objectives: Array.isArray(data?.onboarding_objectives) ? data.onboarding_objectives : Array.isArray(data?.objectives) ? data.objectives : [],
    onboarding_objective_other: data?.onboarding_objective_other || data?.objective_other || '',
    is_collector: data?.is_collector ?? data?.collector ?? null,
    annual_abroad_vacations: data?.annual_abroad_vacations || data?.vacations_abroad || '',
    pokemon_affinity: data?.pokemon_affinity || '',
    acquisition_source: data?.acquisition_source || '',
    acquisition_source_other: data?.acquisition_source_other || '',
    water_activity_interests: Array.isArray(data?.water_activity_interests) ? data.water_activity_interests : [],
    consent_terms_privacy: Boolean(data?.consent_terms_privacy || data?.termsAccepted),
    consent_analytics: Boolean(data?.consent_analytics),
    consent_marketing: Boolean(data?.consent_marketing),
    consent_personalization: Boolean(data?.consent_personalization),
    consent_newsletter: Boolean(data?.consent_newsletter),
    onboarding_completed: Boolean(data?.onboarding_completed),
    has_completed_tutorial: Boolean(data?.has_completed_tutorial),
    onboarding_completed_at: data?.onboarding_completed_at || null,
    tutorial_completed_at: data?.tutorial_completed_at || null,
  };
}
function persistProfileDemographicsLocal(userId, data = {}) {
  if (!userId || typeof window === 'undefined') return;
  try {
    const current = getProfileDemographicsLocal(userId);
    localStorage.setItem(`${PROFILE_DEMOGRAPHICS_STORAGE_PREFIX}${userId}`, JSON.stringify({
      ...current,
      ...normalizeProfileQuestionnaire(data),
    }));
  } catch {}
}
function mergeProfileDemographics(profile = {}, userId) {
  const local = getProfileDemographicsLocal(userId || profile?.user_id);
  const normalizedLocal = normalizeProfileQuestionnaire(local);
  return {
    ...profile,
    date_of_birth: profile?.date_of_birth || normalizedLocal.date_of_birth || '',
    residence_country: profile?.residence_country || profile?.country || normalizedLocal.residence_country || '',
    gender: profile?.gender || normalizedLocal.gender || '',
    nationality: profile?.nationality || normalizedLocal.nationality || '',
    phone: profile?.phone || normalizedLocal.phone || '',
    onboarding_objectives: profile?.onboarding_objectives || normalizedLocal.onboarding_objectives || [],
    onboarding_objective_other: profile?.onboarding_objective_other || normalizedLocal.onboarding_objective_other || '',
    is_collector: profile?.is_collector ?? normalizedLocal.is_collector,
    annual_abroad_vacations: profile?.annual_abroad_vacations || normalizedLocal.annual_abroad_vacations || '',
    pokemon_affinity: profile?.pokemon_affinity || normalizedLocal.pokemon_affinity || '',
    acquisition_source: profile?.acquisition_source || normalizedLocal.acquisition_source || '',
    acquisition_source_other: profile?.acquisition_source_other || normalizedLocal.acquisition_source_other || '',
    water_activity_interests: profile?.water_activity_interests || normalizedLocal.water_activity_interests || [],
    consent_terms_privacy: Boolean(profile?.consent_terms_privacy || normalizedLocal.consent_terms_privacy),
    consent_analytics: Boolean(profile?.consent_analytics || normalizedLocal.consent_analytics),
    consent_marketing: Boolean(profile?.consent_marketing || normalizedLocal.consent_marketing),
    consent_personalization: Boolean(profile?.consent_personalization || normalizedLocal.consent_personalization),
    consent_newsletter: Boolean(profile?.consent_newsletter || normalizedLocal.consent_newsletter),
    ...resolveProfileFirstTimeFlags(profile, userId || profile?.user_id),
  };
}
async function persistOnboardingQuestionnaire(user, payload = {}) {
  if (!user?.id) return;
  const q = normalizeProfileQuestionnaire(payload);
  persistProfileDemographicsLocal(user.id, q);
  const answers = {
    ...q,
    email: user?.email || '',
    auth_provider: user?.app_metadata?.provider || user?.identities?.[0]?.provider || 'email',
    updated_at: new Date().toISOString(),
  };
  try {
    await supabase.from('user_profiles').upsert({
      user_id: user.id,
      email: user?.email || null,
      auth_provider: user?.app_metadata?.provider || user?.identities?.[0]?.provider || 'email',
      date_of_birth: q.date_of_birth || null,
      residence_country: q.residence_country || null,
      gender: q.gender || null,
      nationality: q.nationality || null,
      phone: q.phone || null,
      onboarding_objectives: q.onboarding_objectives,
      onboarding_objective_other: q.onboarding_objective_other || null,
      is_collector: q.is_collector,
      annual_abroad_vacations: q.annual_abroad_vacations || null,
      pokemon_affinity: q.pokemon_affinity || null,
      acquisition_source: q.acquisition_source || null,
      acquisition_source_other: q.acquisition_source_other || null,
      water_activity_interests: q.water_activity_interests || [],
      consent_terms_privacy: q.consent_terms_privacy,
      consent_analytics: q.consent_analytics,
      consent_marketing: q.consent_marketing,
      consent_personalization: q.consent_personalization,
      consent_newsletter: q.consent_newsletter,
      onboarding_answers: answers,
      updated_at: new Date().toISOString(),
    }, { onConflict:'user_id' });
  } catch (err) {
    console.warn('[Apex] Questionario onboarding salvato solo localmente:', err);
  }
}

function buildFallbackProfile(user, onboardingCompleted = false) {
  const username = getDefaultUsernameFromUser(user);
  const local = normalizeProfileQuestionnaire(getProfileDemographicsLocal(user?.id));
  const baseOnboarding = onboardingCompleted || Boolean(local.onboarding_completed);
  return mergeProfileDemographics({
    user_id: user?.id,
    username,
    nickname: username,
    onboarding_completed: baseOnboarding,
    has_completed_tutorial: Boolean(local.has_completed_tutorial),
    first_login_reward_shown: false,
  }, user?.id);
}

async function fetchAnimalsFromSupabase(userId) {
  const { data: animals, error: animalsError } = await supabase
    .from('animals')
    .select(`
      *,
      animal_geo (*)
    `);

  if (animalsError) throw animalsError;

  const { data: userAnimals, error: userAnimalsError } = await supabase
    .from('user_animals')
    .select('*')
    .eq('user_id', userId);

  if (userAnimalsError) throw userAnimalsError;

  const userAnimalsById = Object.fromEntries((userAnimals || []).map(row => [row.animal_id, row]));
  return (animals || []).map(a => normalizeSupabaseAnimal(a, userAnimalsById[a.id]));
}

async function fetchUserAnimalStatusMap(userId) {
  const { data, error } = await supabase
    .from('user_animals')
    .select('animal_id, unlock_status')
    .eq('user_id', userId);

  if (error) throw error;
  return Object.fromEntries((data || [])
    .filter(row => row?.animal_id !== undefined && row?.animal_id !== null)
    .map(row => [String(row.animal_id), supabaseStatusToApp(row.unlock_status)]));
}

async function fetchUserDestinations(userId) {
  const { data, error } = await supabase
    .from('user_destinations')
    .select('iso')
    .eq('user_id', userId);
  if (error) throw error;
  return Array.from(new Set((data || []).map(r => String(r.iso || '').toUpperCase()).filter(Boolean))).sort();
}

async function saveUserAnimalStatus(userId, animal, status) {
  const nextAppStatus = normalizeAnimalStatus(status);
  const unlock_status = appStatusToSupabase(nextAppStatus);
  const now = new Date().toISOString();
  const existing = animal?.userAnimal || null;
  const payload = {
    user_id: userId,
    animal_id: animal.id,
    unlock_status,
    updated_at: now,
  };

  if (unlock_status !== 'locked' && !existing?.unlocked_at) payload.unlocked_at = now;
  if (unlock_status === 'seen') payload.seen_at = now;
  if (unlock_status === 'collected') payload.collected_at = now;

  const { error } = await supabase
    .from('user_animals')
    .upsert(payload, { onConflict:'user_id,animal_id' });
  if (error) throw error;
  return true;
}

async function saveUserAnimalDocumented(userId, animalId, documentedAt) {
  if (!userId || !animalId) return false;
  const now = new Date().toISOString();
  const { error } = await supabase
    .from('user_animals')
    .upsert({ user_id:userId, animal_id:animalId, documented_at:documentedAt || now, updated_at:now }, { onConflict:'user_id,animal_id' });
  if (error) throw error;
  return true;
}

async function fetchUserDocumentedMap(userId) {
  if (!userId) return {};
  const { data, error } = await supabase
    .from('user_animals')
    .select('animal_id,documented_at')
    .eq('user_id', userId)
    .not('documented_at', 'is', null);
  if (error) throw error;
  const map = {};
  for (const row of data || []) {
    if (row?.animal_id && row?.documented_at) map[String(row.animal_id)] = row.documented_at;
  }
  return map;
}

async function fetchUserExpeditions(userId) {
  if (!userId) return null;
  const { data, error } = await supabase
    .from('user_expeditions')
    .select('country_iso,revealed_waves,activated_at')
    .eq('user_id', userId);
  if (error) throw error;
  const map = {};
  for (const row of data || []) {
    const iso = String(row?.country_iso || '').toUpperCase();
    if (!iso) continue;
    map[iso] = { revealedWaves:Math.max(0, Number(row.revealed_waves ?? 1)), activatedAt:row.activated_at || null };
  }
  return map;
}

async function saveUserExpeditions(userId, state = {}) {
  if (!userId) return false;
  const now = new Date().toISOString();
  const rows = Object.entries(state || {}).map(([iso, entry]) => ({
    user_id: userId,
    country_iso: String(iso).toUpperCase(),
    revealed_waves: Math.max(0, Number(entry?.revealedWaves ?? 1)),
    activated_at: entry?.activatedAt || null,
    updated_at: now,
  })).filter(r => r.country_iso);
  if (!rows.length) return false;
  const { error } = await supabase
    .from('user_expeditions')
    .upsert(rows, { onConflict:'user_id,country_iso' });
  if (error) throw error;
  return true;
}

// Merge di due stati spedizione: vince sempre il progresso maggiore per paese.
function mergeExpeditionStates(...states) {
  const merged = {};
  for (const state of states) {
    for (const [iso, entry] of Object.entries(state || {})) {
      const code = String(iso).toUpperCase();
      const prev = merged[code];
      if (!prev || Number(entry?.revealedWaves ?? 0) > Number(prev?.revealedWaves ?? 0)) {
        merged[code] = { ...prev, ...entry };
      }
    }
  }
  return merged;
}

async function syncLocalStatusMapToSupabase(userId, statusMap = {}) {
  if (!userId || !statusMap || !Object.keys(statusMap).length) return false;
  const now = new Date().toISOString();
  const rows = Object.entries(statusMap)
    .map(([animalId, status]) => {
      const appStatus = normalizeAnimalStatus(status);
      const unlock_status = appStatusToSupabase(appStatus);
      if (unlock_status === 'locked') return null;
      const row = {
        user_id:userId,
        animal_id:Number(animalId),
        unlock_status,
        unlocked_at:now,
        updated_at:now,
      };
      if (unlock_status === 'seen') row.seen_at = now;
      if (unlock_status === 'collected') row.collected_at = now;
      return Number.isFinite(row.animal_id) ? row : null;
    })
    .filter(Boolean);
  if (!rows.length) return false;
  const { error } = await supabase
    .from('user_animals')
    .upsert(rows, { onConflict:'user_id,animal_id' });
  if (error) throw error;
  return true;
}

async function unlockAnimalsForDestinationClient(userId, iso, animals = []) {
  const cleanIso = String(iso || '').toUpperCase().trim();
  if (!userId || !cleanIso) return 0;
  const now = new Date().toISOString();
  const animalIds = Array.from(new Set((animals || [])
    .filter(animal => getAnimalCountryCodes(animal).includes(cleanIso))
    .map(animal => Number(animal?.id))
    .filter(Number.isFinite)));
  if (!animalIds.length) return 0;
  const { data: existingRows, error: existingError } = await supabase
    .from('user_animals')
    .select('animal_id, unlock_status')
    .eq('user_id', userId)
    .in('animal_id', animalIds);
  if (existingError) throw existingError;
  const existingStatus = new Map((existingRows || []).map(row => [Number(row.animal_id), String(row.unlock_status || 'locked')]));
  const rows = animalIds
    .filter(animalId => !existingStatus.has(animalId) || existingStatus.get(animalId) === 'locked')
    .map(animalId => ({
      user_id:userId,
      animal_id:animalId,
      unlock_status:'unlocked',
      unlocked_at:now,
      updated_at:now,
    }));
  if (!rows.length) return 0;
  const { error } = await supabase
    .from('user_animals')
    .upsert(rows, { onConflict:'user_id,animal_id' });
  if (error) throw error;
  return rows.length;
}

async function fetchUserBadgeIds(userId) {
  const { data, error } = await supabase
    .from('user_badges')
    .select('badge_id')
    .eq('user_id', userId);

  if (error) throw error;
  return Array.from(new Set((data || []).map(row => normalizeBadgeId(row.badge_id)).filter(Boolean)));
}

async function persistEarnedBadges(userId, badgeIds = []) {
  const cleanIds = filterPersistableBadgeIds(badgeIds);
  if (!userId || !cleanIds.length) return [];

  const { data: existingRows, error: existingError } = await supabase
    .from('user_badges')
    .select('badge_id')
    .eq('user_id', userId)
    .in('badge_id', cleanIds);

  if (existingError) throw existingError;

  const existing = new Set((existingRows || []).map(row => normalizeBadgeId(row.badge_id)));
  const missing = cleanIds.filter(id => !existing.has(id));
  if (!missing.length) return cleanIds;

  const now = new Date().toISOString();
  const payload = missing.map(badge_id => ({
    user_id: userId,
    badge_id,
    earned_at: now,
  }));

  const { error } = await supabase
    .from('user_badges')
    .upsert(payload, { onConflict:'user_id,badge_id' });

  if (error) throw error;
  return cleanIds;
}

async function persistUserDestination(userId, iso, tripTags = []) {
  const cleanIso = String(iso || '').toUpperCase().trim();
  if (!userId || !cleanIso) return false;

  const { error } = await supabase
    .from('user_destinations')
    .insert({
      user_id: userId,
      iso: cleanIso,
      trip_tags: tripTags,
      visited_at: new Date().toISOString().slice(0,10),
    });

  // 23505 = duplicate key. Se hai una unique(user_id, iso, visited_at) o simile,
  // non blocchiamo la RPC: la destinazione risulta già registrata.
  if (error && error.code !== '23505') throw error;
  return true;
}

async function removeUserDestination(userId, iso) {
  const cleanIso = String(iso || '').toUpperCase().trim();
  if (!userId || !cleanIso) return false;
  const { error } = await supabase
    .from('user_destinations')
    .delete()
    .eq('user_id', userId)
    .eq('iso', cleanIso);
  if (error) throw error;
  return true;
}

function normalizeSocialProfile(row = {}) {
  const profile = row.profile || row;
  const username = profile?.username || profile?.nickname || String(profile?.email || 'esploratore').split('@')[0] || 'esploratore';
  return {
    user_id: profile?.user_id || profile?.id || row.user_id || row.id,
    username,
    nickname: profile?.nickname || username,
    avatar_url: profile?.avatar_url || '',
    featured_badge_id: normalizeBadgeId(profile?.featured_badge_id || ''),
    profile_background_image: normalizeProfileBackgroundImage(profile?.profile_background_image || ''),
  };
}

function getDefaultUsernameFromUser(user) {
  return String(user?.email || 'esploratore').split('@')[0].trim() || 'esploratore';
}

function sanitizeSocialSearchQuery(query) {
  return String(query || '')
    .trim()
    .replace(/^@+/, '')
    .replace(/[%(),"'\\*]/g, '')
    .replace(/\s+/g, ' ')
    .slice(0, 40);
}

