  const ids = mapIds?.length ? mapIds : (item?.bioregionIds || (item?.bioregionId ? [item.bioregionId] : []));
  const coverSources = getRegionCoverSources(item, image || item?.image);
  const shouldRenderInlineMap = !onMapFocus && flipped;
