const INSTALL_GUIDE_DISMISSED_KEY = 'apex_install_guide_dismissed_v1';

function isRunningAsInstalledApp() {
  if (typeof window === 'undefined') return false;
  const standaloneMedia = typeof window.matchMedia === 'function' && window.matchMedia('(display-mode: standalone)').matches;
  const iosStandalone = typeof window.navigator !== 'undefined' && window.navigator.standalone === true;
  return Boolean(standaloneMedia || iosStandalone);
}

function detectInstallGuideProfile() {
  if (typeof navigator === 'undefined') {
    return {
      key: 'desktop',
      title: 'Installa Apex',
      intro: 'Apex funziona meglio quando lo apri dalla schermata Home: avvio rapido, schermo pieno e meno distrazioni del browser.',
      bullets: [
        'Apri il menu del browser o l’icona di installazione nella barra.',
        'Scegli Installa app o Aggiungi alla schermata Home.',
        'Riapri Apex dalla nuova icona per giocare a schermo pieno.',
      ],
      primaryLabel: 'Ho capito',
      canUseNativePrompt: true,
    };
  }
  const ua = navigator.userAgent || '';
  const platform = navigator.platform || '';
  const isiOS = /iPad|iPhone|iPod/i.test(ua) || (platform === 'MacIntel' && Number(navigator.maxTouchPoints || 0) > 1);
  const isAndroid = /Android/i.test(ua);
  const isCriOS = /CriOS/i.test(ua);
  const isFxiOS = /FxiOS/i.test(ua);
  const isEdgiOS = /EdgiOS/i.test(ua);
  const isSafari = isiOS && /Safari/i.test(ua) && !isCriOS && !isFxiOS && !isEdgiOS;
  const isChromium = /Chrome|Chromium|Edg|OPR|CriOS/i.test(ua);

  if (isiOS && isSafari) {
    return {
      key: 'ios-safari',
      title: 'Aggiungi Apex alla Home',
      intro: 'Su iPhone Apex diventa più stabile e pulita se la apri come app dalla schermata Home.',
      bullets: [
        'Tocca Condividi nella barra di Safari.',
        'Scorri le azioni e scegli Aggiungi alla schermata Home.',
        'Conferma con Aggiungi, poi apri Apex dalla nuova icona.',
      ],
      primaryLabel: 'Ho capito',
      canUseNativePrompt: false,
    };
  }

  if (isiOS) {
    return {
      key: 'ios-other',
      title: 'Installa da Safari',
      intro: 'iOS permette l’aggiunta alla Home solo da Safari. Ti basta aprire questo link in Safari una volta.',
      bullets: [
        'Apri il menu del browser e scegli Apri in Safari, oppure copia il link.',
        'In Safari tocca Condividi.',
        'Scegli Aggiungi alla schermata Home e conferma.',
      ],
      primaryLabel: 'Ho capito',
      canUseNativePrompt: false,
    };
  }

  if (isAndroid) {
    return {
      key: 'android',
      title: 'Installa Apex sul telefono',
      intro: 'Da Android puoi installare Apex come web app: parte più velocemente e resta dentro un’interfaccia più ordinata.',
      bullets: [
        'Tocca il menu del browser con i tre puntini.',
        'Scegli Installa app o Aggiungi alla schermata Home.',
        'Apri Apex dalla nuova icona per continuare il Dex.',
      ],
      primaryLabel: 'Installa se disponibile',
      canUseNativePrompt: isChromium,
    };
  }

  return {
    key: 'desktop',
    title: 'Installa Apex',
    intro: 'Puoi tenere Apex come app separata dal browser. Su smartphone l’esperienza è ancora più naturale.',
    bullets: [
      'Nel browser cerca l’icona Installa nella barra indirizzi o nel menu.',
      'Conferma l’installazione dell’app.',
      'Per il gioco quotidiano, aggiungila anche alla Home del telefono.',
    ],
    primaryLabel: 'Installa se disponibile',
    canUseNativePrompt: isChromium,
  };
}

function InstallGuidePreview({ profileKey }) {
  const isAndroid = profileKey === 'android';
  const isDesktop = profileKey === 'desktop';
  const isOtherIos = profileKey === 'ios-other';
  const browserLabel = isAndroid ? 'Chrome' : isDesktop ? 'Browser' : isOtherIos ? 'Safari' : 'Safari';
  const steps = isAndroid
    ? [
        { label:'Menu', control:'⋮', caption:'Apri il menu' },
        { label:'Installa app', control:'Installa app', caption:'Tocca installa' },
        { label:'Home', control:'Apex', caption:'Apri dalla Home' },
      ]
    : isDesktop
      ? [
          { label:'Barra', control:'+', caption:'Cerca installa' },
          { label:'Installa Apex', control:'Installa', caption:'Conferma' },
          { label:'App', control:'Apex', caption:'Apri separata' },
        ]
      : [
          { label:isOtherIos ? 'Safari' : 'Condividi', control:'↑', caption:isOtherIos ? 'Apri in Safari' : 'Tocca Condividi' },
          { label:'Aggiungi alla Home', control:'Aggiungi', caption:'Scegli l’azione' },
          { label:'Home', control:'Apex', caption:'Apri dalla Home' },
        ];

  return (
    <div aria-hidden="true" style={{ marginTop:14 }}>
      <style>{`
        @keyframes apexInstallFocus {
          0%, 25% { opacity: .28; transform: scale(.98); }
          33%, 58% { opacity: 1; transform: scale(1); }
          66%, 100% { opacity: .28; transform: scale(.98); }
        }
        @keyframes apexInstallTap {
          0%, 23% { opacity: 0; transform: translate3d(18px, 18px, 0) scale(.82); }
          32%, 48% { opacity: 1; transform: translate3d(0, 0, 0) scale(1); }
          55%, 100% { opacity: 0; transform: translate3d(-8px, -8px, 0) scale(.9); }
        }
        @keyframes apexInstallGlow {
          0%, 100% { box-shadow: 0 0 0 0 rgba(240,168,64,.0); }
          42%, 56% { box-shadow: 0 0 0 5px rgba(240,168,64,.18), 0 0 24px rgba(240,168,64,.30); }
        }
      `}</style>
      <div style={{ borderRadius:24, border:'1px solid rgba(255,255,255,.12)', background:'linear-gradient(180deg,#24252A,#111215)', padding:10, boxShadow:'inset 0 1px 0 rgba(255,255,255,.06)' }}>
        <div style={{ height:22, borderRadius:10, background:'rgba(255,255,255,.08)', display:'flex', alignItems:'center', justifyContent:'space-between', padding:'0 8px', color:'rgba(255,255,255,.68)', fontSize:8.5, fontWeight:1000 }}>
          <span>{browserLabel}</span>
          <span style={{ width:78, height:8, borderRadius:99, background:'rgba(255,255,255,.14)' }} />
          <span style={{ color:'#F0CFA5', fontSize:14, lineHeight:1 }}>{isAndroid ? '⋮' : '+'}</span>
        </div>

        <div style={{ display:'grid', gridTemplateColumns:'repeat(3, 1fr)', gap:8, marginTop:10 }}>
          {steps.map((step, index) => (
            <div key={step.label} style={{ position:'relative', minHeight:118, borderRadius:18, background:index === 2 ? 'linear-gradient(180deg,rgba(240,168,64,.18),rgba(255,255,255,.05))' : 'rgba(255,255,255,.045)', border:index === 2 ? '1px solid rgba(240,168,64,.30)' : '1px solid rgba(255,255,255,.09)', padding:8, overflow:'hidden', animation:`apexInstallFocus 4.8s ease-in-out ${index * 1.6}s infinite` }}>
              <div style={{ height:9, width:index === 0 ? '68%' : '82%', borderRadius:99, background:'rgba(255,255,255,.16)', marginBottom:7 }} />
              <div style={{ height:8, width:'52%', borderRadius:99, background:'rgba(255,255,255,.10)', marginBottom:12 }} />
              <div style={{ minHeight:44, borderRadius:index === 2 ? 14 : 13, background:index === 2 ? 'linear-gradient(135deg,#B84D3A,#F0A840)' : 'rgba(0,0,0,.30)', border:'1px solid rgba(255,255,255,.11)', display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontSize:index === 1 && String(step.control).length > 8 ? 9.5 : 17, fontWeight:1000, textAlign:'center', padding:'0 5px', animation:`apexInstallGlow 4.8s ease-in-out ${index * 1.6}s infinite` }}>
                {step.control}
              </div>
              <div style={{ marginTop:9, color:'#F0CFA5', fontSize:8.8, fontWeight:1000, lineHeight:1.12 }}>{step.caption}</div>
              <div style={{ position:'absolute', right:7, bottom:7, width:17, height:17, borderRadius:'50%', background:'rgba(255,255,255,.94)', color:'#211512', display:'flex', alignItems:'center', justifyContent:'center', fontSize:10, fontWeight:1000, animation:`apexInstallTap 4.8s ease-in-out ${index * 1.6}s infinite` }}>•</div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

function InstallPromptBanner({ suppressed = false }) {
  const [profile] = useState(() => detectInstallGuideProfile());
  const [online, setOnline] = useState(() => typeof navigator === 'undefined' ? true : navigator.onLine !== false);
  const [dismissed, setDismissed] = useState(() => {
    try { return typeof localStorage !== 'undefined' && localStorage.getItem(INSTALL_GUIDE_DISMISSED_KEY) === '1'; }
    catch { return false; }
  });
  const [deferredPrompt, setDeferredPrompt] = useState(null);

  useEffect(() => {
    const handleOnline = () => setOnline(true);
    const handleOffline = () => setOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  useEffect(() => {
    const handleBeforeInstallPrompt = (event) => {
      event.preventDefault?.();
      setDeferredPrompt(event);
    };
    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
    return () => window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt);
  }, []);

  const close = () => {
    try { localStorage.setItem(INSTALL_GUIDE_DISMISSED_KEY, '1'); } catch {}
    setDismissed(true);
  };

  const installOrClose = async () => {
    if (profile.canUseNativePrompt && deferredPrompt?.prompt) {
      try {
        await deferredPrompt.prompt();
        await deferredPrompt.userChoice;
      } catch {}
      setDeferredPrompt(null);
    }
    close();
  };

  if (suppressed || dismissed || !online || isRunningAsInstalledApp()) return null;

  return (
    <div style={{ position:'absolute', inset:0, zIndex:390, pointerEvents:'none', display:'flex', alignItems:'flex-end', justifyContent:'center', padding:'0 14px calc(env(safe-area-inset-bottom, 0px) + 14px)' }}>
      <div style={{ width:'100%', maxWidth:440, pointerEvents:'auto', borderRadius:28, background:'linear-gradient(180deg,rgba(31,31,35,.98),rgba(13,13,15,.99))', border:'1px solid rgba(240,168,64,.28)', boxShadow:'0 26px 80px rgba(0,0,0,.58), inset 0 1px 0 rgba(255,255,255,.06)', padding:16, color:'white' }}>
        <div style={{ display:'flex', gap:12, alignItems:'flex-start' }}>
          <div style={{ width:48, height:48, borderRadius:18, background:'linear-gradient(135deg,#B84D3A,#F0A840)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:24, fontWeight:1000, flexShrink:0 }}>A</div>
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ color:'#F0A840', fontSize:11, fontWeight:1000, letterSpacing:.8, textTransform:'uppercase' }}>Prima apertura online</div>
            <div style={{ marginTop:3, fontSize:21, lineHeight:1.1, fontWeight:1000 }}>{profile.title}</div>
            <div style={{ marginTop:8, color:'rgba(255,245,232,.72)', fontSize:12.5, lineHeight:1.42 }}>{profile.intro}</div>
          </div>
          <button type="button" aria-label="Chiudi guida installazione" onClick={close} style={{ width:38, height:38, borderRadius:14, border:'1px solid rgba(255,255,255,.10)', background:'rgba(255,255,255,.055)', color:'rgba(255,255,255,.72)', fontSize:24, lineHeight:1, cursor:'pointer', flexShrink:0 }}>×</button>
        </div>

        <InstallGuidePreview profileKey={profile.key} />

        <ul style={{ margin:'14px 0 0', padding:'0 0 0 19px', color:'rgba(255,245,232,.82)', fontSize:12.5, lineHeight:1.45 }}>
          {profile.bullets.map((bullet) => <li key={bullet} style={{ marginBottom:6 }}>{bullet}</li>)}
        </ul>

        <div style={{ display:'flex', gap:10, marginTop:14 }}>
          <button type="button" onClick={close} style={{ flex:1, height:46, borderRadius:15, border:'1px solid rgba(255,255,255,.10)', background:'rgba(255,255,255,.05)', color:'rgba(255,245,232,.78)', fontWeight:950, fontFamily:'inherit', cursor:'pointer' }}>Più tardi</button>
          <button type="button" onClick={installOrClose} style={{ flex:1.25, height:46, borderRadius:15, border:'none', background:'linear-gradient(135deg,#B84D3A,#F0A840)', color:'white', fontWeight:1000, fontFamily:'inherit', cursor:'pointer', boxShadow:'0 14px 32px rgba(184,77,58,.32)' }}>{profile.primaryLabel}</button>
        </div>
      </div>
    </div>
  );
}


const CountrySelectButton = React.memo(function CountrySelectButton({ code, name, flag, active, accent = '#A84637', activeBg = 'rgba(168,70,55,.22)', onToggle }) {
  return (
    <button type="button" onClick={() => onToggle(code)} style={{ minHeight:48, borderRadius:17, border:`1px solid ${active ? accent : 'rgba(255,255,255,.08)'}`, background:active ? activeBg : 'rgba(255,255,255,.045)', color:'white', display:'flex', alignItems:'center', gap:8, padding:'8px 10px', cursor:'pointer', textAlign:'left', fontFamily:'inherit', touchAction:'manipulation' }}>
      <span style={{ fontSize:21 }}>{flag}</span>
      <span style={{ flex:1, fontSize:11.5, fontWeight:900, lineHeight:1.15 }}>{name}</span>
      <span style={{ color:active ? '#FFD4C8' : 'rgba(255,255,255,.22)', fontWeight:1000 }}>{active ? '✓' : '+'}</span>
    </button>
  );
});

const RegionsCountrySelectButton = React.memo(function RegionsCountrySelectButton({ code, name, flag, active, onToggle }) {
  return (
    <button type="button" onClick={() => onToggle(code)} style={{ minHeight:44, borderRadius:12, border:`1px solid ${active ? 'rgba(144,216,74,.65)' : 'rgba(255,255,255,.08)'}`, background:active ? 'rgba(144,216,74,.18)' : '#1A1A1C', color:active ? '#D8FFC4' : 'white', padding:'8px 10px', display:'flex', alignItems:'center', gap:8, cursor:'pointer', textAlign:'left', fontFamily:'inherit', touchAction:'manipulation' }}>
      <span style={{ fontSize:20 }}>{flag}</span>
      <span style={{ flex:1, fontSize:11.5, fontWeight:800, lineHeight:1.15 }}>{name}</span>
      <span style={{ color:active ? '#90D84A' : 'rgba(255,255,255,.22)', fontSize:15 }}>{active ? '✓' : '+'}</span>
    </button>
  );
});

function OnboardingFlow({ user, animals = [], initialNickname='', onComplete, onFinish }) {
  const OCHRE = '#A84637';
  const [step,setStep]=useState('intro');
  const [nickname,setNickname]=useState(initialNickname || String(user?.email || 'utente').split('@')[0] || 'Esploratore');
  const [countrySearch,setCountrySearch]=useState('');
  const [selectedCountries,setSelectedCountries]=useState([]);
  const [selectedTripTags,setSelectedTripTags]=useState(['nature']);
  const [gender,setGender]=useState('');
  const [nationality,setNationality]=useState('');
  const [phone,setPhone]=useState('');
  const [dateOfBirth,setDateOfBirth]=useState('');
  const [residenceCountry,setResidenceCountry]=useState('');
  const [objectives,setObjectives]=useState([]);
  const [objectiveOther,setObjectiveOther]=useState('');
  const [consents,setConsents]=useState({ terms:false, analytics:false, marketing:false, personalization:false, newsletter:false });
  const [showProfileExtras,setShowProfileExtras]=useState(false);
  const [cardIndex,setCardIndex]=useState(0);
  const [seenAnimals,setSeenAnimals]=useState([]);
  const [loading,setLoading]=useState(false);
  const [syncing,setSyncing]=useState(false);
  const [result,setResult]=useState(null);
  const [error,setError]=useState('');
  const [showImprobabili,setShowImprobabili]=useState(false);

  useEffect(() => { setShowImprobabili(false); }, [residenceCountry]);

  const steps = ['intro','profile','intent','countries','radar','wow'];
  const stepIndex = Math.max(0, steps.indexOf(step));
  const progress = Math.round(((stepIndex + 1) / steps.length) * 100);
  const allCountries = useMemo(() => normalizeIsoList(getAllScratchCountries()), []);
  const countryNameCompare = useCallback((a, b) => getCountryDisplayName(a).localeCompare(getCountryDisplayName(b), 'it'), []);
  const countryMetaByCode = useMemo(() => {
    const map = new Map();
    for (const code of allCountries) {
      map.set(code, { code, name: getCountryDisplayName(code), flag: getFlagEmoji(code) });
    }
    return map;
  }, [allCountries]);
  const animalsByCountryIndex = useMemo(() => buildAnimalIdsByCountryIndex(animals), [animals]);
  const selectedCountrySet = useMemo(() => new Set(selectedCountries.map(c => String(c).toUpperCase())), [selectedCountries]);
  const deferredSelectedCountries = useDeferredValue(selectedCountries);
  const onboardingCountryGroups = useMemo(
    () => buildOnboardingCountryGroups(residenceCountry, allCountries).map(group => ({
      ...group,
      countries: (group.key === 'molto_probabili'
        ? group.countries
        : [...group.countries].sort(countryNameCompare)
      ).map(code => countryMetaByCode.get(code) || { code, name: getCountryDisplayName(code), flag: getFlagEmoji(code) }),
    })),
    [residenceCountry, allCountries, countryNameCompare, countryMetaByCode]
  );
  const filteredCountries = useMemo(() => {
    const q = countrySearch.trim().toLowerCase();
    if (!q) return [];
    return allCountries
      .filter(code => getCountryDisplayName(code).toLowerCase().includes(q) || code.toLowerCase().includes(q))
      .sort(countryNameCompare)
      .map(code => countryMetaByCode.get(code) || { code, name: getCountryDisplayName(code), flag: getFlagEmoji(code) });
  }, [allCountries, countrySearch, countryNameCompare, countryMetaByCode]);
  const animalCount = animals?.length || LOCAL_ANIMALS.length;
  const classCount = new Set((animals?.length ? animals : LOCAL_ANIMALS).map(a => a.cls).filter(Boolean)).size;
  const countryCount = allCountries.length;
  const RADAR_TARGET = 6;

  const radarAnimals = useMemo(() => {
    if (step !== 'radar' || !selectedCountries.length) return [];
    const normalizedAnimals = animals.map(a => ({ ...(LOCAL_ANIMALS.find(x => Number(x.id) === Number(a.id)) || {}), ...a })).filter(a => a.image_url);
    const byCountry = selectedCountries.map(code => normalizedAnimals
      .filter(a => getAnimalCountryCodes(a).includes(String(code).toUpperCase()))
      .sort((a,b) => (RARITY[a.rarity]?.s || 1) - (RARITY[b.rarity]?.s || 1) || (b.obs_count || b.observations || 0) - (a.obs_count || a.observations || 0))
    );
    const picked = [];
    const seen = new Set();
    for (let round = 0; picked.length < RADAR_TARGET && round < 40; round++) {
      for (const list of byCountry) {
        const next = list.find(a => !seen.has(Number(a.id)));
        if (next) {
          seen.add(Number(next.id));
          picked.push(next);
          if (picked.length >= RADAR_TARGET) break;
        }
      }
      if (byCountry.every(list => list.every(a => seen.has(Number(a.id))))) break;
    }
    if (picked.length < RADAR_TARGET) {
      const selectedSet = new Set(selectedCountries.map(c => String(c).toUpperCase()));
      normalizedAnimals
        .filter(a => getAnimalCountryCodes(a).some(code => selectedSet.has(code)))
        .forEach(a => { if (picked.length < RADAR_TARGET && !seen.has(Number(a.id))) { seen.add(Number(a.id)); picked.push(a); } });
    }
    return picked.slice(0, RADAR_TARGET);
  }, [step, animals, selectedCountries]);

  const currentAnimal = radarAnimals[cardIndex] || null;
  const predictedUnlocks = useMemo(
    () => countAnimalsForCountrySelection(deferredSelectedCountries, animalsByCountryIndex),
    [deferredSelectedCountries, animalsByCountryIndex]
  );

  const toggleCountry = useCallback((code) => {
    setSelectedCountries(prev => toggleIsoCode(prev, code));
  }, []);
  const enterCountries = () => {
    if (residenceCountry && !selectedCountries.length) setSelectedCountries([residenceCountry]);
    setStep('countries');
  };

  const markRadar = (seen) => {
    if (seen && currentAnimal) setSeenAnimals(prev => Array.from(new Set([...prev, currentAnimal.id])));
    setCardIndex(i => i + 1);
  };
  const goBack = () => {
    if (step === 'intro' || step === 'wow') return;
    const idx = steps.indexOf(step);
    if (idx > 0) setStep(steps[idx - 1]);
  };

  const runSync = async () => {
    setLoading(true);
    setSyncing(true);
    setError('');
    setStep('wow');
    const payload = { nickname, countries:normalizeIsoList(selectedCountries), seenAnimalIds:Array.from(new Set(seenAnimals)), tripTags:selectedTripTags, demographics:{
      gender,
      nationality,
      phone,
      date_of_birth:dateOfBirth,
      residence_country:residenceCountry,
      onboarding_objectives:objectives,
      onboarding_objective_other:objectiveOther,
      acquisition_source:'',
      acquisition_source_other:'',
      water_activity_interests:[],
      is_collector:null,
      annual_abroad_vacations:'',
      pokemon_affinity:'',
      consent_terms_privacy:consents.terms,
      consent_analytics:consents.analytics,
      consent_marketing:consents.marketing,
      consent_personalization:consents.personalization,
      consent_newsletter:consents.newsletter,
    } };
    try {
      const timeoutResult = {
        ok:true,
        timed_out:true,
        unlocked_count:Math.max(predictedUnlocks, selectedCountries.length),
        seen_count:seenAnimals.length,
        badge_ids:['ONB-01-L1'],
      };
      const data = await Promise.race([
        Promise.resolve(onComplete?.(payload)),
        new Promise(resolve => setTimeout(() => resolve(timeoutResult), 5000))
      ]);
      setResult(data || timeoutResult);
    } catch (err) {
      console.warn('[Apex] Onboarding sync failed:', err);
      setError(err?.message || 'Sincronizzazione non completata. Puoi riprovare o continuare: Apex tenterà di salvare in background.');
      setResult({ ok:false, unlocked_count:Math.max(predictedUnlocks, selectedCountries.length), seen_count:seenAnimals.length, badge_ids:['ONB-01-L1'] });
    } finally {
      setLoading(false);
      setSyncing(false);
    }
  };

  const panel = { margin:16, borderRadius:30, background:'linear-gradient(180deg,rgba(255,255,255,.065),rgba(255,255,255,.035))', border:'1px solid rgba(255,255,255,.10)', padding:18, boxShadow:'0 28px 80px rgba(0,0,0,.46)', overflowY:'auto', WebkitOverflowScrolling:'touch' };
  const primaryButton = { width:'100%', minHeight:50, borderRadius:18, border:'none', background:`linear-gradient(135deg,${OCHRE},#C45D3F)`, color:'white', fontWeight:1000, cursor:'pointer', fontFamily:'inherit', boxShadow:`0 14px 34px ${OCHRE}38` };
  const disabledButton = { ...primaryButton, background:'#3A3A3C', color:'rgba(255,255,255,.42)', boxShadow:'none', cursor:'default' };
  const Pill = ({ children, active=false, onClick }) => <button onClick={onClick} style={{ borderRadius:999, border:`1px solid ${active?OCHRE:'rgba(255,255,255,.10)'}`, background:active?`rgba(168,70,55,.22)`:'rgba(255,255,255,.055)', color:active?'#FFD4C8':'rgba(255,255,255,.74)', padding:'8px 11px', fontSize:11.5, fontWeight:900, cursor:'pointer', fontFamily:'inherit' }}>{children}</button>;
  const ObjectivePill = ({ value, label }) => <Pill active={objectives.includes(value)} onClick={()=>setObjectives(prev => prev.includes(value) ? prev.filter(x=>x!==value) : [...prev, value])}>{label}</Pill>;
  const ConsentRow = ({ keyName, label, required=false }) => <button type="button" onClick={()=>setConsents(prev => ({ ...prev, [keyName]:!prev[keyName] }))} style={{ display:'flex', alignItems:'center', gap:10, width:'100%', border:'1px solid rgba(255,255,255,.08)', borderRadius:14, background:'rgba(255,255,255,.045)', padding:'10px 12px', color:'white', fontFamily:'inherit', textAlign:'left' }}>
    <span style={{ width:22, height:22, borderRadius:8, background:consents[keyName]?OCHRE:'rgba(255,255,255,.08)', display:'flex', alignItems:'center', justifyContent:'center', fontWeight:1000 }}>{consents[keyName]?'✓':''}</span>
    <span style={{ flex:1, fontSize:12, color:'rgba(255,255,255,.72)', lineHeight:1.35 }}>{label} {required && <b style={{ color:'#FFD4C8' }}>*</b>}</span>
  </button>;

  return (
    <div style={{ height:'100%', background:`radial-gradient(circle at 50% 0%, ${OCHRE}2A, transparent 36%), linear-gradient(180deg,#111113,#050506)`, color:'white', display:'flex', flexDirection:'column', overflow:'hidden' }}>
      <div style={{ padding:'20px 18px 8px', flexShrink:0 }}>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', gap:12 }}>
          {step !== 'intro' && step !== 'wow' && <button onClick={goBack} aria-label="Indietro" style={{ width:38, height:38, borderRadius:14, border:'1px solid rgba(255,255,255,.10)', background:'rgba(255,255,255,.055)', color:'white', fontSize:22, fontWeight:1000, cursor:'pointer', flexShrink:0 }}>‹</button>}
          <div style={{ flex:1, minWidth:0 }}>
            <div style={{ color:OCHRE, fontSize:11, fontWeight:1000, letterSpacing:.9, textTransform:'uppercase' }}>Setup · {stepIndex + 1}/{steps.length}</div>
            <div style={{ color:'white', fontSize:28, fontWeight:1000, letterSpacing:'-.8px', marginTop:3 }}>
              {step==='intro'?'Benvenuto in Apex':step==='profile'?'Il tuo profilo':step==='intent'?'Cosa ti interessa':step==='countries'?'Sul Campo':step==='radar'?'Primi avvistamenti':'Il tuo atlante è pronto'}
            </div>
          </div>
          <div style={{ width:54, height:54, borderRadius:20, background:`linear-gradient(135deg,${OCHRE},#6F2D24)`, display:'flex', alignItems:'center', justifyContent:'center', fontSize:26, boxShadow:`0 0 32px ${OCHRE}44` }}>A</div>
        </div>
        <div style={{ height:8, background:'rgba(255,255,255,.08)', borderRadius:999, overflow:'hidden', marginTop:14 }}>
          <div style={{ width:`${progress}%`, height:'100%', background:`linear-gradient(90deg,${OCHRE},#F0A840)`, borderRadius:999, transition:'width .28s ease' }} />
        </div>
      </div>

      {step==='intro' && (
        <div style={{ ...panel, flex:1, display:'flex', flexDirection:'column', justifyContent:'space-between' }}>
          <div>
            <div style={{ color:OCHRE, fontSize:12, fontWeight:1000, textTransform:'uppercase', letterSpacing:.9 }}>Atlante vivo della fauna</div>
            <div style={{ color:'white', fontSize:27, fontWeight:1000, letterSpacing:'-.7px', lineHeight:1.06, marginTop:8 }}>Colleziona, esplora e impara gli animali del mondo.</div>
            <p style={{ color:'rgba(255,255,255,.68)', fontSize:13.5, lineHeight:1.6 }}>In meno di 2 minuti prepariamo il tuo atlante personale: profilo, paesi visitati e primi avvistamenti. Poi ti guidiamo brevemente nella griglia.</p>
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:10, marginTop:14 }}>
              {[
                [`${animalCount}`,'Specie','catalogo con rarità, biologia e geografia'],
                [`${countryCount}`,'Paesi','attivano la Spedizione e sbloccano fauna locale'],
                ['4','Stati','Misterioso → Ricercato → Avvistato → Catturato'],
                ['Badge','Progressi','obiettivi che trasformano l\'esplorazione in abitudine'],
              ].map(([ic,t,d])=>(
                <div key={t} style={{ borderRadius:20, background:'rgba(255,255,255,.055)', border:'1px solid rgba(255,255,255,.08)', padding:12 }}>
                  <div style={{ color:'#FFD4C8', fontSize:20, fontWeight:1000 }}>{ic}</div><div style={{ fontWeight:1000, fontSize:13, marginTop:5 }}>{t}</div><div style={{ color:'rgba(255,255,255,.50)', fontSize:10.5, lineHeight:1.3, marginTop:3 }}>{d}</div>
                </div>
              ))}
            </div>
          </div>
          <button onClick={()=>setStep('profile')} style={primaryButton}>Inizia in 2 minuti</button>
        </div>
      )}

      {step==='profile' && (
        <div style={{ ...panel, flex:1, display:'flex', flexDirection:'column', justifyContent:'space-between' }}>
          <div>
          <p style={{ color:'rgba(255,255,255,.66)', fontSize:13.5, lineHeight:1.6, marginTop:0 }}>Come ti chiami in Apex? Il paese di residenza ci aiuta a suggerirti fauna locale.</p>
          <div style={{ borderRadius:16, background:'rgba(255,255,255,.045)', border:'1px solid rgba(255,255,255,.08)', padding:12, marginBottom:12 }}>
            <div style={{ color:'rgba(255,255,255,.46)', fontSize:10.5, fontWeight:900, textTransform:'uppercase' }}>Account</div>
            <div style={{ color:'white', fontSize:13, fontWeight:900, marginTop:4 }}>{user?.email || 'Email non disponibile'}</div>
          </div>
          <label style={{ color:'rgba(255,255,255,.58)', fontSize:12, fontWeight:900 }}>Nickname</label>
          <input value={nickname} onChange={e=>setNickname(e.target.value)} placeholder="Es. Andrea" style={{ width:'100%', height:54, borderRadius:18, background:'#202024', border:`1px solid ${OCHRE}55`, color:'white', padding:'0 15px', fontSize:15, boxSizing:'border-box', outline:'none', fontFamily:'inherit', marginTop:8 }} />
          <label style={{ display:'block', color:'rgba(255,255,255,.58)', fontSize:12, fontWeight:900, marginTop:16 }}>Paese di residenza</label>
          <select value={residenceCountry} onChange={e=>setResidenceCountry(e.target.value)} style={{ width:'100%', height:54, borderRadius:18, background:'#202024', border:'1px solid rgba(255,255,255,.14)', color:'white', padding:'0 14px', fontSize:15, boxSizing:'border-box', fontFamily:'inherit', marginTop:8 }}>
            <option value="">Seleziona (consigliato)</option>
            {allCountries.map(code => <option key={code} value={code}>{getCountryDisplayName(code)}</option>)}
          </select>
          <button type="button" onClick={()=>setShowProfileExtras(v=>!v)} style={{ marginTop:14, border:'none', background:'transparent', color:'rgba(255,255,255,.52)', fontSize:12, fontWeight:900, cursor:'pointer', fontFamily:'inherit', textAlign:'left', padding:0 }}>{showProfileExtras ? '▾ Nascondi dettagli facoltativi' : '▸ Altri dettagli facoltativi'}</button>
          {showProfileExtras && (
            <div style={{ marginTop:10, display:'grid', gap:10 }}>
              <input type="date" value={dateOfBirth} onChange={e=>setDateOfBirth(e.target.value)} aria-label="Data di nascita" style={{ width:'100%', height:48, borderRadius:16, background:'#202024', border:'1px solid rgba(255,255,255,.14)', color:'white', padding:'0 14px', fontSize:14, boxSizing:'border-box', fontFamily:'inherit', colorScheme:'dark' }} />
              <select value={gender} onChange={e=>setGender(e.target.value)} style={{ width:'100%', height:48, borderRadius:16, background:'#202024', border:'1px solid rgba(255,255,255,.14)', color:'white', padding:'0 14px', fontSize:14, boxSizing:'border-box', fontFamily:'inherit' }}>
                <option value="">Genere (facoltativo)</option><option>Donna</option><option>Uomo</option><option>Non binario</option><option>Preferisco non dirlo</option>
              </select>
              <select value={nationality} onChange={e=>setNationality(e.target.value)} style={{ width:'100%', height:48, borderRadius:16, background:'#202024', border:'1px solid rgba(255,255,255,.14)', color:'white', padding:'0 14px', fontSize:14, boxSizing:'border-box', fontFamily:'inherit' }}>
                <option value="">Nazionalità (facoltativa)</option>
                {allCountries.map(code => <option key={`nat-${code}`} value={code}>{getCountryDisplayName(code)}</option>)}
              </select>
            </div>
          )}
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'auto 1fr', gap:10, marginTop:16 }}><button onClick={goBack} style={{ minHeight:50, borderRadius:18, border:'1px solid rgba(255,255,255,.12)', background:'rgba(255,255,255,.055)', color:'white', fontWeight:950, padding:'0 14px' }}>Indietro</button><button disabled={!nickname.trim()} onClick={()=>setStep('intent')} style={nickname.trim() ? primaryButton : disabledButton}>Continua</button></div>
        </div>
      )}

      {step==='intent' && (
        <div style={{ ...panel, flex:1, display:'flex', flexDirection:'column', justifyContent:'space-between' }}>
          <div>
            <p style={{ color:'rgba(255,255,255,.66)', fontSize:13.5, lineHeight:1.6, marginTop:0 }}>Scegli cosa vuoi da Apex. Useremo le tue preferenze per missioni e suggerimenti.</p>
            <div style={{ display:'flex', flexWrap:'wrap', gap:8 }}>
              <ObjectivePill value="collection" label="Collezionare specie" /><ObjectivePill value="travel" label="Preparare viaggi" /><ObjectivePill value="photo_ai" label="Riconoscere da foto" /><ObjectivePill value="education" label="Imparare biologia" /><ObjectivePill value="badges" label="Completare badge" /><ObjectivePill value="other" label="Altro" />
            </div>
            {objectives.includes('other') && <input value={objectiveOther} onChange={e=>setObjectiveOther(e.target.value)} placeholder="Scrivi il tuo obiettivo" style={{ width:'100%', height:48, borderRadius:16, background:'#202024', border:'1px solid rgba(255,255,255,.12)', color:'white', padding:'0 13px', fontSize:13, boxSizing:'border-box', outline:'none', fontFamily:'inherit', marginTop:12 }} />}
            <div style={{ color:'rgba(255,255,255,.55)', fontSize:11, fontWeight:900, margin:'18px 0 8px', textTransform:'uppercase' }}>Consensi</div>
            <div style={{ display:'grid', gap:7 }}>
              <ConsentRow keyName="terms" label="Accetto termini, privacy e trattamento dati necessario al funzionamento di Apex" required />
              <ConsentRow keyName="analytics" label="Analytics anonimi per migliorare stabilità e prodotto" />
              <ConsentRow keyName="marketing" label="Comunicazioni su novità e funzioni premium" />
            </div>
            <div style={{ marginTop:14, borderRadius:16, background:'rgba(168,70,55,.10)', border:'1px solid rgba(168,70,55,.20)', padding:11, color:'rgba(255,255,255,.62)', fontSize:11.5, lineHeight:1.4 }}>Ogni avvistamento e ogni badge costruiscono il tuo atlante. Più usi Apex, più la fauna del mondo diventa tua.</div>
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'auto 1fr', gap:10, marginTop:16 }}><button onClick={goBack} style={{ minHeight:50, borderRadius:18, border:'1px solid rgba(255,255,255,.12)', background:'rgba(255,255,255,.055)', color:'white', fontWeight:950, padding:'0 14px' }}>Indietro</button><button disabled={!consents.terms} onClick={enterCountries} style={consents.terms ? primaryButton : disabledButton}>Scegli i paesi</button></div>
        </div>
      )}

      {step==='countries' && (
        <div style={{ ...panel, flex:1, minHeight:0, display:'flex', flexDirection:'column' }}>
          <p style={{ color:'rgba(255,255,255,.66)', fontSize:13.5, lineHeight:1.55, marginTop:0 }}>Seleziona i paesi del tuo <strong style={{ color:'#90D84A', fontWeight:1000 }}>Sul Campo</strong> — dove sei stato davvero. All&apos;iscrizione puoi aggiungerne quanti vuoi: ogni paese attiva subito la prima ondata della Spedizione.</p>
          {residenceCountry && !countrySearch.trim() && (
            <div style={{ color:'rgba(255,255,255,.48)', fontSize:11, lineHeight:1.35, marginBottom:8 }}>Ordinati per probabilità di viaggio da {getCountryDisplayName(residenceCountry)}.</div>
          )}
          <input value={countrySearch} onChange={e=>setCountrySearch(e.target.value)} placeholder="Cerca nazione o ISO..." style={{ width:'100%', height:44, borderRadius:16, background:'#202024', border:'1px solid rgba(255,255,255,.12)', color:'white', padding:'0 13px', fontSize:14, boxSizing:'border-box', outline:'none', marginBottom:10, fontFamily:'inherit' }} />
          <div style={{ flex:1, overflowY:'auto', paddingRight:2 }}>
            {countrySearch.trim() ? (
              <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>
                {filteredCountries.map(({ code, name, flag }) => (
                  <CountrySelectButton
                    key={code}
                    code={code}
                    name={name}
                    flag={flag}
                    active={selectedCountrySet.has(code)}
                    accent={OCHRE}
                    onToggle={toggleCountry}
                  />
                ))}
              </div>
            ) : onboardingCountryGroups.map(group => {
              const collapsed = group.key === 'improbabili' && !showImprobabili;
              return (
                <div key={group.key} style={{ marginBottom:14 }}>
                  <button
                    type="button"
                    onClick={() => { if (group.key === 'improbabili') setShowImprobabili(v => !v); }}
                    style={{
                      display:'flex', alignItems:'center', justifyContent:'space-between', width:'100%',
                      border:'none', background:'transparent', padding:'0 0 8px', cursor: group.key === 'improbabili' ? 'pointer' : 'default',
                      fontFamily:'inherit', textAlign:'left',
                    }}
                  >
                    <span style={{ color: group.key === 'molto_probabili' ? OCHRE : 'rgba(255,255,255,.52)', fontSize:10.5, fontWeight:1000, letterSpacing:.7, textTransform:'uppercase' }}>
                      {group.label} · {group.countries.length}
                    </span>
                    {group.key === 'improbabili' && (
                      <span style={{ color:'rgba(255,255,255,.42)', fontSize:11, fontWeight:900 }}>{collapsed ? 'Mostra' : 'Nascondi'}</span>
                    )}
                  </button>
                  {!collapsed && (
                    <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>
                      {group.countries.map(({ code, name, flag }) => (
                        <CountrySelectButton
                          key={`${group.key}-${code}`}
                          code={code}
                          name={name}
                          flag={flag}
                          active={selectedCountrySet.has(code)}
                          accent={OCHRE}
                          onToggle={toggleCountry}
                        />
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'repeat(2,minmax(0,1fr))', gap:8, marginTop:12, width:'100%', maxWidth:'100%', boxSizing:'border-box' }}>
            <div style={{ borderRadius:18, background:'rgba(255,255,255,.055)', padding:12 }}><div style={{ color:OCHRE, fontWeight:1000, fontSize:18 }}>{selectedCountries.length}</div><div style={{ color:'rgba(255,255,255,.55)', fontSize:11 }}>nazioni</div></div>
            <div style={{ borderRadius:18, background:'rgba(255,255,255,.055)', padding:12 }}><div style={{ color:OCHRE, fontWeight:1000, fontSize:18 }}>{predictedUnlocks}</div><div style={{ color:'rgba(255,255,255,.55)', fontSize:11 }}>animali potenziali</div></div>
          </div>
          <div style={{ display:'grid', gridTemplateColumns:'auto 1fr', gap:8, marginTop:12 }}><button onClick={goBack} style={{ minHeight:50, borderRadius:18, border:'1px solid rgba(255,255,255,.12)', background:'rgba(255,255,255,.055)', color:'white', fontWeight:950, padding:'0 14px' }}>Indietro</button><button disabled={!selectedCountries.length} onClick={()=>{ setCardIndex(0); setStep('radar'); }} style={selectedCountries.length?primaryButton:disabledButton}>Continua al radar</button></div>
        </div>
      )}

      {step==='radar' && (
        <div style={{ ...panel, flex:1, minHeight:0, display:'flex', flexDirection:'column' }}>
          <div style={{ display:'flex', justifyContent:'space-between', alignItems:'center', marginBottom:8 }}>
            <p style={{ color:'rgba(255,255,255,.66)', fontSize:13.5, lineHeight:1.45, margin:0 }}>Se riconosci una specie che hai già visto dal vivo, segnala l'avvistamento. Potrai modificarlo più avanti.</p>
            <span style={{ color:OCHRE, fontWeight:1000, fontSize:12 }}>{Math.min(cardIndex+1, Math.max(1, radarAnimals.length))}/{Math.max(1, radarAnimals.length)}</span>
          </div>
          {!currentAnimal ? (
            <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', textAlign:'center' }}>
              <div>
                <div style={{ fontSize:46 }}>✅</div>
                <div style={{ color:'white', fontWeight:1000, fontSize:18, marginTop:8 }}>Radar completato</div>
                <div style={{ color:'rgba(255,255,255,.55)', fontSize:12, marginTop:5 }}>{seenAnimals.length} specie segnate come avvistate.</div>
              </div>
            </div>
          ) : (
            <div style={{ flex:1, display:'flex', flexDirection:'column', alignItems:'center', justifyContent:'center' }}>
              <div style={{ width:'86%', maxWidth:292, borderRadius:28, background:'#202024', overflow:'hidden', boxShadow:'0 28px 70px rgba(0,0,0,.48)', border:`1px solid ${OCHRE}44` }}>
                <AnimalImg a={{...currentAnimal, status:'catturato'}} size={230} fontSize={82} overrideStatus="catturato" />
                <div style={{ padding:15, textAlign:'center' }}>
                  <div style={{ color:'white', fontSize:19, fontWeight:1000, lineHeight:1.12 }}>{currentAnimal.com}</div>
                  <div style={{ color:'rgba(255,255,255,.45)', fontSize:12, marginTop:5, fontStyle:'italic' }}>{currentAnimal.sci}</div>
                </div>
              </div>
              <div style={{ display:'flex', gap:12, marginTop:18, width:'100%' }}>
                <button onClick={()=>markRadar(false)} style={{ flex:1, height:50, borderRadius:17, border:'1px solid rgba(255,255,255,.12)', background:'#2A2A2C', color:'rgba(255,255,255,.72)', fontWeight:1000, cursor:'pointer', fontFamily:'inherit' }}>Mai visto</button>
                <button onClick={()=>markRadar(true)} style={{ flex:1, height:50, borderRadius:17, border:'none', background:`linear-gradient(135deg,${OCHRE},#C45D3F)`, color:'white', fontWeight:1000, cursor:'pointer', fontFamily:'inherit' }}>Già visto</button>
              </div>
            </div>
          )}
          <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8, marginTop:14 }}>
            <button onClick={goBack} style={{ minHeight:50, borderRadius:18, border:'1px solid rgba(255,255,255,.12)', background:'rgba(255,255,255,.055)', color:'white', fontWeight:950, padding:'0 14px' }}>Indietro</button>
            {!currentAnimal ? (
              <button onClick={runSync} disabled={loading} style={loading ? disabledButton : primaryButton}>{loading ? 'Salvataggio...' : 'Entra in Apex'}</button>
            ) : (
              <button onClick={runSync} disabled={loading} style={{ minHeight:50, borderRadius:18, border:'1px solid rgba(255,255,255,.12)', background:'rgba(255,255,255,.06)', color:'rgba(255,255,255,.78)', fontWeight:950, cursor:'pointer', fontFamily:'inherit' }}>Salta radar</button>
            )}
          </div>
        </div>
      )}

      {step==='wow' && (
        <div style={{ ...panel, flex:1, display:'flex', flexDirection:'column', justifyContent:'space-between', textAlign:'center' }}>
          {syncing ? (
            <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center' }}>
              <div>
                <div style={{ width:72, height:72, borderRadius:'50%', margin:'0 auto 14px', background:`conic-gradient(from 90deg,${OCHRE},#F0A840,${OCHRE})`, animation:'interactiveWiggle .7s ease-in-out infinite' }} />
                <div style={{ color:'white', fontSize:17, fontWeight:1000 }}>Prepariamo il tuo atlante</div>
                <div style={{ color:'rgba(255,255,255,.52)', fontSize:12, marginTop:6 }}>Salvataggio profilo, paesi e primi avvistamenti…</div>
              </div>
            </div>
          ) : (
          <div>
            <div style={{ fontSize:64, marginBottom:12 }}>🏅</div>
            <div style={{ color:'#F0C449', fontSize:13, fontWeight:1000, textTransform:'uppercase', letterSpacing:.8 }}>Prima Spedizione attiva</div>
            <div style={{ color:'white', fontSize:42, fontWeight:1000, marginTop:8 }}>{result?.unlocked_count ?? predictedUnlocks}</div>
            <div style={{ color:'rgba(255,255,255,.64)', fontSize:13, marginTop:4 }}>animali collegati ai tuoi paesi Sul Campo</div>
            <div style={{ color:'rgba(255,255,255,.58)', fontSize:12, lineHeight:1.45, marginTop:12 }}>Subito dopo ti guidiamo in 5 passi nella Home e nella griglia. Poi esplori liberamente: geografia, badge, riconoscimento foto.</div>
            {result?.timed_out && <div style={{ color:'#FFD4C8', fontSize:11.5, marginTop:12, lineHeight:1.4 }}>Rete lenta: Apex è già pronto, la sincronizzazione continua in background.</div>}
            {error && <div style={{ marginTop:12, borderRadius:14, background:'rgba(255,70,70,.12)', border:'1px solid rgba(255,70,70,.22)', color:'#FF9A9A', padding:10, fontSize:11.5 }}>{error}</div>}
            <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:9, marginTop:20 }}>
              <div style={{ borderRadius:20, background:'rgba(168,70,55,.14)', padding:12 }}><div style={{ fontSize:25 }}>🔭</div><div style={{ fontWeight:1000, fontSize:12, marginTop:5 }}>Ricercato</div></div>
              <div style={{ borderRadius:20, background:'rgba(168,70,55,.14)', padding:12 }}><div style={{ fontSize:25 }}>👁️</div><div style={{ fontWeight:1000, fontSize:12, marginTop:5 }}>Avvistato</div></div>
              <div style={{ borderRadius:20, background:'rgba(168,70,55,.14)', padding:12 }}><div style={{ fontSize:25 }}>📸</div><div style={{ fontWeight:1000, fontSize:12, marginTop:5 }}>Catturato</div></div>
              <div style={{ borderRadius:20, background:'rgba(168,70,55,.14)', padding:12 }}><div style={{ fontSize:25 }}>🏅</div><div style={{ fontWeight:1000, fontSize:12, marginTop:5 }}>Badge</div></div>
            </div>
          </div>
          )}
          <button onClick={()=>onFinish?.()} disabled={syncing || loading} style={syncing || loading ? disabledButton : primaryButton}>{syncing ? 'Attendi...' : 'Inizia il tour rapido'}</button>
        </div>
      )}
    </div>
  );
}

function AuthScreen({ onAuthReady }) {
  const [email,setEmail]=useState('');
  const [password,setPassword]=useState('');
  const [mode,setMode]=useState('login');
  const [loading,setLoading]=useState(false);
  const [message,setMessage]=useState('');
  const googleButtonRef=useRef(null);

  const handleGoogleCredential = useCallback(async (credentialResponse) => {
    setLoading(true);
    setMessage('');
    try {
      if (!credentialResponse?.credential) {
        throw new Error('Google non ha restituito un token valido.');
      }
      const { error } = await supabase.auth.signInWithIdToken({
        provider: 'google',
        token: credentialResponse.credential,
      });
      if (error) throw error;
      setMessage('Accesso Google effettuato.');
      onAuthReady?.();
    } catch (err) {
      setMessage(err?.message || 'Errore login Google.');
    } finally {
      setLoading(false);
    }
  }, [onAuthReady]);

  useEffect(() => {
    if (!googleButtonRef.current) return;
    if (!GOOGLE_CLIENT_ID) {
      setMessage('Client ID Google mancante. Aggiungi REACT_APP_GOOGLE_CLIENT_ID in .env.local.');
      return;
    }

    let cancelled = false;
    loadGoogleIdentityScript()
      .then((google) => {
        if (cancelled || !google?.accounts?.id || !googleButtonRef.current) return;
        google.accounts.id.initialize({
          client_id: GOOGLE_CLIENT_ID,
          callback: handleGoogleCredential,
          ux_mode: 'popup',
        });
        googleButtonRef.current.innerHTML = '';
        google.accounts.id.renderButton(googleButtonRef.current, {
          theme: 'outline',
          size: 'large',
          type: 'standard',
          shape: 'pill',
          text: 'continue_with',
          logo_alignment: 'left',
          width: Math.min(420, googleButtonRef.current.offsetWidth || 420),
        });
      })
      .catch((err) => {
        if (!cancelled) setMessage(err?.message || 'Errore caricamento login Google.');
      });

    return () => {
      cancelled = true;
    };
  }, [handleGoogleCredential]);

  const submit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');
    try {
      const { data, error } = mode === 'signup'
        ? await supabase.auth.signUp({ email, password })
        : await supabase.auth.signInWithPassword({ email, password });
      if (error) throw error;
      if (mode === 'signup' && !data?.session) {
        setMessage('Account creato. Controlla la mail per confermare, poi torna qui e fai login.');
        setMode('login');
        return;
      }
      setMessage(mode === 'signup' ? 'Account creato. Benvenuto in Apex!' : 'Accesso effettuato.');
      onAuthReady?.();
    } catch (err) {
      setMessage(err?.message || 'Errore autenticazione.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div {...APP_FRAME_PROPS} style={{ height:'var(--animaldex-app-height, 100dvh)', maxWidth:480, margin:'0 auto', background:'radial-gradient(circle at 78% 4%, rgba(240,168,64,.28), transparent 34%), radial-gradient(circle at 8% 28%, rgba(184,77,58,.34), transparent 42%), linear-gradient(180deg,#2A1208 0%,#17110E 54%,#111113 100%)', color:'white', fontFamily:"'Sora',-apple-system,BlinkMacSystemFont,sans-serif", display:'flex', alignItems:'center', justifyContent:'center', padding:'calc(env(safe-area-inset-top, 0px) + 22px) 22px calc(env(safe-area-inset-bottom, 0px) + 22px)', boxSizing:'border-box', position:'relative', overflow:'hidden' }}>
      <form onSubmit={submit} style={{ width:'100%', background:'linear-gradient(180deg,rgba(41,29,22,.94),rgba(18,17,18,.96))', border:'1px solid rgba(240,168,64,.20)', borderRadius:28, padding:24, boxShadow:'0 28px 80px rgba(0,0,0,.48), inset 0 1px 0 rgba(255,255,255,.06)', backdropFilter:'blur(16px)' }}>
        <div style={{ color:'#F0A840', fontSize:13, fontWeight:900, textTransform:'uppercase', letterSpacing:.9 }}>Apex</div>
        <h1 style={{ margin:'8px 0 6px', fontSize:30, lineHeight:1.05 }}>{mode === 'signup' ? 'Crea il tuo atlante' : 'Bentornato'}</h1>
        <p style={{ margin:'0 0 18px', color:'rgba(255,245,232,.64)', fontSize:13, lineHeight:1.45 }}>{mode === 'signup' ? 'Colleziona fauna, sblocca badge e tieni traccia di ogni avvistamento.' : 'Sincronizza progressi, paesi Sul Campo e badge nel cloud.'}</p>
        <input type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="Email" style={{ width:'100%', height:46, borderRadius:14, border:'1px solid rgba(240,168,64,.20)', background:'rgba(20,16,14,.78)', color:'white', padding:'0 14px', fontSize:14, boxSizing:'border-box', marginBottom:10, outlineColor:'#F0A840' }} />
        <input type="password" required value={password} onChange={e=>setPassword(e.target.value)} placeholder="Password" style={{ width:'100%', height:46, borderRadius:14, border:'1px solid rgba(240,168,64,.20)', background:'rgba(20,16,14,.78)', color:'white', padding:'0 14px', fontSize:14, boxSizing:'border-box', marginBottom:14, outlineColor:'#F0A840' }} />
        <button disabled={loading} type="submit" style={{ width:'100%', height:48, borderRadius:15, border:'none', background:'linear-gradient(135deg,#B84D3A,#F0A840)', color:'white', fontWeight:900, fontSize:15, cursor:loading?'default':'pointer', opacity:loading ? .7 : 1, boxShadow:'0 12px 28px rgba(184,77,58,.34)' }}>{loading ? 'Attendi...' : mode === 'signup' ? 'Crea account' : 'Login'}</button>
        <div ref={googleButtonRef} style={{ width:'100%', height:46, marginTop:10, borderRadius:14, overflow:'hidden', display:'flex', alignItems:'center', justifyContent:'center', background:'rgba(255,245,232,.96)', opacity:loading ? .65 : 1, pointerEvents:loading ? 'none' : 'auto' }} />
        <button type="button" onClick={()=>setMode(mode==='signup'?'login':'signup')} style={{ width:'100%', height:42, marginTop:10, borderRadius:13, border:'1px solid rgba(240,168,64,.18)', background:'rgba(255,255,255,.035)', color:'rgba(255,245,232,.84)', fontWeight:800, cursor:'pointer' }}>{mode === 'signup' ? 'Ho già un account' : 'Crea nuovo account'}</button>
        {message && <SwipeDismissNotice onDismiss={()=>setMessage('')} style={{ marginTop:14, color:message.toLowerCase().includes('erro')?'#FF9387':'#F0C449', fontSize:12, lineHeight:1.4 }}>{message}</SwipeDismissNotice>}
      </form>
    </div>
  );
}

const TRIP_TAGS = ['city','nature','coast','diving','snorkeling','boat','desert','mountain'];

function MainMenuClassic({ onOpen, onBack, onLogout, tutorialFocus=null, statusMap = {}, visitedCountries = [], earnedBadgeIds = [], userProfile, user, socialSnapshot = null, onOpenFriends, onOpenGridStatus, onOpenRegions, onQuickSeen, onOpenPhoto, onOpenBadge, theme='dark', menuProgress=null, dailyDiscovery = null, onDocumentAnimal, onOpenAnimal, usageStreak = 0 }) {
  const progress = menuProgress || buildSimpleProgressState({ animals:ANIMALS, statusMap, visitedCountries, earnedBadgeIds });
  const social = socialSnapshot || buildSocialFallback(user, userProfile, progress);
  const pendingFriendRequests = social.pendingFriendRequestCount || social.requestsIn?.length || 0;
  const socialAlertCount = social.socialAlertCount || pendingFriendRequests;
  const [navOpen, setNavOpen] = useState(false);
  const [quickActionsOpen, setQuickActionsOpen] = useState(false);
  const [homeLaunch, setHomeLaunch] = useState(null);
  const homeLaunchActionRef = useRef(null);
  const homeLaunchTimerRef = useRef(null);
  const userIdKey = user?.id || 'guest';
  const unlockedAwardSet = new Set([
    ...(earnedBadgeIds || []).map(normalizeBadgeId),
    ...computeUnlockedAwards(statusMap, visitedCountries).map(a => normalizeBadgeId(a.badgeId)),
  ].filter(Boolean));
  const earnedAwards = AWARD_RULES.filter(rule => unlockedAwardSet.has(normalizeBadgeId(rule.badgeId)));
  const earnedAwardKey = earnedAwards.map(rule => normalizeBadgeId(rule.badgeId)).join('|');
  const [featuredBadgeId, setFeaturedBadgeId] = useState(() => getFeaturedBadgeId(userIdKey));
  const [profileBgPickerOpen, setProfileBgPickerOpen] = useState(false);
  const [badgePickerOpen, setBadgePickerOpen] = useState(false);
  const [profileBgImage, setProfileBgImage] = useState(() => getProfileBackgroundImage(userIdKey));
  const openFriendsFromHome = (tab = 'feed') => {
    if (typeof onOpenFriends === 'function') onOpenFriends(tab, 'menu');
    else onOpen('friends');
  };
  const isLightTheme = theme === 'light';
  const pageText = isLightTheme ? '#171717' : 'white';
  const mutedText = isLightTheme ? 'rgba(0,0,0,.58)' : 'rgba(255,255,255,.62)';
  const lightPanel = isLightTheme ? '#F6F4EF' : 'rgba(255,255,255,.055)';
  const lightPanelBorder = isLightTheme ? 'rgba(0,0,0,.10)' : 'rgba(255,255,255,.08)';
  const displayName = userProfile?.nickname || userProfile?.username || user?.email?.split('@')[0] || 'Esploratore';
  const nextLevelXP = xpForLevel(progress.level + 1);
  const currLevelXP = xpForLevel(progress.level);
  const xpPct = Math.max(0, Math.min(100, ((progress.xp - currLevelXP) / Math.max(1, nextLevelXP - currLevelXP)) * 100));
  const animalsWithStatus = progress.animalsWithStatus;
  const searchedAnimalsCount = animalsWithStatus.filter(a => a.status === 'ricercato').length;
  const awardMetrics = useMemo(() => computeAwardMetrics(statusMap, visitedCountries), [statusMap, visitedCountries]);
  const featuredBadge = earnedAwards.find(rule => normalizeBadgeId(rule.badgeId) === normalizeBadgeId(featuredBadgeId)) || earnedAwards[0] || null;
  const featuredBadgeColor = featuredBadge ? (BADGE_LEVEL_COLORS[featuredBadge.level] || '#F0A840') : '#D8D2C4';
  const featuredBadgeName = featuredBadge?.name || 'Scegli badge';
  useEffect(() => () => {
    if (homeLaunchTimerRef.current) window.clearTimeout(homeLaunchTimerRef.current);
  }, []);
  const beginHomeLaunch = (event, config, action) => {
    action?.();
  };
  const renderHomeLaunchPreview = () => {
    if (!homeLaunch?.screen) return null;
    const accent = homeLaunch.color || '#F0A840';
    const line = (w, h=9, o=.12) => <span style={{ display:'block', width:w, height:h, borderRadius:999, background:`rgba(255,255,255,${o})` }} />;
    const previewCard = (key, i, color=accent) => (
      <div key={key} style={{ borderRadius:18, border:`1px solid ${hexToRgba(color,.38)}`, background:`linear-gradient(180deg, rgba(18,20,24,.92), ${hexToRgba(color,.08)})`, minHeight:118, padding:12, boxSizing:'border-box', display:'flex', flexDirection:'column', justifyContent:'space-between', boxShadow:'0 12px 32px rgba(0,0,0,.18)' }}>
        <div style={{ color:'rgba(255,255,255,.32)', fontSize:18, fontWeight:1000 }}>#{String(i + 1).padStart(3,'0')}</div>
        <div style={{ width:'54%', height:26, borderRadius:999, background:hexToRgba(color,.26), margin:'8px auto' }} />
        <div style={{ display:'grid', gap:6 }}>{line('78%', 8, .26)}{line('56%', 8, .18)}</div>
      </div>
    );
    const header = (title) => (
      <div style={{ height:72, borderRadius:'0 0 24px 24px', background:ANIMALDEX_ORANGE_GRADIENT, display:'flex', alignItems:'center', justifyContent:'center', color:'white', fontSize:24, fontWeight:1000, boxShadow:'0 14px 30px rgba(184,77,58,.24)' }}>{title}</div>
    );
    if (homeLaunch.screen === 'grid') {
      return (
        <div style={{ height:'100%', background:'radial-gradient(circle at 80% -8%, rgba(240,168,64,.34), transparent 34%), linear-gradient(180deg,#2A1208,#100B09)', color:'white' }}>
          {header('Apex')}
          <div style={{ padding:16, display:'grid', gridTemplateColumns:'repeat(3, minmax(0, 1fr))', gap:10 }}>
            {[0,1,2,3,4,5,6,7,8].map(i => previewCard(`grid-${i}`, i, i % 3 === 0 ? '#D9B86F' : i % 3 === 1 ? '#B86B44' : '#AFCDE0'))}
          </div>
          <div style={{ position:'absolute', left:0, right:0, bottom:0, minHeight:78, borderRadius:'24px 24px 0 0', background:ANIMALDEX_ORANGE_GRADIENT, display:'flex', alignItems:'center', justifyContent:'space-around', color:'white', fontWeight:1000 }}>{line(54,54,.16)}<span style={{ fontSize:24 }}>Ricercati</span>{line(54,54,.16)}</div>
        </div>
      );
    }
    if (homeLaunch.screen === 'profile') {
      return (
        <div style={{ height:'100%', background:'linear-gradient(180deg,#101216,#080A0D)', padding:16, boxSizing:'border-box', color:'white' }}>
          {header('Profilo')}
          <div style={{ marginTop:18, borderRadius:26, border:`1px solid ${hexToRgba(accent,.34)}`, background:homeLaunch.background || 'rgba(255,255,255,.05)', backgroundSize:'cover', backgroundPosition:'center', minHeight:186, padding:22, display:'grid', gridTemplateColumns:'1fr 116px', gap:16, alignItems:'center', overflow:'hidden' }}>
            <div><div style={{ fontSize:28, fontWeight:1000 }}>{displayName}</div><div style={{ color:'rgba(255,255,255,.62)', fontSize:14, marginTop:6 }}>Liv. {progress.level} · {progress.xp} XP</div><div style={{ height:9, borderRadius:999, background:'rgba(255,255,255,.12)', overflow:'hidden', marginTop:14 }}><div style={{ width:`${xpPct}%`, height:'100%', borderRadius:999, background:'linear-gradient(90deg,#D8D2C4,#C87955,#B84D3A)' }} /></div></div>
            <div style={{ height:116, borderRadius:24, border:`1.5px solid ${hexToRgba(accent,.52)}`, background:`linear-gradient(180deg, ${hexToRgba(accent,.20)}, rgba(0,0,0,.20))`, display:'grid', placeItems:'center' }}>{featuredBadge && <img src={buildAwardImagePath(featuredBadge.badgeId)} alt="" style={{ width:84, height:84, objectFit:'contain' }} />}</div>
          </div>
          <div style={{ marginTop:16, display:'grid', gap:10 }}>{[featuredBadgeName, 'Progressi', 'Territori'].map((t,i)=><div key={t} style={{ minHeight:62, borderRadius:18, background:'rgba(255,255,255,.055)', border:'1px solid rgba(255,255,255,.08)', padding:'14px 16px', boxSizing:'border-box', fontWeight:1000 }}>{t}</div>)}</div>
        </div>
      );
    }
    if (homeLaunch.screen === 'taxonomy') {
      const nodes = ['Animalia','Arthropoda','Chordata','Mammalia','Aves','Reptilia'];
      return (
        <div style={{ height:'100%', background:'radial-gradient(circle at 30% 8%, rgba(144,216,74,.14), transparent 32%), linear-gradient(180deg,#07100A,#020504)', color:'white', padding:18, boxSizing:'border-box' }}>
          {header('Albero della Vita')}
          <div style={{ marginTop:30, position:'relative', height:'calc(100% - 110px)' }}>
            <div style={{ position:'absolute', left:'12%', top:'18%', bottom:'12%', width:2, background:'linear-gradient(#D9B86F,#3FB7A6)' }} />
            {nodes.map((node,i)=><div key={node} style={{ position:'absolute', left:`${12 + (i % 3) * 24}%`, top:`${12 + i * 12}%`, width:150, minHeight:58, borderRadius:16, border:`1px solid ${hexToRgba(i < 2 ? '#D9B86F' : '#3FB7A6', .46)}`, background:'rgba(12,15,18,.88)', padding:10, boxSizing:'border-box', boxShadow:'0 14px 38px rgba(0,0,0,.28)' }}><div style={{ color:i < 2 ? '#D9B86F' : '#3FB7A6', fontSize:12, fontWeight:1000 }}>{node}</div>{line('72%', 6, .18)}</div>)}
          </div>
        </div>
      );
    }
    if (homeLaunch.screen === 'friends') {
      return (
        <div style={{ height:'100%', background:'linear-gradient(180deg,#111316,#090A0C)', color:'white', padding:16, boxSizing:'border-box' }}>
          {header('Allenatori')}
          <div style={{ marginTop:18, display:'grid', gap:11 }}>{[displayName, 'Richieste', 'Amici attivi', 'Progressi recenti'].map((t,i)=><div key={t} style={{ minHeight:74, borderRadius:20, border:'1px solid rgba(240,168,64,.22)', background:'rgba(240,168,64,.07)', display:'grid', gridTemplateColumns:'48px 1fr auto', alignItems:'center', gap:12, padding:14, boxSizing:'border-box' }}><div style={{ width:48, height:48, borderRadius:18, background:'rgba(240,168,64,.18)' }} /> <div><div style={{ fontWeight:1000 }}>{t}</div>{line(i ? '55%' : '72%', 7, .22)}</div><div style={{ color:'#F0A840', fontWeight:1000 }}>{i ? '+' : progress.level}</div></div>)}</div>
        </div>
      );
    }
    return null;
  };
  const openTerritoriesFromHome = (event) => {
    prefetchBioregionGeoJson();
    beginHomeLaunch(event, {
      label:'Esplorazione',
      title:'Territori',
      subtitle:'Esplora il mondo e i suoi animali',
      color:'#90D84A',
      background:'linear-gradient(90deg, rgba(5,11,13,.62), rgba(5,11,13,.30) 58%, rgba(5,11,13,.18))',
      content:'globe',
      screen:'regions',
    }, () => (onOpenRegions || (() => onOpen('regions')))());
  };
  useEffect(() => {
    const preferred = normalizeBadgeId(userProfile?.featured_badge_id || getFeaturedBadgeId(userIdKey));
    const validPreferred = earnedAwards.find(rule => normalizeBadgeId(rule.badgeId) === preferred);
    const next = validPreferred?.badgeId || earnedAwards[0]?.badgeId || '';
    setFeaturedBadgeId(normalizeBadgeId(next));
    if (next) persistFeaturedBadgeId(userIdKey, next);
  }, [userIdKey, userProfile?.featured_badge_id, earnedAwardKey]);
  const openFeaturedBadgePicker = (e) => {
    e.stopPropagation();
    if (!earnedAwards.length) {
      onOpen('badges');
      return;
    }
    setBadgePickerOpen(true);
  };
  const chooseFeaturedBadge = (rule) => {
    if (!rule?.badgeId) return;
    setFeaturedBadgeId(normalizeBadgeId(rule.badgeId));
    persistFeaturedBadgeId(userIdKey, rule.badgeId);
    saveFeaturedBadgeId(user?.id, rule.badgeId).catch(err => console.warn('[Apex] Badge in evidenza non salvato su Supabase:', err));
    setBadgePickerOpen(false);
  };
  useEffect(() => {
    const next = normalizeProfileBackgroundImage(userProfile?.profile_background_image || getProfileBackgroundImage(userIdKey));
    setProfileBgImage(next);
    persistProfileBackgroundImage(userIdKey, next);
  }, [userIdKey, userProfile?.profile_background_image]);
  const chooseProfileBackground = (image) => {
    const clean = normalizeProfileBackgroundImage(image);
    setProfileBgImage(clean);
    persistProfileBackgroundImage(userIdKey, clean);
    saveProfileBackgroundImage(user?.id, clean).catch(err => console.warn('[Apex] Sfondo profilo non salvato su Supabase:', err));
    setProfileBgPickerOpen(false);
  };
  const drawerItems = [
    { id:'badges', label:'Badge', icon:'🏅' },
    { id:'abilities', label:'Abilità', icon:'✨' },
    { id:'compare', label:'Comparatore', icon:'⚔️' },
    { id:'profile', label:'Profilo', icon:'👤' },
    { id:'settings', label:'Impostazioni', icon:'⚙️' },
  ];
  const boxBase = {
    width:'100%',
    borderRadius:24,
    border:`1px solid ${lightPanelBorder}`,
    color:pageText,
    fontFamily:'inherit',
    textAlign:'left',
    cursor:'pointer',
    boxSizing:'border-box',
    boxShadow:isLightTheme?'0 14px 30px rgba(0,0,0,.08)':'0 16px 38px rgba(0,0,0,.22)',
  };
  const homeBoxHeight = 164;
  return (
      <div style={{ height:'100%', display:'flex', flexDirection:'column', position:'relative', background:isLightTheme?LIGHT_APP_BG:'radial-gradient(circle at 50% -10%, rgba(184,77,58,.13), transparent 36%), linear-gradient(180deg,#101216,#0B0D10)', overflow:'hidden' }}>
      <div style={{ minHeight:'calc(env(safe-area-inset-top, 0px) + 60px)', display:'flex', alignItems:'center', justifyContent:'space-between', padding:'calc(env(safe-area-inset-top, 0px) + 5px) 14px 8px', boxSizing:'border-box', borderBottom:'none', background:ANIMALDEX_ORANGE_GRADIENT, borderRadius:'0 0 22px 22px', boxShadow:'0 12px 28px rgba(184,77,58,.22)', flexShrink:0 }}>
        <button onClick={()=>setNavOpen(true)} aria-label="Menu" style={{ width:44, height:44, borderRadius:15, border:'1px solid rgba(255,255,255,.10)', background:'rgba(0,0,0,.10)', display:'flex', flexDirection:'column', justifyContent:'center', gap:5, padding:'0 10px', cursor:'pointer' }}>
          {[0,1,2].map(i => <span key={i} style={{ display:'block', width:22, height:2.5, borderRadius:4, background:isLightTheme?'#171717':'white' }} />)}
        </button>
        <ApexHeaderLogo size={28} />
        <button onClick={()=>setQuickActionsOpen(true)} aria-label="Azioni rapide" style={{ width:54, height:54, minWidth:54, minHeight:54, aspectRatio:'1 / 1', borderRadius:18, border:'1px solid rgba(255,255,255,.14)', background:'rgba(0,0,0,.14)', color:'white', cursor:'pointer', display:'flex', alignItems:'center', justifyContent:'center', padding:0, lineHeight:1, flex:'0 0 auto' }}><span style={{ display:'block', fontSize:36, lineHeight:1, fontWeight:900, transform:'translateY(-1px)' }}>+</span></button>
      </div>

      <div style={{ flex:1, overflowY:'auto', padding:'16px 16px 30px' }}>
        <div role="button" tabIndex={0} onClick={(e)=>beginHomeLaunch(e, { label:'Profilo', title:displayName, subtitle:`Liv. ${progress.level} · ${progress.xp} XP`, color:featuredBadgeColor, background:isLightTheme?`linear-gradient(90deg, rgba(251,247,239,.82), rgba(251,247,239,.42)), url("${profileBgImage}")`:`linear-gradient(90deg, rgba(12,14,18,.72), rgba(17,19,23,.28)), url("${profileBgImage}")`, screen:'profile' }, ()=>onOpen('profile'))} onKeyDown={(e)=>{ if (e.key === 'Enter' || e.key === ' ') onOpen('profile'); }} style={{ ...boxBase, position:'relative', height:homeBoxHeight, padding:16, background:isLightTheme?`linear-gradient(90deg, rgba(251,247,239,.84), rgba(251,247,239,.50) 56%, rgba(251,247,239,.20)), url("${profileBgImage}")`:`linear-gradient(90deg, rgba(12,14,18,.76), rgba(17,19,23,.48) 56%, rgba(17,19,23,.18)), url("${profileBgImage}")`, backgroundSize:'cover', backgroundPosition:'center', marginBottom:14, overflow:'hidden' }}>
          {!!socialAlertCount && <div style={{ position:'absolute', top:12, right:12, zIndex:3 }}><SocialCountBadge count={socialAlertCount} /></div>}
          <div style={{ position:'absolute', inset:0, pointerEvents:'none', background:'radial-gradient(circle at 80% 16%, rgba(216,210,196,.16), transparent 36%)' }} />
          <div style={{ position:'relative', zIndex:1, display:'flex', alignItems:'center', gap:14, height:'100%' }}>
            <div style={{ flex:1, minWidth:0 }}>
              <div style={{ color:pageText, fontSize:19, fontWeight:1000, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{displayName}</div>
              <div style={{ color:mutedText, fontSize:11.5, marginTop:2 }}>Liv. {progress.level} · {progress.xp} / {nextLevelXP} XP</div>
              <div style={{ height:8, borderRadius:999, background:'rgba(255,255,255,.08)', overflow:'hidden', marginTop:9 }}><div style={{ height:'100%', width:`${xpPct}%`, background:'linear-gradient(90deg,#D8D2C4,#C87955,#B84D3A)', boxShadow:'0 0 14px rgba(184,77,58,.22)', borderRadius:999 }} /></div>
              <button onClick={openFeaturedBadgePicker} style={{ marginTop:12, height:30, padding:'0 11px', borderRadius:15, border:'1px solid rgba(255,255,255,.16)', background:isLightTheme?'rgba(255,255,255,.60)':'rgba(0,0,0,.30)', color:pageText, fontSize:10.5, fontWeight:1000, fontFamily:'inherit', cursor:'pointer', maxWidth:'100%', overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{featuredBadgeName}</button>
            </div>
            <button onClick={openFeaturedBadgePicker} style={{ width:104, height:116, borderRadius:24, border:`1px solid ${hexToRgba(featuredBadgeColor,.50)}`, background:featuredBadge?`linear-gradient(180deg, ${hexToRgba(featuredBadgeColor,.24)}, rgba(0,0,0,.20))`:'rgba(255,255,255,.055)', display:'flex', alignItems:'center', justifyContent:'center', flexShrink:0, padding:10, cursor:'pointer', boxShadow:`0 12px 30px ${hexToRgba(featuredBadgeColor,.18)}` }}>
              {featuredBadge ? <img src={buildAwardImagePath(featuredBadge.badgeId)} alt={featuredBadge.name} style={{ width:84, height:84, objectFit:'contain', filter:`drop-shadow(0 0 16px ${hexToRgba(featuredBadgeColor,.50)})` }} /> : <span style={{ color:mutedText, fontSize:34, fontWeight:1000 }}>+</span>}
            </button>
          </div>
        </div>

        <button data-tour="home-grid" onClick={(e)=>beginHomeLaunch(e, { label:'Collezione', title:'I tuoi animali', subtitle:'Avvistati e catturati', color:'#F0A840', background:'linear-gradient(135deg, rgba(24,10,6,.42), rgba(20,20,22,.22) 58%, rgba(20,20,22,.45)), url("/backgrounds/background_grid.png")', backgroundSize:'100% 100%, 88% auto', screen:'grid' }, ()=> (tutorialFocus === 'grid' ? onOpen?.('grid') : onOpenGridStatus?.(['avvistato','catturato'])))} style={{ ...boxBase, height:homeBoxHeight, padding:18, background:'linear-gradient(135deg, rgba(24,10,6,.50), rgba(20,20,22,.32) 58%, rgba(20,20,22,.58)), url("/backgrounds/background_grid.png")', backgroundSize:'100% 100%, 88% auto', backgroundRepeat:'no-repeat', backgroundPosition:'center', border: tutorialFocus === 'grid' ? '2.5px solid #F0A840' : '1px solid rgba(184,77,58,.38)', marginBottom:14, overflow:'hidden', display:'flex', flexDirection:'column', justifyContent:'center', boxShadow: tutorialFocus === 'grid' ? '0 0 0 5px rgba(240,168,64,.28), 0 0 32px rgba(240,168,64,.55), 0 16px 34px rgba(184,77,58,.24)' : undefined }}>
          <div style={{ color:'white', fontSize:24, fontWeight:1000 }}>I tuoi animali</div>
          <div style={{ color:'rgba(255,255,255,.78)', fontSize:13, lineHeight:1.55, marginTop:7 }}>Hai {searchedAnimalsCount} animali ricercati da trovare.</div>
        </button>

        <DailyAtlasCard
          dailyDiscovery={dailyDiscovery}
          onDocumentAnimal={onDocumentAnimal}
          onOpenAnimal={onOpenAnimal}
          theme={theme}
        />

        <div style={{ marginBottom:14 }}>
          <button onClick={openTerritoriesFromHome} style={{ position:'relative', width:'100%', height:homeBoxHeight, border:`1px solid ${isLightTheme?'rgba(0,0,0,.10)':'rgba(108,229,199,.24)'}`, borderRadius:24, background:'linear-gradient(90deg, rgba(5,11,13,.82), rgba(5,11,13,.42) 58%, rgba(5,11,13,.18))', color:'#F5F1EA', fontFamily:'inherit', textAlign:'left', padding:'20px 98px 20px 18px', cursor:'pointer', boxShadow:isLightTheme?'0 16px 34px rgba(0,0,0,.09)':'inset 0 1px 0 rgba(255,255,255,.06), 0 16px 34px rgba(0,0,0,.22)', overflow:'hidden' }}>
            <div style={{ position:'absolute', inset:0, pointerEvents:'none', opacity:.92, background:'radial-gradient(circle at 84% 45%, rgba(144,216,74,.24) 0 21%, transparent 22%), radial-gradient(circle at 78% 42%, rgba(79,179,255,.28) 0 30%, transparent 31%), radial-gradient(circle at 88% 56%, rgba(240,168,64,.16) 0 13%, transparent 14%), linear-gradient(115deg, transparent 0 48%, rgba(108,229,199,.16) 54%, transparent 68%)' }} />
            <div style={{ position:'absolute', inset:0, pointerEvents:'none', opacity:.48, backgroundImage:'radial-gradient(circle at 12% 18%, rgba(255,255,255,.95) 0 1px, transparent 1.6px), radial-gradient(circle at 72% 22%, rgba(255,255,255,.75) 0 1px, transparent 1.8px), radial-gradient(circle at 44% 76%, rgba(255,255,255,.55) 0 1px, transparent 1.5px), linear-gradient(115deg, transparent 0 38%, rgba(196,220,255,.16) 45%, rgba(255,255,255,.08) 52%, transparent 62%)', backgroundSize:'82px 82px, 120px 120px, 96px 96px, 100% 100%' }} />
            <div style={{ position:'absolute', inset:0, pointerEvents:'none', background:'linear-gradient(90deg, rgba(5,11,13,.92), rgba(5,11,13,.48) 58%, rgba(5,11,13,.18))' }} />
            <div style={{ position:'relative', zIndex:1 }}>
              <div style={{ color:'#90D84A', fontSize:11, fontWeight:1000, letterSpacing:.8, textTransform:'uppercase' }}>Esplorazione</div>
              <div style={{ fontSize:28, fontWeight:1000, lineHeight:1.02, marginTop:6 }}>Territori</div>
              <div style={{ color:'rgba(245,241,234,.70)', fontSize:12.5, lineHeight:1.45, marginTop:7 }}>Esplora il mondo e i suoi animali</div>
            </div>
          </button>
        </div>

        <button onClick={(e)=>beginHomeLaunch(e, { label:'Tassonomia', title:'Albero della vita', subtitle:'Naviga i rami di Apex', color:'#90D84A', background:'linear-gradient(90deg, rgba(3,8,5,.60), rgba(3,8,5,.30)), url("/backgrounds/background_tree.png")', backgroundSize:'100% 100%, 90% auto', screen:'taxonomy' }, ()=>onOpen('taxonomy'))} style={{ ...boxBase, position:'relative', height:homeBoxHeight, padding:18, marginBottom:14, background:isLightTheme?'linear-gradient(135deg, rgba(244,239,228,.62), rgba(251,247,239,.84))':'linear-gradient(135deg, #06100A, #050708)', border:isLightTheme?'1px solid rgba(0,0,0,.10)':'1px solid rgba(144,216,74,.26)', overflow:'hidden', display:'flex', flexDirection:'column', justifyContent:'center' }}>
          <span style={{ position:'absolute', inset:0, background:'url("/backgrounds/background_tree.png") center 43% / 90% auto no-repeat', opacity:isLightTheme ? .44 : .68, filter:'saturate(1.02) contrast(.98)', transform:'scale(1)', pointerEvents:'none' }} />
          <span style={{ position:'absolute', inset:0, background:isLightTheme?'linear-gradient(90deg, rgba(251,247,239,.82), rgba(251,247,239,.52) 52%, rgba(251,247,239,.20))':'linear-gradient(90deg, rgba(3,8,5,.78), rgba(3,8,5,.54) 47%, rgba(3,8,5,.18))', pointerEvents:'none' }} />
          <div style={{ position:'relative', zIndex:1, maxWidth:'76%' }}>
            <div style={{ color:'#90D84A', fontSize:11, fontWeight:1000, letterSpacing:.8, textTransform:'uppercase' }}>Tassonomia</div>
            <div style={{ color:pageText, fontSize:24, fontWeight:1000, marginTop:6 }}>Albero della vita</div>
            <div style={{ color:mutedText, fontSize:12.5, lineHeight:1.45, marginTop:7 }}>Apri l’albero tassonomico e naviga i rami di Apex.</div>
          </div>
        </button>

        {!!progress.nearlyCompletedBadges.length && <div style={{ ...boxBase, height:homeBoxHeight, padding:14, marginBottom:14, background:isLightTheme?'rgba(255,255,255,.72)':'rgba(255,255,255,.045)', cursor:'default', overflow:'hidden', display:'flex', flexDirection:'column' }}>
          <div style={{ color:isLightTheme?'rgba(0,0,0,.58)':'rgba(255,255,255,.60)', fontSize:11, fontWeight:1000, textTransform:'uppercase', margin:'0 0 8px 2px' }}>Badge in progress</div>
          <div style={{ display:'grid', gap:8, overflowY:'auto', WebkitOverflowScrolling:'touch', paddingRight:2 }}>
            {progress.nearlyCompletedBadges.map(rule => {
              const softBadgeColors = { 1:'#A97D5D', 2:'#AFA99F', 3:'#C4A25C', 4:'#8E73B0' };
              const badgeColor = softBadgeColors[rule.level] || '#AFA99F';
              const badgeBg = isLightTheme ? `linear-gradient(135deg, ${hexToRgba(badgeColor,.18)}, rgba(251,247,239,.96))` : `linear-gradient(135deg, ${hexToRgba(badgeColor,.13)}, rgba(18,18,20,.88))`;
              const badgeText = isLightTheme ? '#171717' : 'white';
              const badgeMuted = isLightTheme ? 'rgba(0,0,0,.62)' : 'rgba(255,255,255,.62)';
              return <button key={rule.badgeId} onClick={()=>onOpenBadge?.(rule.badgeId)} style={{ border:`1.4px solid ${hexToRgba(badgeColor,.72)}`, borderRadius:16, background:badgeBg, boxShadow:isLightTheme?`0 10px 22px ${hexToRgba(badgeColor,.10)}, inset 0 1px 0 rgba(255,255,255,.68)`: `inset 0 1px 0 rgba(255,255,255,.07), 0 0 0 1px rgba(0,0,0,.18)`, padding:12, textAlign:'left', color:badgeText, fontFamily:'inherit', cursor:'pointer' }}>
                <div style={{ display:'flex', justifyContent:'space-between', gap:12, fontWeight:950, fontSize:12.5 }}><span style={{ color:badgeColor }}>{rule.name}</span><span style={{ color:badgeColor }}>{rule.current} / {rule.target}</span></div>
                <div style={{ color:badgeMuted, fontSize:11, lineHeight:1.35, marginTop:5 }}>{rule.sub} · {rule.goal}</div>
                <div style={{ height:7, borderRadius:999, background:isLightTheme?'rgba(0,0,0,.10)':'rgba(255,255,255,.08)', overflow:'hidden', marginTop:8 }}><div style={{ width:`${Math.round(rule.progress*100)}%`, height:'100%', background:`linear-gradient(90deg, ${hexToRgba(badgeColor,.58)}, ${hexToRgba(badgeColor,.92)})` }} /></div>
              </button>;
            })}
          </div>
        </div>}

        <button onClick={(e)=>beginHomeLaunch(e, { label:'Social', title:'Allenatori', subtitle:'Feed, richieste e leaderboard amici', color:'#F0A840', background:'linear-gradient(90deg, rgba(12,10,9,.50), rgba(25,16,10,.24) 58%, rgba(12,10,9,.50)), url("/backgrounds/background_amici.png")', screen:'friends' }, ()=>openFriendsFromHome('feed'))} style={{ width:'100%', border:'1px solid rgba(240,168,64,.30)', borderRadius:22, background:'linear-gradient(90deg, rgba(12,10,9,.62), rgba(25,16,10,.38) 58%, rgba(12,10,9,.60)), url("/backgrounds/background_amici.png")', backgroundSize:'cover', backgroundPosition:'center', color:'white', textAlign:'left', padding:16, fontFamily:'inherit', cursor:'pointer', boxShadow:'0 14px 34px rgba(0,0,0,.20)', marginBottom:14, position:'relative' }}>
          {!!socialAlertCount && <div style={{ position:'absolute', top:12, right:12 }}><SocialCountBadge count={socialAlertCount} prominent /></div>}
          <div style={{ color:'#F0A840', fontSize:10.5, fontWeight:1000, letterSpacing:.8, textTransform:'uppercase' }}>Social</div>
          <div style={{ fontSize:22, fontWeight:1000, marginTop:5 }}>Allenatori</div>
          <div style={{ color:'rgba(255,255,255,.68)', fontSize:12.5, lineHeight:1.4, marginTop:6 }}>Scopri i progressi dei tuoi amici</div>
        </button>
      </div>
      {homeLaunch && (() => {
        const r = homeLaunch.expanded ? homeLaunch.appRect : homeLaunch.sourceRect;
        const radius = homeLaunch.expanded ? 0 : 24;
        return (
          <div style={{ position:'absolute', inset:0, zIndex:470, pointerEvents:'none', background:homeLaunch.expanded?'rgba(0,0,0,.22)':'rgba(0,0,0,0)', transition:'background .38s ease' }}>
            <div style={{ position:'absolute', left:r.left, top:r.top, width:r.width, height:r.height, borderRadius:radius, overflow:'hidden', background:homeLaunch.background || 'linear-gradient(135deg,#1B1A18,#3B2415)', backgroundSize:homeLaunch.backgroundSize || 'cover', backgroundRepeat:'no-repeat', backgroundPosition:'center', border:`1px solid ${hexToRgba(homeLaunch.color || '#F0A840', .42)}`, boxShadow:homeLaunch.expanded?'0 0 0 999px rgba(0,0,0,.18), 0 30px 90px rgba(0,0,0,.52)':'0 16px 38px rgba(0,0,0,.22)', transition:'left .44s cubic-bezier(.16,.86,.18,1), top .44s cubic-bezier(.16,.86,.18,1), width .44s cubic-bezier(.16,.86,.18,1), height .44s cubic-bezier(.16,.86,.18,1), border-radius .44s cubic-bezier(.16,.86,.18,1), box-shadow .44s ease', transform:'translateZ(0)' }}>
              {homeLaunch.screen && homeLaunch.screen !== 'regions' && (
                <div style={{ position:'absolute', inset:0, opacity:homeLaunch.expanded ? 1 : 0, transform:homeLaunch.expanded ? 'scale(1)' : 'scale(.985)', transition:'opacity .22s ease .08s, transform .44s cubic-bezier(.16,.86,.18,1)', zIndex:3 }}>
                  {renderHomeLaunchPreview()}
                </div>
              )}
              {homeLaunch.content === 'globe' && (
                <div style={{ position:'absolute', inset:homeLaunch.expanded ? '-6% -8%' : '0', opacity:homeLaunch.expanded ? .95 : .72, transition:'inset .44s cubic-bezier(.16,.86,.18,1), opacity .34s ease', background:'radial-gradient(circle at 58% 42%, rgba(91,190,248,.28), rgba(7,19,31,.92) 58%, rgba(4,10,14,.98))', overflow:'hidden' }}>
                  <div style={{ position:'absolute', inset:'-8%', borderRadius:'50%', background:'radial-gradient(circle at 35% 30%, rgba(144,216,74,.24), rgba(20,60,48,.18) 34%, transparent 62%)', transform:'rotate(-12deg)' }} />
                  <div style={{ position:'absolute', inset:0, opacity:.55, backgroundImage:'radial-gradient(circle at 12% 18%, rgba(255,255,255,.95) 0 1px, transparent 1.6px), radial-gradient(circle at 72% 22%, rgba(255,255,255,.75) 0 1px, transparent 1.8px), radial-gradient(circle at 44% 76%, rgba(255,255,255,.55) 0 1px, transparent 1.5px)', backgroundSize:'82px 82px, 120px 120px, 96px 96px' }} />
                </div>
              )}
              <div style={{ position:'absolute', inset:0, background:'linear-gradient(90deg, rgba(5,7,8,.78), rgba(5,7,8,.34) 58%, rgba(5,7,8,.12))', opacity:homeLaunch.screen && homeLaunch.screen !== 'regions' ? (homeLaunch.expanded ? 0 : 1) : 1, transition:'opacity .18s ease' }} />
              <div style={{ position:'absolute', left:homeLaunch.expanded ? 26 : 18, bottom:homeLaunch.expanded ? 34 : 18, right:22, color:'white', transition:'left .44s cubic-bezier(.16,.86,.18,1), bottom .44s cubic-bezier(.16,.86,.18,1), opacity .18s ease', opacity:homeLaunch.screen && homeLaunch.screen !== 'regions' && homeLaunch.expanded ? 0 : 1, zIndex:4 }}>
                <div style={{ color:homeLaunch.color || '#F0A840', fontSize:homeLaunch.expanded ? 12 : 10.5, fontWeight:1000, letterSpacing:.8, textTransform:'uppercase' }}>{homeLaunch.label}</div>
                <div style={{ fontSize:homeLaunch.expanded ? 34 : 24, fontWeight:1000, lineHeight:1.02, marginTop:6, transition:'font-size .44s cubic-bezier(.16,.86,.18,1)' }}>{homeLaunch.title}</div>
                <div style={{ color:'rgba(255,255,255,.70)', fontSize:homeLaunch.expanded ? 14 : 12.5, lineHeight:1.45, marginTop:8, maxWidth:360 }}>{homeLaunch.subtitle}</div>
              </div>
            </div>
          </div>
        );
      })()}
      {profileBgPickerOpen && (
        <div onClick={()=>setProfileBgPickerOpen(false)} style={{ position:'absolute', inset:0, zIndex:430, background:'rgba(0,0,0,.72)', display:'flex', alignItems:'flex-end', padding:12, boxSizing:'border-box' }}>
          <div onClick={e=>e.stopPropagation()} style={{ width:'100%', maxHeight:'78%', background:isLightTheme?'#FBF7EF':'#17191D', border:`1px solid ${lightPanelBorder}`, borderRadius:28, padding:14, boxSizing:'border-box', boxShadow:'0 24px 80px rgba(0,0,0,.55)', display:'flex', flexDirection:'column' }}>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', gap:12, marginBottom:12, flexShrink:0 }}>
              <div>
                <div style={{ color:pageText, fontSize:18, fontWeight:1000 }}>Sfondo profilo</div>
                <div style={{ color:mutedText, fontSize:11.5, marginTop:3 }}>Scegli un territorio da mostrare nella box profilo.</div>
              </div>
              <button onClick={()=>setProfileBgPickerOpen(false)} aria-label="Chiudi" style={{ width:40, height:40, borderRadius:18, border:`1px solid ${lightPanelBorder}`, background:isLightTheme?'rgba(0,0,0,.04)':'rgba(255,255,255,.06)', color:pageText, fontSize:22, cursor:'pointer', flexShrink:0 }}>×</button>
            </div>
            <div style={{ overflowY:'auto', WebkitOverflowScrolling:'touch', display:'grid', gridTemplateColumns:'repeat(2, minmax(0, 1fr))', gap:10, paddingBottom:4 }}>
              {PROFILE_BACKGROUND_IMAGES.map(image => {
                const active = image === profileBgImage;
                const label = image.split('/').pop()?.replace(/\.[^.]+$/, '').replace(/[-_]+/g, ' ');
                return (
                  <button key={image} onClick={()=>chooseProfileBackground(image)} style={{ height:104, borderRadius:20, border:`2px solid ${active ? '#F0A840' : 'rgba(255,255,255,.10)'}`, background:`linear-gradient(180deg, rgba(0,0,0,.10), rgba(0,0,0,.68)), url("${image}")`, backgroundSize:'cover', backgroundPosition:'center', color:'white', fontFamily:'inherit', cursor:'pointer', display:'flex', alignItems:'flex-end', justifyContent:'space-between', gap:8, padding:10, textAlign:'left', boxShadow:active?'0 0 0 3px rgba(240,168,64,.20)':'none', overflow:'hidden' }}>
                    <span style={{ fontSize:11.5, fontWeight:950, lineHeight:1.15, textShadow:'0 2px 8px rgba(0,0,0,.65)', overflow:'hidden', display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical' }}>{label}</span>
                    {active && <span style={{ width:24, height:24, borderRadius:12, background:'#F0A840', color:'#17110A', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:1000, flexShrink:0 }}>✓</span>}
                  </button>
                );
              })}
            </div>
          </div>
        </div>
      )}
      {quickActionsOpen && (
        <div onClick={()=>setQuickActionsOpen(false)} style={{ position:'absolute', inset:0, zIndex:435, background:'rgba(0,0,0,.60)', display:'flex', alignItems:'flex-start', justifyContent:'flex-end', padding:'74px 14px 0', boxSizing:'border-box' }}>
          <div onClick={e=>e.stopPropagation()} style={{ width:238, borderRadius:24, border:`1px solid ${lightPanelBorder}`, background:isLightTheme?'rgba(251,247,239,.98)':'linear-gradient(180deg,#1C1E22,#121417)', boxShadow:'0 24px 70px rgba(0,0,0,.44)', padding:12 }}>
            <button onClick={()=>{ setQuickActionsOpen(false); onQuickSeen?.(); }} style={{ width:'100%', minHeight:52, borderRadius:17, border:'1px solid rgba(240,168,64,.24)', background:'rgba(240,168,64,.12)', color:isLightTheme?'#7D3326':'#FFD4A3', fontFamily:'inherit', fontSize:14, fontWeight:1000, textAlign:'left', padding:'0 14px', marginBottom:8 }}>Avvista veloce</button>
            <button onClick={()=>{ setQuickActionsOpen(false); onOpenPhoto?.(); }} style={{ width:'100%', minHeight:52, borderRadius:17, border:'none', background:ANIMALDEX_ORANGE_GRADIENT, color:'white', fontFamily:'inherit', fontSize:14, fontWeight:1000, textAlign:'left', padding:'0 14px' }}>Cattura</button>
          </div>
        </div>
      )}
      {badgePickerOpen && (
        <div onClick={()=>setBadgePickerOpen(false)} style={{ position:'absolute', inset:0, zIndex:432, background:'rgba(0,0,0,.74)', display:'flex', alignItems:'flex-end', padding:12, boxSizing:'border-box' }}>
          <div onClick={e=>e.stopPropagation()} style={{ width:'100%', maxHeight:'82%', background:isLightTheme?'#FBF7EF':'#17191D', border:`1px solid ${lightPanelBorder}`, borderRadius:28, padding:14, boxSizing:'border-box', boxShadow:'0 24px 80px rgba(0,0,0,.58)', display:'flex', flexDirection:'column' }}>
            <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', gap:12, marginBottom:12, flexShrink:0 }}>
              <div style={{ minWidth:0 }}>
                <div style={{ color:pageText, fontSize:18, fontWeight:1000 }}>Badge profilo</div>
                <div style={{ color:mutedText, fontSize:11.5, marginTop:3, lineHeight:1.35 }}>{featuredBadge ? `${featuredBadge.name} · ${featuredBadge.sub}` : 'Scegli un badge conquistato da mostrare agli altri.'}</div>
              </div>
              <button onClick={()=>setBadgePickerOpen(false)} aria-label="Chiudi" style={{ width:40, height:40, borderRadius:18, border:`1px solid ${lightPanelBorder}`, background:isLightTheme?'rgba(0,0,0,.04)':'rgba(255,255,255,.06)', color:pageText, fontSize:22, cursor:'pointer', flexShrink:0 }}>×</button>
            </div>
            {featuredBadge && (
              <div style={{ display:'grid', gridTemplateColumns:'88px 1fr', gap:12, alignItems:'center', border:`1px solid ${hexToRgba(featuredBadgeColor,.38)}`, borderRadius:22, background:`linear-gradient(135deg, ${hexToRgba(featuredBadgeColor,.16)}, rgba(255,255,255,.04))`, padding:12, marginBottom:12 }}>
                <img src={buildAwardImagePath(featuredBadge.badgeId)} alt={featuredBadge.name} style={{ width:76, height:76, objectFit:'contain', filter:`drop-shadow(0 8px 18px ${hexToRgba(featuredBadgeColor,.38)})` }} />
                <div style={{ minWidth:0 }}>
                  <div style={{ color:pageText, fontSize:15, fontWeight:1000, lineHeight:1.1 }}>{featuredBadge.name}</div>
                  <div style={{ color:mutedText, fontSize:11.5, lineHeight:1.35, marginTop:5 }}>{featuredBadge.macro} · {featuredBadge.goal}</div>
                  <div style={{ color:featuredBadgeColor, fontSize:11, fontWeight:1000, marginTop:7 }}>Livello {featuredBadge.level}</div>
                </div>
              </div>
            )}
            <div style={{ overflowY:'auto', WebkitOverflowScrolling:'touch', display:'grid', gridTemplateColumns:'repeat(2, minmax(0, 1fr))', gap:10, paddingBottom:4 }}>
              {earnedAwards.map(rule => {
                const active = normalizeBadgeId(rule.badgeId) === normalizeBadgeId(featuredBadgeId);
                const color = BADGE_LEVEL_COLORS[rule.level] || '#F0A840';
                const current = Math.round(Number(awardMetrics[rule.metric] || 0));
                return (
                  <button key={rule.badgeId} onClick={()=>chooseFeaturedBadge(rule)} style={{ minHeight:134, borderRadius:20, border:`2px solid ${active ? color : 'rgba(255,255,255,.10)'}`, background:isLightTheme?`linear-gradient(180deg, ${hexToRgba(color,.10)}, rgba(251,247,239,.92))`:`linear-gradient(180deg, ${hexToRgba(color,.13)}, rgba(255,255,255,.045))`, color:pageText, fontFamily:'inherit', cursor:'pointer', padding:10, textAlign:'left', boxShadow:active?`0 0 0 3px ${hexToRgba(color,.18)}`:'none', display:'grid', gridTemplateRows:'58px auto', gap:8, overflow:'hidden' }}>
                    <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', gap:8 }}>
                      <img src={buildAwardImagePath(rule.badgeId)} alt="" style={{ width:56, height:56, objectFit:'contain', filter:`drop-shadow(0 6px 14px ${hexToRgba(color,.30)})` }} />
                      {active && <span style={{ width:24, height:24, borderRadius:12, background:color, color:'#15110A', display:'flex', alignItems:'center', justifyContent:'center', fontSize:13, fontWeight:1000, flexShrink:0 }}>✓</span>}
                    </div>
                    <div style={{ minWidth:0 }}>
                      <div style={{ fontSize:11.5, fontWeight:1000, lineHeight:1.12, display:'-webkit-box', WebkitLineClamp:2, WebkitBoxOrient:'vertical', overflow:'hidden' }}>{rule.name}</div>
                      <div style={{ color:mutedText, fontSize:9.8, lineHeight:1.2, marginTop:5 }}>{current} / {rule.threshold} · L{rule.level}</div>
                    </div>
                  </button>
                );
              })}
            </div>
            <button onClick={()=>{ setBadgePickerOpen(false); setProfileBgPickerOpen(true); }} style={{ marginTop:12, height:42, borderRadius:18, border:`1px solid ${lightPanelBorder}`, background:isLightTheme?'rgba(0,0,0,.04)':'rgba(255,255,255,.055)', color:pageText, fontFamily:'inherit', fontWeight:1000, cursor:'pointer' }}>Cambia sfondo profilo</button>
          </div>
        </div>
      )}
      {navOpen && <div onClick={()=>setNavOpen(false)} style={{ position:'absolute', inset:0, zIndex:420, background:'rgba(0,0,0,.52)', display:'flex', alignItems:'stretch' }}>
        <div onClick={e=>e.stopPropagation()} style={{ width:'min(82vw, 330px)', height:'100%', background:isLightTheme?'#FBF7EF':'#121417', borderRight:`1px solid ${lightPanelBorder}`, boxShadow:'24px 0 80px rgba(0,0,0,.45)', padding:'18px 14px', boxSizing:'border-box', color:pageText }}>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', marginBottom:18 }}>
            <div aria-hidden="true" />
            <button onClick={()=>setNavOpen(false)} aria-label="Chiudi" style={{ width:38, height:38, borderRadius:13, border:`1px solid ${lightPanelBorder}`, background:'transparent', color:pageText, fontSize:22, cursor:'pointer' }}>×</button>
          </div>
          <div style={{ display:'grid', gap:9 }}>
            {drawerItems.map(item => <button key={item.id} onClick={()=>{ setNavOpen(false); onOpen(item.id); }} style={{ minHeight:58, border:`1px solid ${lightPanelBorder}`, borderRadius:17, background:lightPanel, color:pageText, cursor:'pointer', padding:'0 13px', display:'flex', alignItems:'center', gap:11, textAlign:'left', fontFamily:'inherit' }}>
              <span style={{ width:38, height:38, borderRadius:14, background:isLightTheme?'rgba(0,0,0,.06)':'rgba(255,255,255,.10)', display:'flex', alignItems:'center', justifyContent:'center', fontSize:20 }}>{item.icon}</span>
              <span style={{ fontSize:14, fontWeight:950, flex:1 }}>{item.label}</span>
              {item.id === 'profile' && <SocialCountBadge count={socialAlertCount} />}
            </button>)}
          </div>
          <button onClick={()=>{ setNavOpen(false); onLogout?.(); }} style={{ width:'100%', height:50, marginTop:18, borderRadius:17, border:'1px solid rgba(184,77,58,.35)', background:'rgba(184,77,58,.10)', color:'#D06A45', fontWeight:1000, fontFamily:'inherit' }}>Esci</button>
        </div>
      </div>}
    </div>
  );
}


const LIFE_TREE_COLORS = {
  animalia:'#D9B86F',
  extra:'#AFCDE0',
  annelida:'#BF8E73',
  arthropoda:'#E59B42',
  mollusca:'#B88CCC',
  chordata:'#3FB7A6',
  amphibia:'#54D0B5',
  reptilia:'#6E9E59',
  pisces:'#4F8CD8',
  aves:'#62C4D8',
  mammalia:'#C89B5A',
  carnivora:'#B8664D',
  primates:'#D1A84F',
  cetacea:'#357AB8',
  chiroptera:'#7D69C8',
};
const lifeSlug = (value) => String(value || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/&/g, ' and ').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const lifeNode = ({ id, label, subtitle='', rank='cluster', kind='cluster', color=LIFE_TREE_COLORS.animalia, match, matchAny, children=[] }) => ({ id:id || lifeSlug(label), label, subtitle, rank, kind, color, ...(match ? { match } : {}), ...(matchAny ? { matchAny } : {}), children });
const lifeTaxon = (label, rank, match, children=[], options={}) => lifeNode({ label, rank, kind:'taxon', match, children, ...options });
const lifeCluster = (label, children=[], options={}) => lifeNode({ label, rank:options.rank || 'cluster', kind:options.kind || 'cluster', children, ...options });
const lifeLeaf = (label, subtitle='', options={}) => lifeNode({ label, subtitle, rank:options.rank || 'editorial', kind:options.kind || 'editorial', ...options });
const lifeFamily = (name, subtitle='', children=[], color) => lifeTaxon(name, 'family', { fam:name }, children, { subtitle, color });
const lifeOrder = (name, subtitle='', children=[], color) => lifeTaxon(name, 'order', { ord:name }, children, { subtitle, color });
const lifeClass = (name, subtitle='', children=[], color) => lifeTaxon(name, 'class', { cls:name }, children, { subtitle, color });
const lifePhylum = (name, subtitle='', children=[], color) => lifeTaxon(name, 'phylum', { phy:name }, children, { subtitle, color });

