      <button onClick={onClose} style={{ width:34, height:34, borderRadius:12, border:'none', background:isLight?'rgba(0,0,0,.06)':'rgba(255,255,255,.08)', color:isLight?'#171717':'white', fontSize:20 }}>×</button>
