function parseRangeAverage(value, unitKind='mass') {
  if (value == null) return null;
  const s = String(value).toLowerCase().replace(/,/g,'.').replace(/[–—]/g,'-');
  const nums = [...s.matchAll(/\d+(?:\.\d+)?/g)].map(m => Number(m[0])).filter(Number.isFinite);
  if (!nums.length) return null;
  let n = nums.length >= 2 ? (nums[0] + nums[1]) / 2 : nums[0];
  if (unitKind === 'mass') {
    if (/\bton|\bt\b|tonnell/.test(s)) n *= 1000000;
    else if (/\bkg\b|chil/.test(s)) n *= 1000;
    else if (/\bmg\b/.test(s)) n /= 1000;
    return n;
  }
  if (unitKind === 'length') {
    if (/\bkm\b/.test(s)) n *= 100000;
    else if (/\bm\b|metro|metri/.test(s)) n *= 100;
    else if (/\bmm\b/.test(s)) n /= 10;
    return n;
  }
  return n;
}
function parseRangeMax(value, unitKind='mass') {
  if (value == null) return null;
  const s = String(value).toLowerCase().replace(/,/g,'.').replace(/[–—]/g,'-');
  const nums = [...s.matchAll(/\d+(?:\.\d)?\d*/g)].map(m => Number(m[0])).filter(Number.isFinite);
  if (!nums.length) return null;
  let n = Math.max(...nums);
  if (unitKind === 'mass') {
    if (/\bton|\bt\b|tonnell/.test(s)) n *= 1000000;
    else if (/\bkg\b|chil/.test(s)) n *= 1000;
    else if (/\bmg\b/.test(s)) n /= 1000;
    return n;
  }
  if (unitKind === 'length') {
    if (/\bkm\b/.test(s)) n *= 100000;
    else if (/\bm\b|metro|metri/.test(s)) n *= 100;
    else if (/\bmm\b/.test(s)) n /= 10;
    return n;
  }
  return n;
}
function getAnimalMassG(a) {
  const m = Number(a?.foodweb?.body_mass_g);
  if (Number.isFinite(m) && m > 0) return m;
  return parseRangeAverage(a?.wt, 'mass') || 1;
}
function getAnimalLengthCm(a) {
  return parseRangeAverage(a?.ln, 'length') || 1;
}
function getComparatorMassG(a) {
  const m = Number(a?.foodweb?.body_mass_g);
  if (Number.isFinite(m) && m > 0) return m;
  return parseRangeMax(a?.wt, 'mass') || 1;
}
function getComparatorLengthCm(a) {
  return parseRangeMax(a?.ln, 'length') || 1;
}
function getCountriesCount(a) {
  return toArraySafe(a?.distribution?.countries_present || a?.geo?.iso?.primary || a?.geo?.iso?.iucn || a?.geo?.iso).length;
}
function percentileRank(value, values) {
  const clean = values.map(Number).filter(v => Number.isFinite(v));
  if (!clean.length || !Number.isFinite(Number(value))) return 0;
  const below = clean.filter(v => v <= Number(value)).length;
  return Math.round((below / clean.length) * 100);
}
function minMaxScore(value, values) {
  const clean = values.map(Number).filter(v => Number.isFinite(v));
  if (!clean.length || !Number.isFinite(Number(value))) return 0;
  const min = Math.min(...clean); const max = Math.max(...clean);
  if (max <= min) return 50;
  return Math.round(((Number(value) - min) / (max - min)) * 100);
}
function vulnerabilityScore(a) {
  const s = String(a?.cons || '').toUpperCase();
  const map = { EX:100, EW:96, CR:92, EN:78, VU:64, NT:42, LC:16, DD:50, NE:45 };
  return map[s] ?? Math.max(0, Math.min(100, 100 - Number(a?.stats?.resistenza || 45)));
}
function getComparatorBenchmarks(animals=[]) {
  const list = (animals || []).filter(Boolean);
  return {
    massLog: list.map(a => Math.log10(getComparatorMassG(a) + 1)),
    lengthLog: list.map(a => Math.log10(getComparatorLengthCm(a) + 1)),
    speeds: list.map(a => Number(a?.stats?.velocita || 0)),
    countries: list.map(getCountriesCount),
    bite: list.map(a => Number(a?.stats?.morso || 0)),
    lifespans: list.map(a => Number(a?.lifespan || 0)),
    rarity: list.map(a => rarityScore(a)),
    abilities: list.map(a => toArraySafe(a?.categories).length),
  };
}
let comparatorBenchmarksCache = { key:'', value:null };
function getComparatorBenchmarksFingerprint(list=[]) {
  let weight = 0;
  for (const a of list) weight += extractAverageWeightKg(a?.wt) || 0;
  return `${list.length}:${Math.round(weight)}`;
}
function getCachedComparatorBenchmarks(animals=[]) {
  const list = (animals || []).filter(Boolean);
  const key = getComparatorBenchmarksFingerprint(list);
  if (comparatorBenchmarksCache.key === key && comparatorBenchmarksCache.value) return comparatorBenchmarksCache.value;
  const value = getComparatorBenchmarks(list);
  comparatorBenchmarksCache = { key, value };
  return value;
}
function invalidateComparatorBenchmarksCache() {
  comparatorBenchmarksCache = { key:'', value:null };
}
const COMPARATOR_METRICS = [
  { key:'vulnerabilita', label:'Vulnerabilità' },
  { key:'dimensioni', label:'Dimensioni' },
  { key:'velocita', label:'Velocità' },
  { key:'peso', label:'Peso' },
  { key:'adattabilita', label:'Adattabilità' },
  { key:'morso', label:'Morso' },
  { key:'longevita', label:'Longevità' },
  { key:'rarita', label:'Rarità' },
  { key:'abilita', label:'Abilità' },
];
const DEFAULT_COMPARATOR_METRIC_KEYS = ['vulnerabilita','dimensioni','velocita','peso','adattabilita'];
function rarityScore(a) {
  const text = normalizeComparatorText(`${a?.rarity || ''} ${a?.rarity_it || ''}`);
  if (/leggend|legend/.test(text)) return 100;
  if (/mitic|myth|epic|epic/.test(text)) return 88;
  if (/rar|rare/.test(text)) return 70;
  if (/non comun|uncommon/.test(text)) return 48;
  if (/comun|common/.test(text)) return 25;
  return 42;
}
function getComparatorMetricDefinition(key) {
  return COMPARATOR_METRICS.find(metric => metric.key === key) || COMPARATOR_METRICS[0];
}
function getComparatorMetrics(a, benchmarks, selectedKeys=DEFAULT_COMPARATOR_METRIC_KEYS) {
  const massG = getComparatorMassG(a);
  const lengthCm = getComparatorLengthCm(a);
  const countries = getCountriesCount(a);
  const speed = Number(a?.stats?.velocita || 0);
  const bite = Number(a?.stats?.morso || 0);
  const lifespan = Number(a?.lifespan || 0);
  const abilityCount = toArraySafe(a?.categories).length;
  const allRadar = [
    { key:'vulnerabilita', label:'Vulnerabilità', value:vulnerabilityScore(a), raw:String(a?.cons || 'DD') },
    { key:'dimensioni', label:'Dimensioni', value:minMaxScore(Math.log10(lengthCm + 1), benchmarks.lengthLog), raw:lengthCm ? `${Math.round(lengthCm)} cm` : 'n/d' },
    { key:'velocita', label:'Velocità', value:percentileRank(speed, benchmarks.speeds), raw:speed ? `${speed}` : 'n/d' },
    { key:'peso', label:'Peso', value:minMaxScore(Math.log10(massG + 1), benchmarks.massLog), raw:formatComparatorMassG(massG) },
    { key:'adattabilita', label:'Adattabilità', value:percentileRank(countries, benchmarks.countries), raw:`${countries} paesi` },
    { key:'morso', label:'Morso', value:percentileRank(bite, benchmarks.bite), raw:bite ? `${bite} PSI` : 'n/d' },
    { key:'longevita', label:'Longevità', value:percentileRank(lifespan, benchmarks.lifespans), raw:lifespan ? `${lifespan} anni` : 'n/d' },
    { key:'rarita', label:'Rarità', value:rarityScore(a), raw:a?.rarity || 'n/d' },
    { key:'abilita', label:'Abilità', value:percentileRank(abilityCount, benchmarks.abilities), raw:`${abilityCount}` },
  ];
  const allowed = new Set((selectedKeys || DEFAULT_COMPARATOR_METRIC_KEYS).slice(0, 8));
  return {
    radar:allRadar.filter(metric => allowed.has(metric.key)),
    massG, lengthCm, countries, speed,
  };
}
function formatComparatorRaw(metric) {
  if (!metric) return '';
  const raw = String(metric.raw || '').trim();
  if (metric.key === 'vulnerabilita') return formatConservationStatus(raw);
  if (metric.key === 'velocita') return raw && raw !== 'n/d' ? `${raw} km/h` : 'n/d';
  return raw || 'n/d';
}
function formatComparatorMassG(g) {
  const n = Number(g);
  if (!Number.isFinite(n) || n <= 0) return 'n/d';
  if (n >= 1000000) return `${Number((n / 1000000).toFixed(n >= 10000000 ? 0 : 1))} t`;
  if (n >= 1000) return `${Number((n / 1000).toFixed(n >= 10000 ? 0 : 1))} kg`;
  if (n < 1) return `${Number((n * 1000).toFixed(1))} mg`;
  return `${Number(n.toFixed(n < 10 ? 1 : 0))} g`;
}
function polarPoint(cx, cy, r, angleDeg) {
  const rad = (Math.PI / 180) * angleDeg;
  return [cx + r * Math.cos(rad), cy + r * Math.sin(rad)];
}
function RadarPolygon({ values, color, opacity=.24, strokeWidth=4, cx=220, cy=205, r=105 }) {
  if (!values?.length) return null;
  const pts = values.map((v,i)=>{
    const angle = -90 + i * (360 / values.length);
    const [x,y] = polarPoint(cx, cy, r * Math.max(0, Math.min(100, v.value)) / 100, angle);
    return `${x},${y}`;
  }).join(' ');
  return <polygon points={pts} fill={color} fillOpacity={opacity} stroke={color} strokeWidth={strokeWidth} strokeLinejoin="round" />;
}
function radarLabelLines(label='') {
  const s = String(label);
  if (s === 'Velocità centili') return ['Velocità', 'centili'];
  if (s === 'Dimensioni log') return ['Dimensioni', 'log'];
  if (s === 'Peso log') return ['Peso', 'log'];
  if (s === 'Adattabilità') return ['Adattabilità'];
  if (s === 'Vulnerabilità') return ['Vulnerabilità'];
  return s.split(' ');
}
function ComparatorRadar({ left, right, colorLeft, colorRight }) {
  const width = 430, height = 410, cx = width/2, cy = 206, r = 120;
  const fallbackAxes = COMPARATOR_METRICS.slice(0, DEFAULT_COMPARATOR_METRIC_KEYS.length).map(m=>({ ...m, value:0 }));
  const axes = left?.radar?.length ? left.radar : right?.radar?.length ? right.radar : fallbackAxes;
  const axisCount = Math.max(1, axes.length);
  const metricForAxis = (data, axis, index) => {
    if (!data?.radar?.length) return null;
    return data.radar.find(metric => metric.key === axis.key) || data.radar[index] || null;
  };
  const labelPoint = (idx) => {
    const angle = -Math.PI/2 + idx*(2*Math.PI/axisCount);
    const rr = r + 52;
    const x = cx + Math.cos(angle) * rr;
    const y = cy + Math.sin(angle) * rr;
    const anchor = Math.abs(Math.cos(angle)) < .18 ? 'middle' : Math.cos(angle) > 0 ? 'start' : 'end';
    return { x:Math.max(42, Math.min(width - 42, x)), y:Math.max(28, Math.min(height - 28, y)), anchor };
  };
  const pt = (idx,value)=>{ const angle=-Math.PI/2 + idx*(2*Math.PI/axisCount); const rr=r*(Number(value||0)/100); return [cx+Math.cos(angle)*rr, cy+Math.sin(angle)*rr]; };
  const poly = (data)=> data?.radar?.length ? axes.map((axis,i)=>pt(i, metricForAxis(data, axis, i)?.value || 0).join(',')).join(' ') : '';
  const grid = [20,40,60,80,100].map(v=> axes.map((_,i)=>pt(i,v).join(',')).join(' '));
  return (
    <div style={{ borderRadius:24, background:'radial-gradient(circle at 50% 48%,rgba(168,70,55,.14),rgba(0,0,0,.36) 58%,rgba(0,0,0,.76))', border:'1px solid rgba(255,255,255,.08)', padding:8, overflow:'hidden', boxShadow:'inset 0 1px 0 rgba(255,255,255,.04)' }}>
      <svg viewBox={`0 0 ${width} ${height}`} style={{ width:'100%', maxWidth:430, display:'block', margin:'0 auto' }}>
        {grid.map((g,i)=><polygon key={i} points={g} fill="none" stroke="rgba(255,255,255,.18)" strokeDasharray="5 6" strokeWidth="1" />)}
        {axes.map((m,i)=>{ const [x,y]=pt(i,100); return <line key={m.key} x1={cx} y1={cy} x2={x} y2={y} stroke="rgba(255,255,255,.20)" strokeWidth="1" />; })}
        {right && <polygon points={poly(right)} fill={`${colorRight}33`} stroke={colorRight} strokeWidth="4" />}
        {left && <polygon points={poly(left)} fill={`${colorLeft}33`} stroke={colorLeft} strokeWidth="4" />}
        {[left,right].filter(Boolean).map((data,di)=>axes.map((axis,i)=>{ const metric=metricForAxis(data, axis, i); const [x,y]=pt(i, metric?.value || 0); const col=di===0?colorLeft:colorRight; return <circle key={`${di}-${axis.key}`} cx={x} cy={y} r="4.8" fill={col} stroke="rgba(255,255,255,.65)" strokeWidth="1.2" />; }))}
        {axes.map((m,i)=>{ const slot=labelPoint(i); const lv=metricForAxis(left, m, i); const rv=metricForAxis(right, m, i); const lines=radarLabelLines(m.label); return <g key={m.key}>
          <text x={slot.x} y={slot.y} fill="white" fontSize={axes.length > 6 ? 12 : 15} fontWeight="900" textAnchor={slot.anchor}>{lines[0]}</text>
          {lines[1] && <text x={slot.x} y={slot.y+14} fill="white" fontSize="10.5" fontWeight="850" opacity=".82" textAnchor={slot.anchor}>{lines[1]}</text>}
          <text x={slot.x} y={slot.y+(lines[1]?29:18)} fill={colorLeft} fontSize="10" fontWeight="900" textAnchor={slot.anchor}>{lv?formatComparatorRaw(lv):''}</text>
          <text x={slot.x} y={slot.y+(lines[1]?42:31)} fill={colorRight} fontSize="10" fontWeight="900" textAnchor={slot.anchor}>{rv?formatComparatorRaw(rv):''}</text>
        </g>; })}
      </svg>
    </div>
  );
}

function ComparatorMetricBars({ left, right, colorLeft, colorRight, theme='dark' }) {
  const isLight = theme === 'light';
  const text = isLight ? '#171717' : '#FFFFFF';
  const muted = isLight ? 'rgba(0,0,0,.56)' : 'rgba(255,255,255,.58)';
  const panel = isLight ? 'rgba(255,255,255,.72)' : 'rgba(255,255,255,.05)';
  const border = isLight ? 'rgba(0,0,0,.10)' : 'rgba(255,255,255,.08)';
  const axes = left?.radar?.length ? left.radar : right?.radar?.length ? right.radar : [];
  const getMetric = (data, axis, index) => data?.radar?.find(metric => metric.key === axis.key) || data?.radar?.[index] || null;
  if (!axes.length) {
    return (
      <div style={{ borderRadius:22, border:`1px solid ${border}`, background:panel, padding:16, color:muted, fontSize:12.5, textAlign:'center', marginBottom:12 }}>
        Scegli due animali per iniziare il confronto.
      </div>
    );
  }
  return (
    <div style={{ borderRadius:24, border:`1px solid ${border}`, background:panel, padding:14, marginBottom:12, overflow:'hidden' }}>
      <div style={{ display:'flex', alignItems:'baseline', justifyContent:'space-between', gap:10, marginBottom:12 }}>
        <div style={{ color:text, fontSize:14, fontWeight:1000 }}>Confronto metriche</div>
        <div style={{ color:muted, fontSize:10.5, fontWeight:900 }}>{axes.length} valori</div>
      </div>
      <div style={{ display:'grid', gap:11 }}>
        {axes.map((axis, index) => {
          const leftMetric = getMetric(left, axis, index);
          const rightMetric = getMetric(right, axis, index);
          const leftValue = Math.max(0, Math.min(100, Number(leftMetric?.value || 0)));
          const rightValue = Math.max(0, Math.min(100, Number(rightMetric?.value || 0)));
          return (
            <div key={axis.key || index} style={{ minWidth:0 }}>
              <div style={{ display:'grid', gridTemplateColumns:'1fr auto auto', alignItems:'center', gap:8, marginBottom:6 }}>
                <div style={{ color:text, fontSize:11.5, fontWeight:950, minWidth:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{axis.label}</div>
                <div style={{ color:colorLeft, fontSize:10.5, fontWeight:950 }}>{leftMetric ? formatComparatorRaw(leftMetric) : 'n/d'}</div>
                <div style={{ color:colorRight, fontSize:10.5, fontWeight:950 }}>{rightMetric ? formatComparatorRaw(rightMetric) : 'n/d'}</div>
              </div>
              <div style={{ display:'grid', gap:5 }}>
                <div style={{ height:8, borderRadius:999, background:isLight?'rgba(0,0,0,.07)':'rgba(255,255,255,.08)', overflow:'hidden' }}>
                  <div style={{ width:`${leftValue}%`, height:'100%', borderRadius:999, background:colorLeft, transition:'width .22s ease' }} />
                </div>
                <div style={{ height:8, borderRadius:999, background:isLight?'rgba(0,0,0,.07)':'rgba(255,255,255,.08)', overflow:'hidden' }}>
                  <div style={{ width:`${rightValue}%`, height:'100%', borderRadius:999, background:colorRight, transition:'width .22s ease' }} />
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
function ComparatorSelector({ label, value, animals, onChange, accent, gradient, onZoom, compact=false }) {
  const [open,setOpen] = useState(false);
  const [q,setQ] = useState('');
  const rows = useMemo(() => {
    const query = q.trim().toLowerCase();
    return (animals || [])
      .filter(a => !query || `${a.com || ''} ${a.sci || ''} ${a.com_en || ''}`.toLowerCase().includes(query))
      .slice(0, 80);
  }, [animals, q]);
  const shownLabel = compact ? '' : label;
  return (
    <div style={{ position:'relative', minWidth:0, width:'100%' }}>
      <button data-sound="compare" onClick={()=>setOpen(v=>!v)} style={{ width:'100%', minWidth:0, boxSizing:'border-box', border:'1px solid transparent', background:`linear-gradient(180deg,rgba(18,18,20,.92),rgba(0,0,0,.36)) padding-box, ${gradient || accent} border-box`, borderRadius:20, padding:compact?8:10, color:'white', cursor:'pointer', textAlign:'left', display:'flex', alignItems:'center', gap:compact?8:10, boxShadow:`0 0 0 1px ${accent}33, 0 14px 34px rgba(0,0,0,.26)` }}>
        <div onClick={e=>{ if (value && onZoom) { e.stopPropagation(); onZoom(value); } }} style={{ width:compact?54:58, height:compact?54:58, borderRadius:16, background:'#202228', display:'flex', alignItems:'center', justifyContent:'center', overflow:'hidden', flexShrink:0, boxShadow:`0 0 18px ${accent}22`, cursor:value?'zoom-in':'pointer' }}>
          {value ? <AnimalImg a={{...value,status:'avvistato'}} size={compact?48:52} fontSize={30} overrideStatus="avvistato" /> : <span style={{ fontSize:24, color:accent }}>＋</span>}
        </div>
        <div style={{ minWidth:0, flex:1 }}>
          {shownLabel && <div style={{ color:accent, fontSize:10, fontWeight:950, textTransform:'uppercase', letterSpacing:.6 }}>{shownLabel}</div>}
          <div style={{ color:'white', fontSize:compact?15:14, fontWeight:950, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{value?.com || 'Seleziona animale'}</div>
          <div style={{ color:'rgba(255,255,255,.48)', fontSize:10, fontStyle:'italic', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{value?.sci || 'tocca per cercare'}</div>
        </div>
      </button>
      {open && <div style={{ position:'fixed', left:14, right:14, top:'calc(env(safe-area-inset-top, 0px) + 86px)', bottom:'calc(env(safe-area-inset-bottom, 0px) + 18px)', zIndex:260, background:'#171719', border:'1px solid rgba(255,255,255,.12)', borderRadius:20, padding:10, boxShadow:'0 22px 70px rgba(0,0,0,.72)', display:'flex', flexDirection:'column' }}>
        <input id={`comparator-search-${label || 'animal'}`} name={`comparator_search_${label || 'animal'}`} value={q} onChange={e=>setQ(e.target.value)} placeholder="Cerca nome o scientifico..." autoFocus style={{ width:'100%', height:44, borderRadius:12, border:'1px solid rgba(255,255,255,.10)', background:'#252529', color:'white', padding:'0 12px', boxSizing:'border-box', outline:'none', marginBottom:8, fontSize:16 }} />
        <div style={{ flex:1, minHeight:0, overflowY:'auto', display:'flex', flexDirection:'column', gap:7, WebkitOverflowScrolling:'touch' }}>
          {rows.map(a=>{
            return <button data-sound="compare" key={a.id} onClick={()=>{onChange(a); setOpen(false); setQ('');}} style={{ border:'none', background:'rgba(255,255,255,.05)', borderRadius:13, padding:8, color:'white', display:'flex', alignItems:'center', gap:9, cursor:'pointer', textAlign:'left' }}>
              <div style={{ width:38, height:38, borderRadius:12, background:'#202228', display:'flex', alignItems:'center', justifyContent:'center', overflow:'hidden', flexShrink:0 }}><AnimalImg a={{...a,status:'avvistato'}} size={34} fontSize={22} overrideStatus="avvistato" /></div>
              <div style={{ minWidth:0 }}><div style={{ fontSize:12.5, fontWeight:900, whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{a.com}</div><div style={{ fontSize:10, color:'rgba(255,255,255,.45)', fontStyle:'italic', whiteSpace:'nowrap', overflow:'hidden', textOverflow:'ellipsis' }}>{a.sci}</div></div>
            </button>;
          })}
        </div>
      </div>}
    </div>
  );
}
function CompareInfoCard({ animal, metrics, accent, sideLabel, gradient, onZoom }) {
  if (!animal) return <div style={{ minHeight:240, borderRadius:22, background:'rgba(255,255,255,.05)', border:'1px dashed rgba(255,255,255,.12)', display:'flex', alignItems:'center', justifyContent:'center', color:'rgba(255,255,255,.45)', fontWeight:850 }}>Scegli un animale</div>;
  const c = CLS[animal.cls] || CLS.Mammalia;
  const abilities = toArraySafe(animal.categories).slice(0,6);
  const stat = (label,value,sub,icon) => <div style={{ background:'rgba(0,0,0,.28)', border:'1px solid rgba(255,255,255,.06)', borderRadius:14, padding:'9px 10px' }}><div style={{ color:'rgba(255,255,255,.55)', fontSize:10, fontWeight:850, textTransform:'uppercase' }}>{icon} {label}</div><div style={{ color:'white', fontSize:14, fontWeight:950, marginTop:3 }}>{value}</div>{sub && <div style={{ color:'rgba(255,255,255,.42)', fontSize:9.5, marginTop:1 }}>{sub}</div>}</div>;
  return (
    <div style={{ borderRadius:24, overflow:'hidden', background:`linear-gradient(180deg,${c.detailTop || '#2A2A2C'},#111113) padding-box, ${gradient || accent} border-box`, border:'1px solid transparent', boxShadow:`0 16px 48px rgba(0,0,0,.28), 0 0 0 1px ${accent}22` }}>
      <div onClick={()=>onZoom?.(animal)} style={{ padding:14, display:'flex', alignItems:'center', gap:12, cursor:'zoom-in' }}>
        <div style={{ width:76, height:76, borderRadius:22, background:'#202228', display:'flex', alignItems:'center', justifyContent:'center', overflow:'hidden', flexShrink:0, boxShadow:`0 0 20px ${accent}22` }}><AnimalImg a={{...animal,status:'avvistato'}} size={70} fontSize={38} overrideStatus="avvistato" /></div>
        <div style={{ minWidth:0 }}>
          <div aria-label={sideLabel} style={{ width:38, height:5, borderRadius:999, background:accent, marginBottom:7, boxShadow:`0 0 14px ${accent}44` }} />
          <div style={{ color:'white', fontSize:18, fontWeight:1000, lineHeight:1.05 }}>{animal.com}</div>
          <div style={{ color:'rgba(255,255,255,.58)', fontSize:11, fontStyle:'italic', marginTop:3 }}>{animal.sci}</div>
        </div>
      </div>
      <div style={{ padding:'0 14px 14px', display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>
        {stat('Morso', Number(animal.stats?.morso || 0) > 0 ? `${animal.stats.morso} PSI` : 'NA', null, '🦷')}
        {stat('Lifespan', animal.lifespan != null ? `${animal.lifespan} anni` : 'n/d', null, '⏳')}
        {stat('Classe', CLS[animal.cls]?.label || animal.cls || 'n/d', animal.cls, '🧬')}
        {stat('Adattabilità', metrics?.radar?.find(x=>x.key==='adattabilita')?.value != null ? `${metrics.radar.find(x=>x.key==='adattabilita').value}/100` : 'n/d', `${metrics?.countries || 0} paesi`, '🌍')}
      </div>
      <div style={{ padding:'0 14px 16px' }}>
        <div style={{ color:'rgba(255,255,255,.58)', fontSize:11, fontWeight:900, margin:'0 0 8px 2px', textTransform:'uppercase' }}>Abilità</div>
        {abilities.length ? <div style={{ display:'grid', gridTemplateColumns:'1fr 1fr', gap:8 }}>{abilities.map(id=><ComparatorAbilityChip key={id} animal={animal} id={id} accent={accent} />)}</div> : <div style={{ color:'rgba(255,255,255,.45)', fontSize:12, background:'rgba(255,255,255,.05)', borderRadius:13, padding:12 }}>Nessuna abilità speciale registrata.</div>}
      </div>
    </div>
  );
}
function ComparatorPage({ onBack, animals = [], statusMap = {}, visitedCountries = [], initialAnimal = null, theme='dark' }) {
  const selectorAnimals = useMemo(() => {
    const source = (animals || []).length ? animals : ANIMALS;
    const revealed = source.filter(a => !isMysteryStatus(normalizeAnimalStatus(a.status ?? getResolvedAnimalStatus(a, statusMap, visitedCountries))));
    return revealed.length ? revealed : source.slice(0, 120);
  }, [animals, statusMap, visitedCountries]);
  const revealedDefaults = useMemo(() => selectorAnimals.slice(0, 12), [selectorAnimals]);
  const pickDefaultPair = useCallback(() => {
    const nextLeft = initialAnimal
      ? (selectorAnimals.find(a => String(a.id) === String(initialAnimal.id)) || initialAnimal)
      : (revealedDefaults[0] || selectorAnimals[0] || null);
    const nextRight = initialAnimal
      ? null
      : (nextLeft
        ? (revealedDefaults.find(a => String(a.id) !== String(nextLeft.id)) || selectorAnimals.find(a => String(a.id) !== String(nextLeft.id)) || null)
        : (revealedDefaults[1] || selectorAnimals[1] || null));
    return { nextLeft, nextRight };
  }, [initialAnimal, revealedDefaults, selectorAnimals]);
  const initialPair = useMemo(() => pickDefaultPair(), [pickDefaultPair]);
  const [left,setLeft] = useState(initialPair.nextLeft || null);
  const [right,setRight] = useState(initialPair.nextRight || null);
  const [selectedMetricKeys,setSelectedMetricKeys] = useState(DEFAULT_COMPARATOR_METRIC_KEYS);
  const [bench,setBench] = useState(() => comparatorBenchmarksCache.value);
  useEffect(() => {
    const { nextLeft, nextRight } = pickDefaultPair();
    setLeft(nextLeft);
    setRight(nextRight);
  }, [initialAnimal?.id, pickDefaultPair]);
  useEffect(() => {
    if (bench) return undefined;
    let alive = true;
    const compute = () => {
      const source = (animals || []).length ? animals : ANIMALS;
      const next = getCachedComparatorBenchmarks(source);
      if (alive) setBench(next);
    };
    if (typeof requestIdleCallback === 'function') requestIdleCallback(compute, { timeout: 250 });
    else setTimeout(compute, 0);
    return () => { alive = false; };
  }, [animals?.length, bench]);
  const leftMetrics = left && bench ? getComparatorMetrics(left, bench, selectedMetricKeys) : null;
  const rightMetrics = right && bench ? getComparatorMetrics(right, bench, selectedMetricKeys) : null;
  const colorLeft = COMPARE_LEFT_COLOR;
  const colorRight = COMPARE_RIGHT_COLOR;
  const [showInfo,setShowInfo]=useState(false);
  const [zoomAnimal,setZoomAnimal]=useState(null);
  const isMobile = typeof window !== 'undefined' && window.innerWidth <= 560;
  const toggleMetric = (key) => {
    setSelectedMetricKeys(prev => {
      const current = prev || DEFAULT_COMPARATOR_METRIC_KEYS;
      if (current.includes(key)) return current.length <= 3 ? current : current.filter(item => item !== key);
      if (current.length >= 8) return current;
      return [...current, key];
    });
  };
  return (
    <div style={{ height:'100%', display:'flex', flexDirection:'column', background:theme==='light'?LIGHT_APP_BG:'#111113', overflow:'hidden' }}>
      <PageHeader title="Comparatore" onBack={onBack} theme={theme} />
      <div style={{ flex:1, overflowY:'auto', overflowX:'hidden', padding:'14px 14px 28px', boxSizing:'border-box' }}>
        <div style={{ background:'linear-gradient(135deg,rgba(168,70,55,.28),rgba(20,20,22,.88))', border:'1px solid rgba(255,255,255,.08)', borderRadius:24, padding:16, marginBottom:14 }}>
          <div style={{ display:'flex', alignItems:'flex-start', justifyContent:'space-between', gap:12 }}>
            <div>
              <div style={{ color:'#C85D44', fontSize:11, fontWeight:950, textTransform:'uppercase', letterSpacing:1 }}>Analisi comparativa</div>
              <div style={{ color:'white', fontSize:25, fontWeight:1000, lineHeight:1.05, marginTop:4 }}>Duello biologico</div>
            </div>
            <button onClick={()=>setShowInfo(true)} aria-label="Info comparatore" style={{ width:36, height:36, borderRadius:13, border:'1px solid rgba(255,255,255,.12)', background:'rgba(255,255,255,.06)', color:'#F0A840', fontSize:18, fontWeight:1000, cursor:'pointer' }}>i</button>
          </div>
          <div style={{ color:'rgba(255,255,255,.56)', fontSize:12, lineHeight:1.55, marginTop:8 }}>Il radar mostra i valori reali accanto a ogni voce; il pentagono li normalizza solo per rendere il confronto immediato.</div>
        </div>
        {!bench && <div style={{ marginBottom:12, borderRadius:18, border:'1px solid rgba(255,255,255,.08)', background:'rgba(255,255,255,.04)', padding:'10px 14px', color:'rgba(255,255,255,.62)', fontSize:12, fontWeight:850 }}>Preparazione statistiche…</div>}
        <div style={{ display:'grid', gridTemplateColumns:isMobile?'1fr':'1fr 1fr', gap:10, marginBottom:12, minWidth:0 }}>
          <ComparatorSelector label="Sinistra" value={left} animals={selectorAnimals} onChange={setLeft} accent={colorLeft} gradient={COMPARE_LEFT_GRADIENT} compact={isMobile} onZoom={setZoomAnimal} />
          <ComparatorSelector label="Destra" value={right} animals={selectorAnimals} onChange={setRight} accent={colorRight} gradient={COMPARE_RIGHT_GRADIENT} compact={isMobile} onZoom={setZoomAnimal} />
        </div>
        {!left && !right && <div style={{ marginBottom:12, borderRadius:18, border:'1px solid rgba(255,255,255,.08)', background:'rgba(255,255,255,.04)', padding:'12px 14px', color:'rgba(255,255,255,.68)', fontSize:12.5, lineHeight:1.45 }}>Seleziona uno o due animali per iniziare il confronto. Da mobile, tocca le card sopra per aprire la ricerca.</div>}
        <ComparatorErrorBoundary>
          <ComparatorMetricBars left={leftMetrics} right={rightMetrics} colorLeft={colorLeft} colorRight={colorRight} theme={theme} />
        </ComparatorErrorBoundary>
        <ComparatorErrorBoundary resetKey={`${left?.id || ''}-${right?.id || ''}-${selectedMetricKeys.join(',')}`}>
          <div style={{ borderRadius:24, border:'1px solid rgba(255,255,255,.08)', background:'rgba(255,255,255,.03)', overflow:'hidden', marginBottom:12 }}>
            <ComparatorRadar left={leftMetrics} right={rightMetrics} colorLeft={colorLeft} colorRight={colorRight} />
            <div style={{ borderTop:'1px solid rgba(255,255,255,.08)', padding:'12px 12px 14px' }}>
              <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', gap:10, marginBottom:9 }}>
                <div style={{ color:'white', fontSize:13, fontWeight:1000 }}>Variabili radar</div>
                <div style={{ color:'rgba(255,255,255,.50)', fontSize:11, fontWeight:900 }}>{selectedMetricKeys.length} / 8</div>
              </div>
              <div style={{ display:'flex', gap:7, overflowX:'auto', paddingBottom:2, WebkitOverflowScrolling:'touch' }}>
                {COMPARATOR_METRICS.map(metric => {
                  const active = selectedMetricKeys.includes(metric.key);
                  const disabled = !active && selectedMetricKeys.length >= 8;
                  return <button key={metric.key} disabled={disabled} onClick={()=>toggleMetric(metric.key)} style={{ flex:'0 0 auto', height:34, borderRadius:13, border:`1px solid ${active?'rgba(240,168,64,.72)':'rgba(255,255,255,.10)'}`, background:active?'linear-gradient(135deg,rgba(184,77,58,.82),rgba(240,168,64,.78))':'rgba(255,255,255,.045)', color:active?'white':'rgba(255,255,255,.72)', padding:'0 10px', fontSize:11, fontWeight:950, fontFamily:'inherit', opacity:disabled ? .55 : 1, cursor:disabled?'not-allowed':'pointer' }}>{metric.label}</button>;
                })}
              </div>
            </div>
          </div>
        </ComparatorErrorBoundary>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:14, margin:'12px 0 16px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:6, color:'rgba(255,255,255,.76)', fontSize:11, fontWeight:850 }}><span style={{ width:14, height:4, borderRadius:4, background:colorLeft, display:'inline-block' }} />{left ? getComparatorAnimalLabel(left) : 'Animale A'}</div>
          <div style={{ color:'rgba(255,255,255,.26)', fontSize:13, fontWeight:950 }}>VS</div>
          <div style={{ display:'flex', alignItems:'center', gap:6, color:'rgba(255,255,255,.76)', fontSize:11, fontWeight:850 }}><span style={{ width:14, height:4, borderRadius:4, background:colorRight, display:'inline-block' }} />{right ? getComparatorAnimalLabel(right) : 'Animale B'}</div>
        </div>
        <ComparatorErrorBoundary>
          <ComparatorSharedHabitats left={left} right={right} colorLeft={colorLeft} colorRight={colorRight} />
        </ComparatorErrorBoundary>
        <div style={{ display:'grid', gridTemplateColumns:'1fr', gap:12 }}>
          <ComparatorErrorBoundary>
            <CompareInfoCard animal={left} metrics={leftMetrics} accent={colorLeft} gradient={COMPARE_LEFT_GRADIENT} sideLabel="Animale A" onZoom={setZoomAnimal} />
          </ComparatorErrorBoundary>
          <ComparatorErrorBoundary>
            <CompareInfoCard animal={right} metrics={rightMetrics} accent={colorRight} gradient={COMPARE_RIGHT_GRADIENT} sideLabel="Animale B" onZoom={setZoomAnimal} />
          </ComparatorErrorBoundary>
        </div>
      </div>
      {showInfo && <ComparatorInfoModal onClose={()=>setShowInfo(false)} />}
      {zoomAnimal && <ImageLightbox src={zoomAnimal.image_url} alt={zoomAnimal.com} accentColor={(CLS[zoomAnimal.cls]||CLS.Mammalia).accent} bgColor={(CLS[zoomAnimal.cls]||CLS.Mammalia).img} animal={zoomAnimal} onClose={()=>setZoomAnimal(null)} />}
    </div>
  );
}

function SimpleComparatorPage({ onBack, animals = [], statusMap = {}, visitedCountries = [], initialAnimal = null, theme='dark' }) {
  const isLightTheme = theme === 'light';
  const pageBg = isLightTheme ? LIGHT_APP_BG : '#111113';
  const pageText = isLightTheme ? '#171717' : '#FFFFFF';
  const subText = isLightTheme ? 'rgba(0,0,0,.60)' : 'rgba(255,255,255,.62)';
  const panelBg = isLightTheme ? 'rgba(255,255,255,.72)' : 'rgba(255,255,255,.055)';
  const panelBorder = isLightTheme ? 'rgba(0,0,0,.10)' : 'rgba(255,255,255,.10)';
  const normalized = useMemo(() => {
    const source = (animals && animals.length ? animals : ANIMALS) || [];
    return source
      .filter(a => a && a.id !== undefined && a.id !== null)
      .map(a => ({ ...a, status: getResolvedAnimalStatus(a, statusMap, visitedCountries) }))
      .sort(compareAnimalsRevealedFirst);
  }, [animals, statusMap, visitedCountries]);
  const firstDefault = useMemo(() => {
    if (initialAnimal?.id) return normalized.find(a => String(a.id) === String(initialAnimal.id)) || initialAnimal;
    return normalized.find(a => !isMysteryStatus(a.status)) || normalized[0] || null;
  }, [initialAnimal?.id, normalized]);
  const secondDefault = useMemo(() => {
    if (initialAnimal?.id) return null;
    if (!firstDefault) return normalized[1] || null;
    return normalized.find(a => String(a.id) !== String(firstDefault.id) && !isMysteryStatus(a.status))
      || normalized.find(a => String(a.id) !== String(firstDefault.id))
      || null;
  }, [initialAnimal?.id, firstDefault, normalized]);
  const [leftId,setLeftId] = useState(firstDefault?.id ? String(firstDefault.id) : '');
  const [rightId,setRightId] = useState(secondDefault?.id ? String(secondDefault.id) : '');
  useEffect(() => {
    setLeftId(firstDefault?.id ? String(firstDefault.id) : '');
    setRightId(secondDefault?.id ? String(secondDefault.id) : '');
  }, [firstDefault?.id, secondDefault?.id]);
  const left = useMemo(() => normalized.find(a => String(a.id) === String(leftId)) || null, [normalized, leftId]);
  const right = useMemo(() => normalized.find(a => String(a.id) === String(rightId)) || null, [normalized, rightId]);
  const options = normalized.filter(a => !isMysteryStatus(a.status) || String(a.id) === leftId || String(a.id) === rightId);
  const [selectedMetricKeys,setSelectedMetricKeys] = useState(DEFAULT_COMPARATOR_METRIC_KEYS);
  const bench = useMemo(() => getComparatorBenchmarks(normalized), [normalized]);
  const leftMetrics = left ? getComparatorMetrics(left, bench, selectedMetricKeys) : null;
  const rightMetrics = right ? getComparatorMetrics(right, bench, selectedMetricKeys) : null;
  const [zoomAnimal,setZoomAnimal] = useState(null);
  const toggleMetric = (key) => {
    setSelectedMetricKeys(prev => {
      const current = prev || DEFAULT_COMPARATOR_METRIC_KEYS;
      if (current.includes(key)) return current.length <= 3 ? current : current.filter(item => item !== key);
      if (current.length >= 8) return current;
      return [...current, key];
    });
  };
  const safeNumber = (value, suffix='') => {
    const n = Number(value);
    return Number.isFinite(n) && n > 0 ? `${n}${suffix}` : 'n/d';
  };
  const statValue = (animal, key) => {
    if (!animal) return 'n/d';
    if (key === 'weight') return formatComparatorMassG(getComparatorMassG(animal));
    if (key === 'length') return `${Math.round(getComparatorLengthCm(animal))} cm`;
    if (key === 'speed') return safeNumber(animal?.stats?.velocita, ' km/h');
    if (key === 'bite') return safeNumber(animal?.stats?.morso, ' PSI');
    if (key === 'countries') return `${getCountriesCount(animal)} paesi`;
    if (key === 'risk') return `${vulnerabilityScore(animal)} / 100`;
    if (key === 'class') return getComparatorClassLabel(animal);
    return 'n/d';
  };
  const AnimalPanel = ({ animal, accent, side }) => {
    if (!animal) {
      return <div style={{ borderRadius:22, background:panelBg, border:`1px dashed ${panelBorder}`, padding:18, color:subText, fontWeight:850, textAlign:'center' }}>Scegli un animale</div>;
    }
    const classKey = comparatorText(animal.cls);
    const cls = CLS[classKey] || CLS.Mammalia;
    const abilities = toArraySafe(animal.categories).slice(0, 4);
    return (
      <div style={{ borderRadius:24, border:`1px solid ${hexToRgba(accent,.42)}`, background:isLightTheme?'rgba(255,255,255,.72)':'linear-gradient(180deg,rgba(255,255,255,.07),rgba(255,255,255,.035))', padding:14, boxShadow:`0 16px 38px ${hexToRgba(accent,.10)}` }}>
        <div style={{ display:'flex', alignItems:'center', gap:12 }}>
          <div style={{ width:86, height:86, borderRadius:22, background:cls.img || '#202228', display:'flex', alignItems:'center', justifyContent:'center', overflow:'hidden', flex:'0 0 auto' }}>
            <AnimalImg a={{...animal, status:'avvistato'}} size={82} fontSize={40} overrideStatus="avvistato" />
          </div>
          <div style={{ minWidth:0, flex:1 }}>
            <div style={{ color:accent, fontSize:11, fontWeight:1000, textTransform:'uppercase', letterSpacing:.8 }}>{side}</div>
            <div style={{ color:pageText, fontSize:20, fontWeight:1000, lineHeight:1.08, marginTop:3 }}>{animal.com}</div>
            <div style={{ color:subText, fontSize:11.5, fontStyle:'italic', marginTop:4, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{animal.sci}</div>
          </div>
        </div>
        <div style={{ display:'flex', flexWrap:'wrap', gap:7, marginTop:12 }}>
          <span style={{ borderRadius:999, padding:'6px 9px', background:hexToRgba(accent,.15), color:accent, fontSize:11, fontWeight:950 }}>{formatConservationStatus(animal.cons)}</span>
          <span style={{ borderRadius:999, padding:'6px 9px', background:isLightTheme?'rgba(0,0,0,.05)':'rgba(255,255,255,.07)', color:pageText, fontSize:11, fontWeight:950 }}>{getComparatorClassLabel(animal)}</span>
          {abilities.map(id => <span key={id} style={{ borderRadius:999, padding:'6px 9px', background:isLightTheme?'rgba(0,0,0,.05)':'rgba(255,255,255,.07)', color:subText, fontSize:10.5, fontWeight:850 }}>{CATEGORY_META[id]?.label || id}</span>)}
        </div>
      </div>
    );
  };
  const rows = [
    ['Peso', 'weight'],
    ['Dimensioni', 'length'],
    ['Velocità', 'speed'],
    ['Morso', 'bite'],
    ['Distribuzione', 'countries'],
    ['Vulnerabilità', 'risk'],
    ['Classe', 'class'],
  ];
  return (
    <div style={{ height:'100%', display:'flex', flexDirection:'column', background:pageBg, overflow:'hidden' }}>
      <PageHeader title="Comparatore" onBack={onBack} theme={theme} />
      <div style={{ flex:1, overflowY:'auto', WebkitOverflowScrolling:'touch', padding:'14px 14px calc(30px + env(safe-area-inset-bottom, 0px))', boxSizing:'border-box' }}>
        <div style={{ borderRadius:24, border:`1px solid ${panelBorder}`, background:isLightTheme?'rgba(255,255,255,.66)':'linear-gradient(135deg,rgba(168,70,55,.24),rgba(20,20,22,.88))', padding:16, marginBottom:14 }}>
          <div style={{ color:'#C85D44', fontSize:11, fontWeight:1000, textTransform:'uppercase', letterSpacing:.9 }}>Analisi comparativa</div>
          <div style={{ color:pageText, fontSize:25, fontWeight:1000, lineHeight:1.05, marginTop:4 }}>Paragona animali</div>
          <div style={{ color:subText, fontSize:12.5, lineHeight:1.5, marginTop:8 }}>Scegli due specie e confronta subito dimensioni, peso, abilità e distribuzione.</div>
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'1fr', gap:10, marginBottom:12 }}>
          <ComparatorSelector label="Animale A" value={left} animals={options} onChange={(animal)=>setLeftId(animal?.id ? String(animal.id) : '')} accent={COMPARE_LEFT_COLOR} gradient={COMPARE_LEFT_GRADIENT} compact onZoom={setZoomAnimal} />
          <ComparatorSelector label="Animale B" value={right} animals={options} onChange={(animal)=>setRightId(animal?.id ? String(animal.id) : '')} accent={COMPARE_RIGHT_COLOR} gradient={COMPARE_RIGHT_GRADIENT} compact onZoom={setZoomAnimal} />
        </div>
        <div style={{ borderRadius:20, border:`1px solid ${panelBorder}`, background:panelBg, padding:12, marginBottom:12 }}>
          <div style={{ display:'flex', alignItems:'center', justifyContent:'space-between', gap:10, marginBottom:9 }}>
            <div style={{ color:pageText, fontSize:13, fontWeight:1000 }}>Variabili radar</div>
            <div style={{ color:subText, fontSize:11, fontWeight:900 }}>{selectedMetricKeys.length} / 8</div>
          </div>
          <div style={{ display:'flex', gap:7, overflowX:'auto', paddingBottom:2, WebkitOverflowScrolling:'touch' }}>
            {COMPARATOR_METRICS.map(metric => {
              const active = selectedMetricKeys.includes(metric.key);
              const disabled = !active && selectedMetricKeys.length >= 8;
              return <button key={metric.key} disabled={disabled} onClick={()=>toggleMetric(metric.key)} style={{ flex:'0 0 auto', height:34, borderRadius:13, border:`1px solid ${active?'rgba(240,168,64,.72)':panelBorder}`, background:active?'linear-gradient(135deg,rgba(184,77,58,.82),rgba(240,168,64,.78))':(isLightTheme?'rgba(0,0,0,.045)':'rgba(255,255,255,.045)'), color:active?'white':pageText, padding:'0 10px', fontSize:11, fontWeight:950, fontFamily:'inherit', opacity:disabled ? .55 : 1, cursor:disabled?'not-allowed':'pointer' }}>{metric.label}</button>;
            })}
          </div>
        </div>
        <ComparatorErrorBoundary>
          <ComparatorMetricBars left={leftMetrics} right={rightMetrics} colorLeft={COMPARE_LEFT_COLOR} colorRight={COMPARE_RIGHT_COLOR} theme={theme} />
        </ComparatorErrorBoundary>
        <div style={{ display:'flex', alignItems:'center', justifyContent:'center', gap:14, margin:'12px 0 14px' }}>
          <div style={{ display:'flex', alignItems:'center', gap:6, color:subText, fontSize:11, fontWeight:850 }}><span style={{ width:14, height:4, borderRadius:4, background:COMPARE_LEFT_COLOR, display:'inline-block' }} />{left ? getComparatorAnimalLabel(left) : 'Animale A'}</div>
          <div style={{ color:isLightTheme?'rgba(0,0,0,.28)':'rgba(255,255,255,.26)', fontSize:13, fontWeight:950 }}>VS</div>
          <div style={{ display:'flex', alignItems:'center', gap:6, color:subText, fontSize:11, fontWeight:850 }}><span style={{ width:14, height:4, borderRadius:4, background:COMPARE_RIGHT_COLOR, display:'inline-block' }} />{right ? getComparatorAnimalLabel(right) : 'Animale B'}</div>
        </div>
        <div style={{ display:'grid', gridTemplateColumns:'1fr', gap:12, marginBottom:12 }}>
          <AnimalPanel animal={left} accent={COMPARE_LEFT_COLOR} side="Animale A" />
          <AnimalPanel animal={right} accent={COMPARE_RIGHT_COLOR} side="Animale B" />
        </div>
        <div style={{ borderRadius:24, border:`1px solid ${panelBorder}`, background:panelBg, overflow:'hidden' }}>
          {rows.map(([label,key], index) => (
            <div key={key} style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:8, alignItems:'center', padding:'12px 13px', borderTop:index ? `1px solid ${panelBorder}` : 'none' }}>
              <div style={{ color:subText, fontSize:11.5, fontWeight:950, textTransform:'uppercase', letterSpacing:.5 }}>{label}</div>
              <div style={{ color:COMPARE_LEFT_COLOR, fontSize:13, fontWeight:1000, textAlign:'center', minWidth:0, overflow:'hidden', textOverflow:'ellipsis' }}>{statValue(left, key)}</div>
              <div style={{ color:COMPARE_RIGHT_COLOR, fontSize:13, fontWeight:1000, textAlign:'right', minWidth:0, overflow:'hidden', textOverflow:'ellipsis' }}>{statValue(right, key)}</div>
            </div>
          ))}
        </div>
      </div>
      {zoomAnimal && <ImageLightbox src={zoomAnimal.image_url} alt={zoomAnimal.com} accentColor={(CLS[zoomAnimal.cls]||CLS.Mammalia).accent} bgColor={(CLS[zoomAnimal.cls]||CLS.Mammalia).img} animal={zoomAnimal} onClose={()=>setZoomAnimal(null)} />}
    </div>
  );
}

function StableComparatorPage({ onBack, animals = [], statusMap = {}, visitedCountries = [], initialAnimal = null, theme='dark' }) {
  const isLightTheme = theme === 'light';
  const pageBg = isLightTheme ? LIGHT_APP_BG : '#111113';
  const pageText = isLightTheme ? '#171717' : '#FFFFFF';
  const subText = isLightTheme ? 'rgba(0,0,0,.60)' : 'rgba(255,255,255,.62)';
  const panelBg = isLightTheme ? 'rgba(255,255,255,.74)' : 'rgba(255,255,255,.055)';
  const panelBorder = isLightTheme ? 'rgba(0,0,0,.10)' : 'rgba(255,255,255,.10)';
  const normalized = useMemo(() => {
    const source = (animals?.length ? animals : ANIMALS) || [];
    return source
      .filter(a => a && a.id !== undefined && a.id !== null)
      .map(a => ({ ...a, com:getComparatorAnimalLabel(a), sci:getComparatorAnimalScientificName(a), status:getResolvedAnimalStatus(a, statusMap, visitedCountries) }))
      .sort((a,b) => getComparatorAnimalLabel(a).localeCompare(getComparatorAnimalLabel(b), 'it'));
  }, [animals, statusMap, visitedCountries]);
  const visibleOptions = useMemo(() => {
    const revealed = normalized.filter(a => !isMysteryStatus(a.status));
    return revealed.length ? revealed : normalized;
  }, [normalized]);
  const initialLeftId = initialAnimal?.id ? String(initialAnimal.id) : String(visibleOptions[0]?.id || '');
  const initialRightId = visibleOptions.find(a => String(a.id) !== initialLeftId)?.id || '';
  const [leftId,setLeftId] = useState(initialLeftId);
  const [rightId,setRightId] = useState(String(initialRightId));
  useEffect(() => {
    setLeftId(initialLeftId);
    setRightId(String(initialRightId || ''));
  }, [initialLeftId, initialRightId]);
  const left = visibleOptions.find(a => String(a.id) === String(leftId)) || null;
  const right = visibleOptions.find(a => String(a.id) === String(rightId)) || null;
  const bench = useMemo(() => getComparatorBenchmarks(normalized), [normalized]);
  const leftMetrics = left ? getComparatorMetrics(left, bench, DEFAULT_COMPARATOR_METRIC_KEYS) : null;
  const rightMetrics = right ? getComparatorMetrics(right, bench, DEFAULT_COMPARATOR_METRIC_KEYS) : null;
  const selectStyle = {
    width:'100%',
    height:50,
    borderRadius:16,
    border:`1px solid ${panelBorder}`,
    background:isLightTheme?'#FFFFFF':'#1B1C20',
    color:pageText,
    padding:'0 12px',
    fontFamily:'inherit',
    fontSize:14,
    fontWeight:850,
    outline:'none',
  };
  const row = (label, aValue, bValue) => (
    <div key={label} style={{ display:'grid', gridTemplateColumns:'1fr 1fr 1fr', gap:8, alignItems:'center', padding:'12px 13px', borderTop:`1px solid ${panelBorder}` }}>
      <div style={{ color:subText, fontSize:11.5, fontWeight:950, textTransform:'uppercase' }}>{label}</div>
      <div style={{ color:COMPARE_LEFT_COLOR, fontSize:13, fontWeight:1000, textAlign:'center', minWidth:0 }}>{comparatorText(aValue, 'n/d')}</div>
      <div style={{ color:COMPARE_RIGHT_COLOR, fontSize:13, fontWeight:1000, textAlign:'right', minWidth:0 }}>{comparatorText(bValue, 'n/d')}</div>
    </div>
  );
  const value = (animal, key) => {
    if (!animal) return 'n/d';
    if (key === 'weight') return formatComparatorMassG(getComparatorMassG(animal));
    if (key === 'length') return `${Math.round(getComparatorLengthCm(animal))} cm`;
    if (key === 'speed') return Number(animal?.stats?.velocita || 0) > 0 ? `${animal.stats.velocita} km/h` : 'n/d';
    if (key === 'bite') return Number(animal?.stats?.morso || 0) > 0 ? `${animal.stats.morso} PSI` : 'n/d';
    if (key === 'countries') return `${getCountriesCount(animal)} paesi`;
    if (key === 'class') return getComparatorClassLabel(animal);
    return 'n/d';
  };
  if (!visibleOptions.length) {
    return (
      <div style={{ height:'100%', display:'flex', flexDirection:'column', background:pageBg, overflow:'hidden' }}>
        <PageHeader title="Comparatore" onBack={onBack} theme={theme} />
        <div style={{ flex:1, display:'flex', alignItems:'center', justifyContent:'center', padding:22, textAlign:'center' }}>
          <div style={{ borderRadius:24, border:`1px solid ${panelBorder}`, background:panelBg, padding:18, color:subText, fontSize:13, lineHeight:1.45 }}>
            <div style={{ color:pageText, fontSize:20, fontWeight:1000, marginBottom:8 }}>Nessun animale confrontabile</div>
            Aggiungi o sblocca almeno un animale per usare il confronto.
          </div>
        </div>
      </div>
    );
  }
  return (
    <div style={{ height:'100%', display:'flex', flexDirection:'column', background:pageBg, overflow:'hidden' }}>
      <PageHeader title="Comparatore" onBack={onBack} theme={theme} />
      <div style={{ flex:1, overflowY:'auto', WebkitOverflowScrolling:'touch', padding:'14px 14px calc(30px + env(safe-area-inset-bottom, 0px))', boxSizing:'border-box' }}>
        <div style={{ borderRadius:24, border:`1px solid ${panelBorder}`, background:panelBg, padding:16, marginBottom:12 }}>
          <div style={{ color:'#C85D44', fontSize:11, fontWeight:1000, textTransform:'uppercase', letterSpacing:.9 }}>Analisi comparativa</div>
          <div style={{ color:pageText, fontSize:25, fontWeight:1000, lineHeight:1.05, marginTop:4 }}>Paragona animali</div>
          <div style={{ color:subText, fontSize:12.5, lineHeight:1.5, marginTop:8 }}>Versione stabile: seleziona due specie e confronta valori essenziali.</div>
        </div>
        <div style={{ display:'grid', gap:10, marginBottom:12 }}>
          <select aria-label="Animale A" value={leftId} onChange={e=>setLeftId(e.target.value)} style={selectStyle}>
            {visibleOptions.map(a => <option key={a.id} value={String(a.id)}>{getComparatorAnimalLabel(a)}</option>)}
          </select>
          <select aria-label="Animale B" value={rightId} onChange={e=>setRightId(e.target.value)} style={selectStyle}>
            <option value="">Scegli animale B</option>
            {visibleOptions.map(a => <option key={a.id} value={String(a.id)}>{getComparatorAnimalLabel(a)}</option>)}
          </select>
        </div>
        <ComparatorErrorBoundary>
          <ComparatorMetricBars left={leftMetrics} right={rightMetrics} colorLeft={COMPARE_LEFT_COLOR} colorRight={COMPARE_RIGHT_COLOR} theme={theme} />
        </ComparatorErrorBoundary>
        <div style={{ borderRadius:24, border:`1px solid ${panelBorder}`, background:panelBg, overflow:'hidden' }}>
          {row('Peso', value(left, 'weight'), value(right, 'weight'))}
          {row('Dimensioni', value(left, 'length'), value(right, 'length'))}
          {row('Velocità', value(left, 'speed'), value(right, 'speed'))}
          {row('Morso', value(left, 'bite'), value(right, 'bite'))}
          {row('Distribuzione', value(left, 'countries'), value(right, 'countries'))}
          {row('Classe', value(left, 'class'), value(right, 'class'))}
        </div>
      </div>
    </div>
  );
}

const SECTION_INTRO_SEEN_KEY = 'apex_section_intros_seen_v2';
const SECTION_INTRO_SEEN_SESSION_KEY = 'apex_section_intros_seen_session_v2';
let sectionIntroSeenMemory = new Set();
function getSeenSectionIntros() {
  try {
    const next = new Set(sectionIntroSeenMemory);
    JSON.parse(window.localStorage.getItem(SECTION_INTRO_SEEN_KEY) || '[]').forEach(section => next.add(section));
    JSON.parse(window.sessionStorage.getItem(SECTION_INTRO_SEEN_SESSION_KEY) || '[]').forEach(section => next.add(section));
    ['regions', 'badges', 'abilities', 'compare', 'profile', 'gallery', 'lifeweb', 'quickSeen', 'friends', 'taxonomy'].forEach(section => {
      if (window.localStorage.getItem(`apex_section_intro_${section}`)) next.add(section);
      if (window.sessionStorage.getItem(`apex_section_intro_${section}`)) next.add(section);
      if (document.cookie.includes(`apex_section_intro_${section}=1`)) next.add(section);
    });
    sectionIntroSeenMemory = next;
    return next;
  } catch {
    return new Set(sectionIntroSeenMemory);
  }
}
function hasSeenSectionIntro(section) {
  return getSeenSectionIntros().has(section);
}
function markSectionIntroSeen(section) {
  if (!section) return;
  try {
    const seen = getSeenSectionIntros();
    seen.add(section);
    sectionIntroSeenMemory = seen;
    window.localStorage.setItem(SECTION_INTRO_SEEN_KEY, JSON.stringify(Array.from(seen)));
    window.sessionStorage.setItem(SECTION_INTRO_SEEN_SESSION_KEY, JSON.stringify(Array.from(seen)));
    window.localStorage.setItem(`apex_section_intro_${section}`, '1');
    window.sessionStorage.setItem(`apex_section_intro_${section}`, '1');
    document.cookie = `apex_section_intro_${section}=1; Max-Age=31536000; Path=/; SameSite=Lax`;
  } catch {}
}


