export default function App() {
  const [session,setSession]=useState(null);
  const [user,setUser]=useState(null);
  const [authLoading,setAuthLoading]=useState(true);
  const [dataLoading,setDataLoading]=useState(false);
  const [dataError,setDataError]=useState('');
  const [userProfile,setUserProfile]=useState(null);
  const [toastOpenBadgeId,setToastOpenBadgeId]=useState(null);
  const [tutorialStep,setTutorialStep]=useState(null);
  const [tutorialAnimalId,setTutorialAnimalId]=useState(null);
  const [tutorialStamp,setTutorialStamp]=useState(false);
  const [localAnimalsReady,setLocalAnimalsReady]=useState(() => LOCAL_ANIMALS.length > 0);
  const [animalsData,setAnimalsData]=useState(() => LOCAL_ANIMALS.map(normalizeLocalAnimal));
  useEffect(() => {
    ANIMALS = animalsData;
    invalidateComparatorBenchmarksCache();
  invalidateLifeAnimalsCache();
    if (animalsData?.length) rebuildAnimalGridFilterOptions(animalsData);
  }, [animalsData]);
  const [sel,setSel]=useState(null);
  const [,startDetailTransition]=useTransition();
  const [,startNavTransition]=useTransition();
  const selectAnimal = useCallback((animal) => {
    startDetailTransition(() => setSel(animal));
    queueFullAnimalsHydration().then(() => {
      setSel(prev => {
        if (!prev || Number(prev.id) !== Number(animal?.id)) return prev;
        return getEnrichedAnimal({ ...prev, status: prev.status ?? animal?.status });
      });
    }).catch(() => {});
  }, []);
  const [statusMap,setStatusMap]=useState({});
  const [page,setPage]=useState('menu');
  const [gridPreset,setGridPreset]=useState(null);
  const [gridReturnTarget,setGridReturnTarget]=useState(null);
  const [regionsInitialView,setRegionsInitialView]=useState(null);
  const [comparatorInitialAnimal,setComparatorInitialAnimal]=useState(null);
  const [lifeWebInitialAnimal,setLifeWebInitialAnimal]=useState(null);
  const [taxonomyInitialAnimal,setTaxonomyInitialAnimal]=useState(null);
  const [featureReturnAnimal,setFeatureReturnAnimal]=useState(null);
  const [sectionReturnPage,setSectionReturnPage]=useState('menu');
  const [friendsInitialTab,setFriendsInitialTab]=useState('feed');
  const [socialSnapshot,setSocialSnapshot]=useState(() => buildSocialFallback(null, null, {}));
  const [photoTarget,setPhotoTarget]=useState(null);
  const [sectionIntro,setSectionIntro]=useState(null);
  const [activeSectionGuide,setActiveSectionGuide]=useState(null);
  const [destinationsLoading,setDestinationsLoading]=useState(false);
  const [countryVisitPrompt,setCountryVisitPrompt]=useState(null);
  const [awardQueue,setAwardQueue]=useState([]);
  const [earnedBadgeIds,setEarnedBadgeIds]=useState([]);
  const [progressHydrated,setProgressHydrated]=useState(false);
  const [awardToastReady,setAwardToastReady]=useState(false);
  const [theme,setTheme]=useState(getInitialAnimaldexTheme);
  const [homeVariant,setHomeVariantState]=useState(() => getHomeVariant());
  const [visitedCountries,setVisitedCountries]=useState(() => normalizeIsoList(getVisitedCountries()));
  const [documentedMap,setDocumentedMap]=useState({});
  const [expeditionState,setExpeditionState]=useState({});
  const [expeditionGift,setExpeditionGift]=useState(null);
  const [expeditionNotice,setExpeditionNotice]=useState('');
  // Sync sincrono delle mappe modulo prima del calcolo dei memo (stesso pattern di ANIMALS).
  setModuleDocumentedMap(documentedMap);
  setModuleExpeditionState(expeditionState);
  const animalsWithStatus = useMemo(
    () => (animalsData || []).map(a => ({
      ...a,
      status: getResolvedAnimalStatus(a, statusMap, visitedCountries),
      documented: !!documentedMap[String(a.id)],
    })),
    [animalsData, statusMap, visitedCountries, documentedMap, expeditionState]
  );
  useEffect(() => {
    if (!animalsWithStatus?.length) return;
    let idleId = null;
    const run = () => prewarmLifeTreeIndex(animalsWithStatus);
    if (typeof requestIdleCallback === 'function') idleId = requestIdleCallback(run, { timeout: 500 });
    else idleId = setTimeout(run, 0);
    return () => {
      if (typeof cancelIdleCallback === 'function' && idleId) cancelIdleCallback(idleId);
      else if (idleId) clearTimeout(idleId);
    };
  }, [animalsWithStatus]);
  const menuProgress = useMemo(
    () => buildSimpleProgressState({ animalsWithStatus, visitedCountries, earnedBadgeIds, statusMap }),
    [animalsWithStatus, visitedCountries, earnedBadgeIds, statusMap, documentedMap, expeditionState]
  );
  const awardMetrics = useMemo(() => computeAwardMetrics(statusMap, visitedCountries), [statusMap, visitedCountries]);
  const refreshSocialSnapshot = useCallback(async (force = false) => {
    if (!user?.id) return;
    const next = await fetchSocialSnapshotCached(user.id, userProfile, menuProgress, session?.access_token || '', { force });
    setSocialSnapshot(next || buildSocialFallback(user, userProfile, menuProgress));
  }, [user?.id, userProfile, session?.access_token]);
  useEffect(() => {
    if (!user?.id) return;
    refreshSocialSnapshot(true);
  }, [user?.id, session?.access_token]);
  useEffect(() => {
    if (!user?.id) return;
    setSocialSnapshot(prev => patchSocialSnapshotMe(prev, userProfile, menuProgress, user.id));
  }, [menuProgress.xp, menuProgress.level, menuProgress.seenCount, menuProgress.capturedCount, user?.id, userProfile]);
  useEffect(() => subscribeHomeVariant(setHomeVariantState), []);
  useEffect(() => {
    try {
      const param = new URLSearchParams(window.location.search).get('home');
      if (param === HOME_VARIANTS.v2 || param === HOME_VARIANTS.classic) {
        setHomeVariant(param);
        setHomeVariantState(param);
        return;
      }
      const rolloutKey = 'animaldex_home_v2_rollout';
      if (!window.localStorage.getItem(rolloutKey)) {
        const next = setHomeVariant(HOME_VARIANTS.v2);
        setHomeVariantState(next);
        window.localStorage.setItem(rolloutKey, '1');
      }
    } catch {}
  }, []);
  const handleHomeVariantChange = useCallback((variant) => {
    const next = setHomeVariant(variant);
    setHomeVariantState(next);
    if (page !== 'menu') setPage('menu');
  }, [page]);
  const pendingFriendRequestCount = socialSnapshot?.pendingFriendRequestCount || socialSnapshot?.requestsIn?.length || 0;
  const socialAlertCount = socialSnapshot?.socialAlertCount || pendingFriendRequestCount;
  const awardsHydratedRef = useRef(false);
  const awardInteractionRef = useRef(false);
  const reloadGenerationRef = useRef(0);
  const unlockedAwards = useMemo(() => computeUnlockedAwards(statusMap, visitedCountries, awardMetrics), [statusMap, visitedCountries, awardMetrics]);
  const activeAwardToast = awardQueue[0] || null;
  useAnimaldexSound(true);
  useEffect(() => { bumpUsageStreak(); }, []);
  const appHeight = useAppViewportHeight();
  const getTutorialAnimal = () => {
    const list = (animalsData || []).map(a => ({ ...a, status: getResolvedAnimalStatus(a, statusMap, visitedCountries) }));
    return list.find(a => Number(a.id) === 31)
      || list.find(a => /piccione|columba livia/i.test(`${a.com || ''} ${a.sci || ''}`))
      || list.find(a => !isMysteryStatus(a.status) && a.image_url)
      || list.find(a => a.image_url)
      || list[0]
      || null;
  };

  useEffect(()=>{
    const l=document.createElement('link');
    l.rel='stylesheet';
    l.href='https://fonts.googleapis.com/css2?family=Sora:wght@400;600;700;800&display=swap';
    document.head.appendChild(l);
    document.body.style.cssText='margin:0;background:#1C1C1E;overflow:hidden;overscroll-behavior:none;touch-action:manipulation;width:100%;min-width:0';
    const meta = document.querySelector('meta[name=viewport]') || document.createElement('meta');
    meta.name = 'viewport';
    meta.content = 'width=device-width, initial-scale=1, viewport-fit=cover, maximum-scale=1';
    if (!meta.parentNode) document.head.appendChild(meta);
    const style=document.createElement('style');
    style.textContent = RARITY_CSS + `
@keyframes ecosystemStress { 0%,100%{ transform:translate(0,0); } 25%{ transform:translate(1.5px,-1px); } 50%{ transform:translate(-1.3px,1px); } 75%{ transform:translate(1px,1.2px); } }
@media (max-width: 560px), (display-mode: standalone) {
  .animaldex-page-dive {
    animation: none !important;
    transform: none !important;
    will-change: auto !important;
    filter: none !important;
  }
  .animaldex-app-frame {
    height: var(--animaldex-app-height, 100dvh);
    max-height: var(--animaldex-app-height, 100dvh);
    min-height: var(--animaldex-app-height, 100dvh);
    overflow: hidden;
    overscroll-behavior: none;
  }
}`;
    document.head.appendChild(style);
    return () => { try { document.head.removeChild(l); document.head.removeChild(style); } catch {} };
  },[]);

  useEffect(() => {
    let alive = true;
    loadLocalAnimalsData()
      .then(list => {
        if (!alive) return;
        const normalized = list.map(normalizeLocalAnimal);
        setAnimalsData(prev => prev?.length ? prev : normalized);
        setLocalAnimalsReady(true);
      })
      .catch(err => {
        console.warn('[Apex] Dataset animali locale non caricato:', err);
        if (alive) {
          setDataError('Dataset animali non caricato');
          setLocalAnimalsReady(true);
        }
      });
    return () => { alive = false; };
  }, []);

  useEffect(() => {
    if (authLoading || !user?.id) return;
    hydrateCachedProgress(user);
  }, [authLoading, user?.id]);

  useEffect(()=>{
    applyAnimaldexThemeToDocument(theme);
  }, [theme]);

  useEffect(()=>{
    applyAnimaldexPageChrome(theme, page);
  }, [theme, page]);

  useEffect(()=>{
    let mounted = true;
    supabase.auth.getSession().then(({ data }) => {
      if (!mounted) return;
      syncSupabaseAccessTokenCache(data.session || null);
      setSession(data.session || null);
      setUser(data.session?.user || null);
      setAuthLoading(false);
    });
    const { data: listener } = supabase.auth.onAuthStateChange(async (_event, nextSession) => {
      syncSupabaseAccessTokenCache(nextSession || null);
      setSession(nextSession || null);
      setUser(nextSession?.user || null);
      setAuthLoading(false);
      if (nextSession?.user) {
        try { await ensureUserProfile(nextSession.user); } catch (err) { console.warn('[Apex] Profilo Supabase:', err); }
      }
    });
    return () => {
      mounted = false;
      listener?.subscription?.unsubscribe?.();
    };
  },[]);

  const hydrateCachedProgress = (activeUser = user) => {
    if (!activeUser?.id) return;
    const localStatusMap = getLocalUserStatusMap(activeUser.id);
    const localBadgeIds = Array.from(getAwardUnlockSet()).map(normalizeBadgeId).filter(Boolean);
    const localDestinations = normalizeIsoList(getVisitedCountries());
    const fallbackProfile = buildFallbackProfile(activeUser, false);

    setUserProfile(prev => prev || fallbackProfile);
    if (Object.keys(localStatusMap).length) {
      setStatusMap(prev => mergeStatusMapsByRank(localStatusMap, prev));
      setAnimalsData(prev => applyCachedUserStatuses(prev, activeUser.id));
    }
    if (localDestinations.length) setVisitedCountries(localDestinations);
    if (localBadgeIds.length) setEarnedBadgeIds(prev => Array.from(new Set([...prev.map(normalizeBadgeId), ...localBadgeIds])));
    const localDocumented = getLocalDocumentedMap(activeUser.id);
    if (Object.keys(localDocumented).length) setDocumentedMap(prev => ({ ...localDocumented, ...prev }));
    const localExpeditions = getLocalExpeditionState(activeUser.id);
    if (Object.keys(localExpeditions).length) setExpeditionState(prev => ({ ...localExpeditions, ...prev }));
    setProgressHydrated(true);
  };

  const reloadSupabaseData = async (activeUser = user) => {
    if (!activeUser?.id) return;
    const myGen = ++reloadGenerationRef.current;
    const isStale = () => reloadGenerationRef.current !== myGen;
    setDataLoading(true);
    setDataError('');

    try {
      // Non bloccare mai la UI sul profilo: se Supabase/RLS rallenta, usiamo fallback.
      await withTimeout(
        ensureUserProfile(activeUser).catch(err => {
          console.warn('[Apex] ensure profile non bloccante:', err);
          return false;
        }),
        3500,
        false,
        'ensureUserProfile'
      );

      const profile = await withTimeout(
        fetchUserProfile(activeUser),
        4500,
        buildFallbackProfile(activeUser, false),
        'fetchUserProfile'
      );
      setUserProfile(profile || buildFallbackProfile(activeUser, false));

      const localSnapshot = buildLocalAnimalSnapshot(activeUser.id, statusMap);
      if (localSnapshot) {
        setAnimalsData(localSnapshot.nextAnimals);
        setStatusMap(localSnapshot.nextStatusMap);
        setDataLoading(false);
        setProgressHydrated(true);
        setTimeout(() => setAwardToastReady(true), 0);
      }

      const [remoteAnimalsResult, remoteStatusResult, destinationsResult, badgeResult, documentedResult, expeditionsResult] = await Promise.allSettled([
        Promise.resolve(null),
        withTimeout(fetchUserAnimalStatusMap(activeUser.id), 6500, {}, 'fetchUserAnimalStatusMap'),
        withTimeout(fetchUserDestinations(activeUser.id), 6500, getVisitedCountries(), 'fetchUserDestinations'),
        withTimeout(fetchUserBadgeIds(activeUser.id), 6500, null, 'fetchUserBadgeIds'),
        withTimeout(fetchUserDocumentedMap(activeUser.id), 6500, null, 'fetchUserDocumentedMap'),
        withTimeout(fetchUserExpeditions(activeUser.id), 6500, null, 'fetchUserExpeditions'),
      ]);

      if (isStale()) return;
      const remoteAnimals = remoteAnimalsResult.status === 'fulfilled' ? remoteAnimalsResult.value : null;
      const remoteUserStatusMap = remoteStatusResult.status === 'fulfilled' ? (remoteStatusResult.value || {}) : {};
      const destinations = destinationsResult.status === 'fulfilled' ? destinationsResult.value : getVisitedCountries();
      const remoteBadgeIds = badgeResult.status === 'fulfilled' ? badgeResult.value : null;

      [remoteAnimalsResult, remoteStatusResult, destinationsResult, badgeResult].forEach((result, idx) => {
        if (result.status === 'rejected') {
          const label = ['animals', 'user_animals', 'destinations', 'badges'][idx];
          console.warn(`[Apex] Caricamento parziale ${label} fallito:`, result.reason);
        }
      });

      const sourceAnimals = LOCAL_ANIMALS.length
        ? applyCachedUserStatuses(LOCAL_ANIMALS.map(normalizeLocalAnimal), activeUser.id)
        : (remoteAnimals?.length ? applyCachedUserStatuses(mergeRemoteWithLocalBioregions(remoteAnimals), activeUser.id) : null);
      const mergedSnapshot = LOCAL_ANIMALS.length
        ? buildLocalAnimalSnapshot(activeUser.id, statusMap, remoteUserStatusMap)
        : (sourceAnimals?.length ? {
            nextAnimals: sourceAnimals.map(a => {
              const status = remoteUserStatusMap[a.id] || normalizeAnimalStatus(a.status);
              const base = a._searchText ? a : { ...a, _searchText:getAnimalSearchText(a) };
              return { ...base, status, userStatus:appStatusToSupabase(status) };
            }),
            nextStatusMap: mergeStatusMapsByRank(
              Object.fromEntries(sourceAnimals.map(a => [a.id, normalizeAnimalStatus(a.status)])),
              remoteUserStatusMap,
              getLocalUserStatusMap(activeUser.id),
              statusMap
            ),
          } : null);
      if (mergedSnapshot?.nextAnimals?.length) {
        setAnimalsData(mergedSnapshot.nextAnimals);
        setStatusMap(mergedSnapshot.nextStatusMap);
        saveLocalUserStatusMap(activeUser.id, mergedSnapshot.nextStatusMap);
        syncLocalStatusMapToSupabase(activeUser.id, mergedSnapshot.nextStatusMap).catch(err => console.warn('[Apex] sync progressi locali non bloccante:', err));
      }

      // Merge remoto + paesi in attesa di conferma: un insert fallito o in
      // timeout non deve mai far sparire un paese appena aggiunto.
      const remoteDestinations = normalizeIsoList(destinations || []);
      const pendingDestinations = getPendingDestinations(activeUser.id);
      const nextDestinations = normalizeIsoList([...remoteDestinations, ...pendingDestinations]);
      setVisitedCountries(nextDestinations);
      saveVisitedCountries(nextDestinations);
      if (pendingDestinations.length && destinationsResult.status === 'fulfilled') {
        const remoteDestSet = new Set(remoteDestinations);
        const confirmed = pendingDestinations.filter(iso => remoteDestSet.has(iso));
        if (confirmed.length) removePendingDestinations(activeUser.id, confirmed);
        pendingDestinations.filter(iso => !remoteDestSet.has(iso)).forEach(iso => {
          persistUserDestination(activeUser.id, iso, [])
            .then(() => removePendingDestinations(activeUser.id, [iso]))
            .catch(err => console.warn('[Apex] risync destinazione fallito:', iso, err));
        });
      }

      const localBadgeIds = Array.from(getAwardUnlockSet()).map(normalizeBadgeId);
      const nextBadgeIds = Array.from(new Set([
        ...(earnedBadgeIds || []).map(normalizeBadgeId),
        ...localBadgeIds,
        ...((remoteBadgeIds || []).map(normalizeBadgeId)),
      ])).filter(Boolean);
      setEarnedBadgeIds(nextBadgeIds);
      persistAwardUnlocks(nextBadgeIds);

      // Layer Documentato: merge remoto (se la colonna esiste) + locale, senza mai perdere voci locali.
      const remoteDocumented = documentedResult.status === 'fulfilled' ? (documentedResult.value || null) : null;
      const mergedDocumented = { ...getLocalDocumentedMap(activeUser.id), ...(remoteDocumented || {}) };
      if (Object.keys(mergedDocumented).length) {
        setDocumentedMap(prev => ({ ...mergedDocumented, ...prev }));
        saveLocalDocumentedMap(activeUser.id, mergedDocumented);
      }

      // Spedizioni: merge remoto+locale (vince il progresso maggiore) e risync.
      const remoteExpeditions = expeditionsResult.status === 'fulfilled' ? (expeditionsResult.value || null) : null;
      if (remoteExpeditions) {
        const mergedExpeditions = mergeExpeditionStates(remoteExpeditions, getLocalExpeditionState(activeUser.id));
        if (Object.keys(mergedExpeditions).length) {
          setExpeditionState(prev => mergeExpeditionStates(mergedExpeditions, prev));
          saveLocalExpeditionState(activeUser.id, mergedExpeditions);
          saveUserExpeditions(activeUser.id, mergedExpeditions).catch(err => console.warn('[Apex] risync spedizioni non bloccante:', err));
        }
      }
    } catch (err) {
      if (isStale()) return;
      console.warn('[Apex] Caricamento Supabase fallito, uso fallback locale:', err);
      setDataError(err?.message || 'Errore caricamento Supabase');

      const fallbackSource = applyCachedUserStatuses(LOCAL_ANIMALS.map(normalizeLocalAnimal), activeUser.id);
      const fallbackStatusMap = mergeStatusMapsByRank(Object.fromEntries(fallbackSource.map(a => [a.id, normalizeAnimalStatus(a.status)])), getLocalUserStatusMap(activeUser.id), statusMap);
      const fallback = fallbackSource.map(a => ({ ...a, status:fallbackStatusMap[a.id] || normalizeAnimalStatus(a.status), userStatus:appStatusToSupabase(fallbackStatusMap[a.id] || a.status) }));
      setAnimalsData(fallback);
      setStatusMap(fallbackStatusMap);
      setUserProfile(prev => prev || buildFallbackProfile(activeUser, false));
    } finally {
      if (!isStale()) {
        setDataLoading(false);
        setProgressHydrated(true);
        setTimeout(() => setAwardToastReady(true), 0);
      }
    }
  };

  useEffect(()=>{
    awardsHydratedRef.current = false;
    setProgressHydrated(false);
    setAwardToastReady(false);
    setAwardQueue([]);
    if (user?.id) {
      reloadSupabaseData(user);
    }
  },[user?.id]);

  useEffect(() => {
    if (!localAnimalsReady || !user?.id) return;
    const snapshot = buildLocalAnimalSnapshot(user.id, statusMap);
    if (!snapshot?.nextAnimals?.length) return;
    setAnimalsData(snapshot.nextAnimals);
    setStatusMap(snapshot.nextStatusMap);
  }, [localAnimalsReady, user?.id]);

  useEffect(() => {
    if (authLoading) return;
    if (!localAnimalsReady) return;
    if (user?.id) return;
    const localStatusMap = getLocalUserStatusMap('guest');
    const guestDocumented = getLocalDocumentedMap('guest');
    if (Object.keys(guestDocumented).length) setDocumentedMap(prev => ({ ...guestDocumented, ...prev }));
    const guestExpeditions = getLocalExpeditionState('guest');
    if (Object.keys(guestExpeditions).length) setExpeditionState(prev => ({ ...guestExpeditions, ...prev }));
    if (!Object.keys(localStatusMap).length) {
      setProgressHydrated(true);
      setTimeout(() => setAwardToastReady(true), 0);
      return;
    }
    setStatusMap(localStatusMap);
    setAnimalsData(prev => prev.map(a => {
      const nextStatus = localStatusMap[a.id];
      return nextStatus ? { ...a, status:nextStatus, userStatus:appStatusToSupabase(nextStatus) } : a;
    }));
    setProgressHydrated(true);
    setTimeout(() => setAwardToastReady(true), 0);
  }, [authLoading, user?.id, localAnimalsReady]);

  useEffect(() => {
    if (!userProfile?.onboarding_completed) return;
    if (userProfile?.has_completed_tutorial) return;
    if (tutorialStep) return;
    if (!animalsData?.length) return;
    const target = getTutorialAnimal();
    if (!target) return;
    setTutorialAnimalId(target.id);
    setSel(null);
    setGridPreset(null);
    setGridReturnTarget(null);
    setPage('menu');
    setTutorialStep('home');
  }, [userProfile?.onboarding_completed, userProfile?.has_completed_tutorial, animalsData?.length, Object.keys(statusMap || {}).length, tutorialStep]);

  useEffect(() => {
    if (!progressHydrated) return;
    const localSaved = getAwardUnlockSet();
    const dbSaved = new Set((earnedBadgeIds || []).map(normalizeBadgeId));
    const alreadyKnown = new Set([...Array.from(localSaved), ...Array.from(dbSaved)]);
    const current = unlockedAwards.map(a => normalizeBadgeId(a.badgeId));
    const fresh = unlockedAwards.filter(a => !alreadyKnown.has(normalizeBadgeId(a.badgeId)));
    const initialHydration = !awardsHydratedRef.current;
    awardsHydratedRef.current = true;

    if (awardToastReady && !initialHydration && awardInteractionRef.current && fresh.length) {
      setAwardQueue(prev => [...prev, ...fresh]);
      if (user?.id) fresh.forEach(award => createSocialBadgeEvent(user.id, award).catch(err => console.warn('[Apex] Evento badge non salvato:', err)));
      if (user?.id) fresh.forEach(award => trackUserEvent(user, 'badge_earned', { badge_id:award.badgeId, badge_name:award.name, badge_macro:award.macro, source_screen:'badges' }, userProfile));
      awardInteractionRef.current = false;
    } else if (awardToastReady && !initialHydration && awardInteractionRef.current && !fresh.length) {
      awardInteractionRef.current = false;
    }

    const earnedClean = (earnedBadgeIds || []).map(normalizeBadgeId).filter(Boolean);
    const merged = Array.from(new Set([...earnedClean, ...current]));
    const earnedSet = new Set(earnedClean);
    const badgeSetChanged = merged.length !== earnedClean.length || merged.some(id => !earnedSet.has(id));
    if (badgeSetChanged) {
      setEarnedBadgeIds(merged);
      persistAwardUnlocks(merged);
      if (user?.id) {
        persistEarnedBadges(user.id, merged).catch(err => {
          const msg = String(err?.message || '');
          const isBadgeCatalogMismatch = err?.code === '23503' || /user_badges_badge_id_fkey|foreign key constraint/i.test(msg);
          if (isBadgeCatalogMismatch) {
            console.warn('[Apex] Badge non presente nel catalogo Supabase, salvataggio locale mantenuto:', err);
            return;
          }
          console.warn('[Apex] Salvataggio user_badges fallito:', err);
          setDataError(err?.message || 'Errore salvataggio badge');
        });
      }
    } else {
      persistAwardUnlocks(merged);
    }
  }, [unlockedAwards, earnedBadgeIds, progressHydrated, awardToastReady, user?.id]);

  useEffect(() => {
    if (!activeAwardToast) return;
    const t = setTimeout(() => setAwardQueue(prev => prev.slice(1)), 3200);
    return () => clearTimeout(t);
  }, [activeAwardToast]);

  useEffect(() => {
    if (!expeditionNotice) return;
    const t = setTimeout(() => setExpeditionNotice(''), 5200);
    return () => clearTimeout(t);
  }, [expeditionNotice]);

  const handleStatusChange = async (id, status) => {
    const localUserId = user?.id || 'guest';
    const nextStatus = normalizeAnimalStatus(status);
    const previousStatus = normalizeAnimalStatus(statusMap[id]);
    const currentAnimal = animalsData.find(a => a.id === id);
    const nextCountryCodes = getAnimalCountryCodes(currentAnimal);
    const visitedSet = new Set(normalizeIsoList(visitedCountries));
    const hasVisitedMatch = nextCountryCodes.some(code => visitedSet.has(code));
    setStatusMap(prev => ({ ...prev, [id]: nextStatus }));
    setAnimalsData(prev => prev.map(a => a.id === id ? { ...a, status: nextStatus, userStatus: appStatusToSupabase(nextStatus) } : a));
    saveLocalUserAnimalStatus(localUserId, id, nextStatus);
    awardInteractionRef.current = true;
    if ((nextStatus === 'avvistato' || nextStatus === 'catturato') && nextCountryCodes.length && !hasVisitedMatch) {
      setCountryVisitPrompt(currentAnimal || { id });
    }
    if (!user?.id) return;
    try {
      await saveUserAnimalStatus(user.id, currentAnimal || { id }, nextStatus);
      trackUserEvent(user, 'animal_status_changed', { animal_id:id, animal_name:currentAnimal?.com, rarity:currentAnimal?.rarity, previous_status:previousStatus, next_status:nextStatus, source_screen:'animal_status' }, userProfile).catch(err => console.warn('[Apex] tracking status non bloccante:', err));
      if (nextStatus === 'avvistato') trackUserEvent(user, 'animal_marked_seen', { animal_id:id, animal_name:currentAnimal?.com, rarity:currentAnimal?.rarity, source_screen:'animal_status' }, userProfile).catch(err => console.warn('[Apex] tracking visto non bloccante:', err));
      if (nextStatus === 'catturato') trackUserEvent(user, 'animal_capture_completed', { animal_id:id, animal_name:currentAnimal?.com, rarity:currentAnimal?.rarity, source_screen:'animal_status' }, userProfile).catch(err => console.warn('[Apex] tracking cattura non bloccante:', err));
      if (isSocialCaptureEventWorthy(currentAnimal, nextStatus, previousStatus)) {
        await createSocialCaptureEvent(user.id, currentAnimal).catch(err => console.warn('[Apex] Evento social non salvato:', err));
      }
      reloadSupabaseData(user).catch(err => {
        console.warn('[Apex] Refresh Supabase post-status non bloccante fallito:', err);
        setDataError(err?.message || 'Errore refresh dati Supabase');
      });
    } catch (err) {
      console.warn('[Apex] Salvataggio user_animals fallito:', err);
      setDataError(err?.message || 'Errore salvataggio status animale');
    }
  };

  const handleDocumentAnimal = async (id, source = 'atlas_daily') => {
    const animalId = String(id || '');
    if (!animalId || documentedMap[animalId]) return;
    const now = new Date().toISOString();
    const nextMap = { ...documentedMap, [animalId]: now };
    setDocumentedMap(nextMap);
    saveLocalDocumentedMap(user?.id || 'guest', nextMap);
    awardInteractionRef.current = true;
    const animal = animalsData.find(a => String(a.id) === animalId);
    trackUserEvent(user, 'animal_documented', { animal_id:id, animal_name:animal?.com, rarity:animal?.rarity, source_screen:source }, userProfile).catch(err => console.warn('[Apex] tracking documentato non bloccante:', err));
    if (user?.id) {
      saveUserAnimalDocumented(user.id, id, now).catch(err => console.warn('[Apex] documented_at non salvato (colonna assente?):', err));
    }
  };

  // Avanzamento automatico ondate: quando l'ondata corrente di un paese è
  // completata (10 avvistati o 3 catturati), la successiva si rivela da sola.
  useEffect(() => {
    if (!Object.keys(expeditionState).length) return;
    let changed = false;
    const next = { ...expeditionState };
    let lastAdvance = null;
    for (const iso of Object.keys(next)) {
      let guard = 0;
      while (guard++ < 60) {
        const progress = getExpeditionProgress(iso, statusMap, next, animalsData);
        if (!progress.shouldAdvance) break;
        next[iso] = { ...next[iso], revealedWaves:progress.revealedWaves + 1 };
        changed = true;
        lastAdvance = { iso, wave:progress.revealedWaves + 1, waveCount:progress.waveCount };
      }
    }
    if (changed) {
      setExpeditionState(next);
      saveLocalExpeditionState(user?.id || 'guest', next);
      if (user?.id) saveUserExpeditions(user.id, next).catch(err => console.warn('[Apex] sync spedizioni non bloccante:', err));
      if (lastAdvance) setExpeditionNotice(`Nuova ondata rivelata in ${getCountryDisplayName(lastAdvance.iso)}: ${lastAdvance.wave} di ${lastAdvance.waveCount}. +${XP_PER_WAVE_COMPLETED} XP`);
    }
  }, [statusMap, expeditionState, animalsData, user?.id]);

  // Spedizioni in attesa: si attivano da sole quando matura un credito mensile.
  useEffect(() => {
    const pending = Object.entries(expeditionState).filter(([, entry]) => Number(entry?.revealedWaves ?? 1) <= 0);
    if (!pending.length) return;
    let changed = false;
    const next = { ...expeditionState };
    for (const [iso] of pending) {
      if (!consumeExpeditionCredit(user?.id)) break;
      next[iso] = { ...next[iso], revealedWaves:1, activatedAt:new Date().toISOString() };
      changed = true;
      setExpeditionNotice(`Spedizione ${getCountryDisplayName(iso)} attivata: prima ondata rivelata.`);
    }
    if (changed) {
      setExpeditionState(next);
      saveLocalExpeditionState(user?.id || 'guest', next);
      if (user?.id) saveUserExpeditions(user.id, next).catch(err => console.warn('[Apex] sync spedizioni non bloccante:', err));
    }
  }, [expeditionState, user?.id]);

  const handleAddDestination = async (isoInput, tripTags = []) => {
    const cleanList = (Array.isArray(isoInput) ? isoInput : [isoInput])
      .map(code => String(code || '').toUpperCase())
      .filter(Boolean);
    if (!user?.id || !cleanList.length) return;
    awardInteractionRef.current = true;
    setDestinationsLoading(true);
    setDataError('');
    // In coda finché Supabase non conferma: il paese resta visibile anche se
    // l'insert fallisce o va in timeout (risync automatico al prossimo reload).
    addPendingDestinations(user.id, cleanList);
    try {
      let giftGranted = false;
      const nextExpeditions = { ...expeditionState };
      for (const cleanIso of cleanList) {
        const persisted = await withTimeout(persistUserDestination(user.id, cleanIso, tripTags || []), 4500, false, 'persistUserDestination');
        if (persisted === true) removePendingDestinations(user.id, [cleanIso]);
        const { error: rpcError } = await withTimeout(supabase.rpc('unlock_animals_for_destination', {
          p_user_id: user.id,
          p_iso: cleanIso,
          p_trip_tags: tripTags || [],
        }), 7000, { error:null }, 'unlock_animals_for_destination');
        if (rpcError) console.warn('[Apex] RPC unlock destinazione non disponibile, uso fallback client:', rpcError);
        await unlockAnimalsForDestinationClient(user.id, cleanIso, animalsData);
        await trackUserEvent(user, 'country_added', { country_iso:cleanIso, trip_tags:tripTags || [], source_screen:'regions' }, userProfile);
        // Il diario è sempre libero; l'attivazione della Spedizione (ondate)
        // consuma un credito mensile. Senza crediti resta "in attesa".
        if (!nextExpeditions[cleanIso]) {
          const activated = consumeExpeditionCredit(user.id);
          nextExpeditions[cleanIso] = activated
            ? { revealedWaves:1, activatedAt:new Date().toISOString() }
            : { revealedWaves:0 };
          if (activated && !giftGranted) {
            // Regalo di Spedizione: omaggio celebrativo, comunicato come dono.
            grantExpeditionGift(user.id);
            giftGranted = true;
            setExpeditionGift({ iso:cleanIso, recognitions:EXPEDITION_GIFT_RECOGNITIONS, days:EXPEDITION_GIFT_DAYS });
            trackUserEvent(user, 'expedition_gift_granted', { country_iso:cleanIso, source_screen:'regions' }, userProfile).catch(() => {});
          }
          if (!activated) {
            setExpeditionNotice(`${getCountryDisplayName(cleanIso)} è nel tuo diario. La Spedizione si attiverà con il credito del prossimo mese.`);
          }
        }
      }
      setExpeditionState(nextExpeditions);
      saveLocalExpeditionState(user.id, nextExpeditions);
      saveUserExpeditions(user.id, nextExpeditions).catch(err => console.warn('[Apex] sync spedizioni non bloccante:', err));
      reloadSupabaseData(user).catch(err => console.warn('[Apex] reload destinazione non bloccante:', err));
    } catch (err) {
      console.warn('[Apex] Aggiungi destinazione fallito:', err);
      setDataError(err?.message || 'Errore aggiunta paese');
    } finally {
      setDestinationsLoading(false);
    }
  };

  const handleVisitedCountriesChange = (nextList = []) => {
    const clean = normalizeIsoList(nextList);
    setVisitedCountries(clean);
    saveVisitedCountries(clean);
  };

  const handleRemoveDestination = async (iso) => {
    const cleanIso = String(iso || '').toUpperCase();
    if (!cleanIso) return;
    const nextVisited = normalizeIsoList(visitedCountries.filter(code => String(code).toUpperCase() !== cleanIso));
    setVisitedCountries(nextVisited);
    saveVisitedCountries(nextVisited);
    removePendingDestinations(user?.id, [cleanIso]);
    if (!user?.id) return;
    try {
      await withTimeout(removeUserDestination(user.id, cleanIso), 4500, false, 'removeUserDestination');
      await trackUserEvent(user, 'country_removed', { country_iso:cleanIso, source_screen:'regions' }, userProfile);
    } catch (err) {
      console.warn('[Apex] Rimozione destinazione fallita:', err);
      setDataError(err?.message || 'Errore rimozione paese');
    }
  };

  const confirmPromptCountries = async (codes = []) => {
    const cleanCodes = normalizeIsoList(codes);
    if (!cleanCodes.length) { setCountryVisitPrompt(null); return; }
    setCountryVisitPrompt(null);
    handleVisitedCountriesChange(normalizeIsoList([...(visitedCountries || []), ...cleanCodes]));
    await handleAddDestination(cleanCodes, []);
  };


  // All'iscrizione i paesi scelti sono illimitati e le loro Spedizioni partono
  // subito (prima ondata), senza consumare crediti mensili. Un solo Regalo di
  // Spedizione di benvenuto.
  const activateOnboardingExpeditions = (isoList = []) => {
    const clean = normalizeIsoList(isoList || []);
    if (!clean.length) return;
    const now = new Date().toISOString();
    const next = { ...expeditionState };
    clean.forEach(iso => { if (!next[iso]) next[iso] = { revealedWaves:1, activatedAt:now }; });
    setExpeditionState(next);
    saveLocalExpeditionState(user?.id || 'guest', next);
    if (user?.id) saveUserExpeditions(user.id, next).catch(err => console.warn('[Apex] sync spedizioni non bloccante:', err));
    grantExpeditionGift(user?.id);
    setExpeditionGift({ iso:clean[0], recognitions:EXPEDITION_GIFT_RECOGNITIONS, days:EXPEDITION_GIFT_DAYS });
  };

  const handleCompleteOnboarding = async ({ nickname, countries, seenAnimalIds, tripTags, demographics = {} }) => {
    if (!user?.id) throw new Error('Sessione non valida');
    setDataError('');
    try {
      const rpcResult = await withTimeout(
        supabase.rpc('complete_user_onboarding', {
          p_user_id: user.id,
          p_nickname: nickname,
          p_iso_list: countries,
          p_seen_animal_ids: seenAnimalIds,
          p_trip_tags: tripTags || [],
        }),
        12000,
        { data:{ ok:true, timed_out:true, unlocked_count:(countries || []).length, seen_count:(seenAnimalIds || []).length, badge_ids:['ONB-01-L1'] }, error:null },
        'complete_user_onboarding'
      );
      const { data, error } = rpcResult || {};
      if (error) throw error;

      const badgeIds = (data?.badge_ids || data?.badges || []).map(normalizeBadgeId);
      const cleanCountries = normalizeIsoList(countries || []);
      if (cleanCountries.length) {
        setVisitedCountries(cleanCountries);
        saveVisitedCountries(cleanCountries);
        activateOnboardingExpeditions(cleanCountries);
      }
      await persistOnboardingQuestionnaire(user, demographics || {});
      await trackUserEvent(user, 'onboarding_completed', {
        source_screen:'onboarding',
        countries_count:(countries || []).length,
        seen_count:(seenAnimalIds || []).length,
        trip_tags:tripTags || [],
        acquisition_source:demographics?.acquisition_source || '',
        water_activity_interests:demographics?.water_activity_interests || [],
      }, { ...userProfile, consent_analytics:demographics?.consent_analytics });
      if (badgeIds.length) {
        setEarnedBadgeIds(prev => Array.from(new Set([...prev.map(normalizeBadgeId), ...badgeIds])));
        const awards = badgeIds.map(id => AWARD_RULES.find(rule => normalizeBadgeId(rule.badgeId) === id)).filter(Boolean);
        if (awards.length) setAwardQueue(prev => [...prev, ...awards]);
      }
      return data || {};
    } catch (err) {
      console.warn('[Apex] RPC onboarding fallita, uso fallback frontend:', err);
      const cleanCountries = normalizeIsoList(countries || []);
      if (cleanCountries.length) {
        setVisitedCountries(cleanCountries);
        saveVisitedCountries(cleanCountries);
        activateOnboardingExpeditions(cleanCountries);
      }
      for (const iso of cleanCountries) {
        await withTimeout(persistUserDestination(user.id, iso, tripTags || []), 3500, false, 'persistUserDestination');
        const { error: rpcError } = await withTimeout(supabase.rpc('unlock_animals_for_destination', {
          p_user_id: user.id,
          p_iso: iso,
          p_trip_tags: tripTags || [],
        }), 4500, { error:null }, 'unlock_animals_for_destination');
        if (rpcError) console.warn('[Apex] unlock fallback non riuscito:', rpcError);
      }

      const now = new Date().toISOString();
      await persistOnboardingQuestionnaire(user, demographics || {});
      await trackUserEvent(user, 'onboarding_completed', {
        source_screen:'onboarding',
        fallback:true,
        countries_count:cleanCountries.length,
        seen_count:seenAnimalIds?.length || 0,
        trip_tags:tripTags || [],
        acquisition_source:demographics?.acquisition_source || '',
        water_activity_interests:demographics?.water_activity_interests || [],
      }, { ...userProfile, consent_analytics:demographics?.consent_analytics });
      if (seenAnimalIds?.length) {
        const rows = seenAnimalIds.map(animal_id => ({
          user_id: user.id,
          animal_id,
          unlock_status:'seen',
          unlocked_at: now,
          seen_at: now,
          updated_at: now,
        }));
        const { error: seenError } = await supabase.from('user_animals').upsert(rows, { onConflict:'user_id,animal_id' });
        if (seenError) throw seenError;
      }

      await supabase.from('user_profiles').upsert({
        user_id:user.id,
        username:userProfile?.username || String(user.email || 'esploratore').split('@')[0],
        nickname,
        onboarding_completed:true,
        onboarding_completed_at:now,
      }, { onConflict:'user_id' });

      await persistEarnedBadges(user.id, ['ONB-01-L1']);
      setEarnedBadgeIds(prev => Array.from(new Set([...prev.map(normalizeBadgeId), 'ONB-01-L1'])));
      const first = AWARD_RULES.find(rule => rule.badgeId === 'ONB-01-L1');
      if (first) setAwardQueue(prev => [...prev, first]);
      return { ok:true, unlocked_count:cleanCountries.length, seen_count:seenAnimalIds?.length || 0, badge_ids:['ONB-01-L1'] };
    }
  };

  const finishOnboarding = async (options = {}) => {
    const now = new Date().toISOString();
    persistProfileDemographicsLocal(user?.id, { onboarding_completed: true, onboarding_completed_at: now });
    setUserProfile(prev => mergeProfileDemographics({
      ...(prev || buildFallbackProfile(user, true)),
      onboarding_completed:true,
      has_completed_tutorial:false,
      onboarding_completed_at:new Date().toISOString(),
    }, user?.id));
    setSel(null);
    setPage('menu');
    // Ricarica silenziosa: non bloccare mai la schermata finale dell’onboarding.
    if (!options?.skipReload) {
      reloadSupabaseData(user).catch(err => console.warn('[Apex] reload post-onboarding non bloccante:', err));
    }
  };

  const openAwardFromToast = (award) => {
    if (!award?.badgeId) return;
    setToastOpenBadgeId(normalizeBadgeId(award.badgeId));
    setAwardQueue(prev => prev.slice(1));
    setSectionReturnPage('menu');
    setPage('badges');
    maybeShowSectionIntro('badges');
  };

  function maybeShowSectionIntro(section) {
    if (!section) return;
    if (tutorialStep) return;
    if (userProfile && userProfile.has_completed_tutorial === false) return;
    const validSections = ['regions', 'badges', 'abilities', 'compare', 'profile', 'gallery', 'lifeweb', 'quickSeen', 'friends'];
    const resolved = section === 'taxonomy' ? 'lifeweb' : section;
    if (!validSections.includes(resolved)) return;
    if (hasSeenSectionIntro(resolved)) return;
    markSectionIntroSeen(resolved);
    setActiveSectionGuide(null);
    setTimeout(() => setSectionIntro(resolved), 260);
  }

  const getCurrentTutorialAnimal = () => {
    if (tutorialAnimalId) return animalsData.find(a => a.id === tutorialAnimalId) || getTutorialAnimal();
    return getTutorialAnimal();
  };

  const handleTutorialAnimalSelect = (animal) => {
    setTutorialAnimalId(animal?.id || tutorialAnimalId);
    setTutorialStep('detail-guide');
  };

  const handleTutorialNext = () => {
    if (tutorialStep === 'grid-basics') { setTutorialStep('grid-open'); return; }
    if (tutorialStep === 'detail-guide') { setTutorialStep('detail-status'); return; }
    if (tutorialStep === 'home-finish') { completeOperationalTutorial(); return; }
  };
  const handleTutorialPrev = () => {
    if (tutorialStep === 'home-finish') { setSel(getCurrentTutorialAnimal()); setPage('grid'); setTutorialStep('detail-status'); return; }
    if (tutorialStep === 'detail-status') { setTutorialStep('detail-guide'); return; }
    if (tutorialStep === 'detail-guide') { setSel(null); setPage('grid'); setTutorialStep('grid-open'); return; }
    if (tutorialStep === 'grid-open') { setTutorialStep('grid-basics'); return; }
    if (tutorialStep === 'grid-basics') { setPage('menu'); setTutorialStep('home'); return; }
  };

  const handleTutorialAbilityClick = () => {};
  const handleTutorialMetricClick = () => {};
  const handleTutorialStatusClick = () => {
    if (tutorialStep === 'detail-status') setTimeout(() => { setSel(null); setPage('menu'); setTutorialStep('home-finish'); }, 620);
  };

  const completeOperationalTutorial = async () => {
    const now = new Date().toISOString();
    setTutorialStep(null);
    setTutorialAnimalId(null);
    setTutorialStamp(false);
    persistProfileDemographicsLocal(user?.id, { has_completed_tutorial: true, tutorial_completed_at: now });
    setUserProfile(prev => ({ ...(prev || {}), has_completed_tutorial:true, tutorial_completed_at:now }));
    try {
      if (user?.id) {
        await supabase
          .from('user_profiles')
          .update({ has_completed_tutorial:true, tutorial_completed_at:now })
          .eq('user_id', user.id);
      }
    } catch (err) {
      console.warn('[Apex] Salvataggio tutorial non bloccante:', err);
    }
    setSel(null);
    setPage('grid');
  };


  const startInitialOnboardingFromSettings = () => {
    setDataError('');
    setSel(null);
    setGridPreset(null);
    setGridReturnTarget(null);
    setRegionsInitialView(null);
    setTutorialStep(null);
    setTutorialAnimalId(null);
    setTutorialStamp(false);
    setPage('grid');
    setUserProfile(prev => ({
      ...(prev || buildFallbackProfile(user, false)),
      onboarding_completed:false,
      has_completed_tutorial:false,
    }));
  };

	  const startOperationalTutorialFromSettings = () => {
	    const target = getTutorialAnimal();
	    setSel(null);
	    setGridPreset(null);
	    setGridReturnTarget(null);
	    setRegionsInitialView(null);
	    setPage('menu');
	    setTutorialAnimalId(target?.id || null);
	    setTutorialStamp(false);
	    setTutorialStep('home');
    setUserProfile(prev => ({
      ...(prev || buildFallbackProfile(user, true)),
      onboarding_completed:true,
      has_completed_tutorial:false,
    }));
  };

const enriched = sel ? getEnrichedAnimal({ ...sel, status: getResolvedAnimalStatus(sel, statusMap, visitedCountries) }) : null;
const openPage = (nextPage, returnPage = 'menu') => {
  const apply = () => {
  setSel(null);
  setPhotoTarget(null);
  setGridReturnTarget(null);
  setRegionsInitialView(null);
  setTaxonomyInitialAnimal(null);
  if (nextPage !== 'compare') setComparatorInitialAnimal(null);
  if (nextPage !== 'lifeweb') setLifeWebInitialAnimal(null);
  setFeatureReturnAnimal(null);
  setSectionReturnPage(returnPage);
  if (nextPage === 'regions') prefetchBioregionGeoJson();
	  if (nextPage === 'grid') {
	    if (tutorialStep === 'home') setGridPreset({ id: Date.now(), type:'tutorial', search:'piccione', statuses:['ricercato'], title:'Apex' });
	    else setGridPreset({ id: Date.now(), type:'status', statuses:['avvistato','catturato'], title:'Apex' });
	    setPage('grid');
	    if (tutorialStep === 'home') setTutorialStep('grid-basics');
	    return;
	  }
	  setPage(nextPage || 'menu');
	  maybeShowSectionIntro(nextPage);
  };
  if (nextPage === 'menu' || nextPage === 'compare' || nextPage === 'regions' || nextPage === 'taxonomy' || nextPage === 'profile') startNavTransition(apply);
  else apply();
	};
const openFriends = (tab = 'feed', returnPage = 'menu') => {
  setFriendsInitialTab(tab || 'feed');
  openPage('friends', returnPage);
};
	const openComparator = (animal=null) => {
	  const enrichedAnimal = animal ? getEnrichedAnimal({ ...animal, status: getResolvedAnimalStatus(animal, statusMap, visitedCountries) }) : null;
	  startNavTransition(() => {
	    setFeatureReturnAnimal(enrichedAnimal); setSel(null); setGridReturnTarget(null); setComparatorInitialAnimal(enrichedAnimal); setPage('compare');
	    maybeShowSectionIntro('compare');
	  });
	};
	const openLifeWeb = (animal=null) => {
	  const enrichedAnimal = animal ? getEnrichedAnimal({ ...animal, status: getResolvedAnimalStatus(animal, statusMap, visitedCountries) }) : null;
	  setFeatureReturnAnimal(enrichedAnimal); setSel(null); setGridReturnTarget(null); setTaxonomyInitialAnimal(enrichedAnimal); setPage('taxonomy');
	  maybeShowSectionIntro('taxonomy');
	};
const openPhotoRecognition = (animal=null) => {
  const enrichedAnimal = animal ? { ...animal, status: getResolvedAnimalStatus(animal, statusMap, visitedCountries) } : null;
  trackUserEvent(user, 'photo_recognition_started', { animal_id:enrichedAnimal?.id || null, animal_name:enrichedAnimal?.com || null, source_screen:'camera' }, userProfile);
  setPhotoTarget(enrichedAnimal || { mode:'identify' });
};
const confirmPhotoRecognition = async (animal, meta={}) => {
  if (!animal?.id) return;
  setPhotoTarget(null);
  await trackUserEvent(user, 'photo_recognition_confirmed', { animal_id:animal.id, animal_name:animal.com, rarity:animal.rarity, ai_confidence:meta.confidence || null, has_gps:!!meta.gps, source_screen:'photo_recognition' }, userProfile);
  // Cattura solo tramite validazione AI: la specie deve comparire tra le proposte del riconoscimento.
  const aiValidated = meta.ai_status === 'certain' || meta.ai_status === 'alternatives';
  const resolvedStatus = getResolvedAnimalStatus(animal, statusMap, visitedCountries);
  if (aiValidated && resolvedStatus !== 'catturato') {
    await handleStatusChange(animal.id, 'catturato');
  } else if (!aiValidated && (resolvedStatus === 'ricercato' || resolvedStatus === 'nascosto' || !resolvedStatus)) {
    await handleStatusChange(animal.id, 'avvistato');
  }
  try {
    if (user?.id) {
      await supabase.from('animal_photos').insert({
        user_id:user.id,
        animal_id:animal.id,
        ai_guess_animal_id:animal.id,
        ai_confidence:meta.confidence || null,
        confirmed_by_user:true,
        storage_path:meta.storage_path || null,
        public_url:meta.public_url || null,
        photo_source:meta.file ? 'upload' : null,
        recognition_status:meta.ai_status || 'confirmed',
        lat:meta.gps?.lat || null,
        lng:meta.gps?.lng || null,
        location_accuracy:meta.gps?.accuracy || null,
        created_at:new Date().toISOString(),
      });
    }
  } catch (err) {
    console.warn('[Apex] animal_photos non bloccante:', err);
  }
  if (meta.openDetail) {
    const nextStatus = (meta.ai_status === 'certain' || meta.ai_status === 'alternatives') ? 'catturato' : 'avvistato';
    startDetailTransition(() => {
      setPage('grid');
      setSel(getEnrichedAnimal({ ...animal, status:nextStatus }));
    });
  }
};
const requestAnimalAdd = async (payload = {}) => {
  const commonName = String(payload.common_name || '').trim();
  if (!commonName) return { ok:false };
  const body = {
    user_id:user?.id || null,
    user_email:user?.email || userProfile?.email || null,
    common_name:commonName,
    scientific_name:payload.scientific_name || '',
    photo_url:payload.photo_url || '',
    photo_storage_path:payload.photo_storage_path || '',
    ai_summary:payload.ai_summary || '',
    ai_probability:payload.ai_probability ?? null,
    lat:payload.gps?.lat ?? null,
    lng:payload.gps?.lng ?? null,
  };
  try {
    const response = await fetch('/api/request-animal-add', {
      method:'POST',
      headers:{ 'Content-Type':'application/json' },
      body:JSON.stringify(body),
    });
    const data = await response.json().catch(() => ({}));
    if (response.ok && data.stored) {
      await trackUserEvent(user, 'animal_add_requested', { common_name:commonName, scientific_name:body.scientific_name || null, stored:true, notified:!!data.notified }, userProfile);
      return { ok:true, mode:'database', notified:!!data.notified };
    }
    if (response.ok && data.fallback === 'mailto') {
      const adminEmail = process.env.REACT_APP_APEX_ADMIN_EMAIL || '';
      if (adminEmail && typeof window !== 'undefined') {
        const subject = encodeURIComponent(`Richiesta animale Apex: ${commonName}`);
        const text = encodeURIComponent([
          `Nome comune: ${commonName}`,
          `Nome scientifico: ${body.scientific_name || '-'}`,
          `Utente: ${body.user_email || user?.id || '-'}`,
          `Foto: ${body.photo_url || '-'}`,
          `Note AI: ${body.ai_summary || '-'}`,
        ].join('\n'));
        window.location.href = `mailto:${adminEmail}?subject=${subject}&body=${text}`;
        return { ok:true, mode:'mailto' };
      }
    }
    if (!response.ok) throw new Error(data?.error || 'Richiesta non salvata.');
  } catch (err) {
    console.warn('[Apex] request-animal-add api:', err);
  }
  if (user?.id) {
    try {
      const { error } = await supabase.from('animal_add_requests').insert({ ...body, user_id:user.id, status:'pending' });
      if (!error) {
        await trackUserEvent(user, 'animal_add_requested', { common_name:commonName, scientific_name:body.scientific_name || null, stored:true, notified:false }, userProfile);
        return { ok:true, mode:'supabase' };
      }
    } catch (err) {
      console.warn('[Apex] animal_add_requests insert:', err);
    }
  }
  const adminEmail = process.env.REACT_APP_APEX_ADMIN_EMAIL || '';
  if (adminEmail && typeof window !== 'undefined') {
    const subject = encodeURIComponent(`Richiesta animale Apex: ${commonName}`);
    const text = encodeURIComponent([
      `Nome comune: ${commonName}`,
      `Nome scientifico: ${body.scientific_name || '-'}`,
      `Utente: ${body.user_email || user?.id || '-'}`,
      `Foto: ${body.photo_url || '-'}`,
      `Note AI: ${body.ai_summary || '-'}`,
    ].join('\n'));
    window.location.href = `mailto:${adminEmail}?subject=${subject}&body=${text}`;
    return { ok:true, mode:'mailto' };
  }
  return { ok:false };
};
const openHabitatGrid = (territory, habitat, returnContext = null) => {
  if (!territory || !habitat) return;
  const geographyFilter = territory.filterValue || (territory.kind === 'region' ? `territory-region:${territory.id}` : `ecoregion:${territory.id}`);
  const isGeneralHabitat = habitat.id === 'GENERAL';
  const exactBioregionId = isGeneralHabitat ? (habitat.exactBioregionId || territory.bioregionId || territory.id) : null;
  setSel(null);
  setGridPreset({ id: Date.now(), type:'habitat-grid', customFilter:(a)=> (exactBioregionId ? matchExactBioregion(a, exactBioregionId) : matchGeographySelection(a, [geographyFilter])) && (isGeneralHabitat || animalMatchesHabitat(a, habitat.id)), customSort:isGeneralHabitat ? compareAnimalsRevealedFirst : null, title:isGeneralHabitat ? territory.label : `${habitat.label}` });
  setGridReturnTarget({ page:'regions', view:returnContext || 'ecoregions' });
  setPage('grid');
};
const openGridWithStatus = (statuses) => {
  setSel(null); setGridReturnTarget(null); setGridPreset({ id: Date.now(), type:'status', statuses, title:'Apex' }); setPage('grid');
};
const openGridWithCategory = (categoryId, label) => {
  setSel(null); setGridPreset({ id: Date.now(), type:'category', categories:[categoryId], title: label || 'Abilità' }); setGridReturnTarget({ page:'abilities' }); setPage('grid');
};
const openGridWithGeography = (geoValue, label, returnView='countries') => {
  setSel(null); setGridPreset({ id: Date.now(), type:'geography', geography:[geoValue], title: label || 'Geografia' }); setGridReturnTarget({ page:'regions', view:returnView }); setPage('grid');
};
const handleLogout = async () => {
  setDataError('');
  clearSupabaseAccessTokenCache();
  socialSnapshotCache = { key:'', data:null, ts:0 };
  socialSnapshotInflight = null;
  setSession(null);
  setUser(null);
  setUserProfile(null);
  setSel(null);
  setPage('grid');
  setGridPreset(null);
  setGridReturnTarget(null);
  setAwardQueue([]);
  setAuthLoading(false);
  try {
    await withTimeout(supabase.auth.signOut({ scope:'local' }), 4500, null, 'signOut');
  } catch (err) {
    console.warn('[Apex] logout non bloccante:', err);
  }
};
const jumpToClassFromDetail = (cls, animal) => {
  setGridReturnTarget({ page:'detail', animal }); setSel(null); setGridPreset({ id: Date.now(), type:'class', cls, title:`Classe · ${cls}` }); setPage('grid');
};
const openTaxonomyFilterFromDetail = ({ key, value, animal }) => {
  const labels = { kin:'Regno', phy:'Phylum', cls:'Classe', ord:'Ordine', fam:'Famiglia', gen:'Genere' };
  if (!key || !value) return;
  setGridReturnTarget(animal ? { page:'detail', animal } : { page:'taxonomy' });
  setSel(null);
  setGridPreset({
    id: Date.now(),
    type:'taxonomy-node',
    tax:{ key, value, label:`${labels[key] || 'Tassonomia'}: ${value}` },
    statuses:['misterioso','ricercato','avvistato','catturato'],
    title:`${labels[key] || 'Tassonomia'} · ${value}`,
  });
  setPage('grid');
};
const returnFromFilteredGrid = () => {
  const target = gridReturnTarget;
  setGridReturnTarget(null);
  setGridPreset(null);
  if (target?.page === 'detail' && target.animal) { setSel(target.animal); setPage('grid'); return; }
  if (target?.page === 'abilities') { setSel(null); setPage('abilities'); return; }
  if (target?.page === 'regions') { setSel(null); setRegionsInitialView(target.view || 'countries'); setPage('regions'); return; }
  if (target?.page === 'taxonomy') { setSel(null); setPage('taxonomy'); return; }
  setSel(null); setPage('grid');
};

const returnFromSection = (fallback = 'menu') => {
  const target = sectionReturnPage || fallback;
  setSectionReturnPage('menu');
  setPage(target);
};

const returnFromFeaturePage = (fallback='menu') => {
  if (featureReturnAnimal?.id) {
    const fresh = animalsData.find(a => a.id === featureReturnAnimal.id) || featureReturnAnimal;
    setComparatorInitialAnimal(null);
    setLifeWebInitialAnimal(null);
    setTaxonomyInitialAnimal(null);
    setFeatureReturnAnimal(null);
    setPage('grid');
    setSel({ ...fresh, status: normalizeAnimalStatus(statusMap[fresh.id] ?? fresh.status) });
    return;
  }
  setComparatorInitialAnimal(null);
  setLifeWebInitialAnimal(null);
  setTaxonomyInitialAnimal(null);
  setFeatureReturnAnimal(null);
  setPage(fallback);
};

const renderDetailOverlay = () => enriched ? <div style={{ position:'absolute', inset:0, zIndex:80, background:theme==='light'?LIGHT_APP_BG:'#1C1C1E' }}><Detail theme={theme} a={enriched} documentedMap={documentedMap} onBack={()=>setSel(null)} onStatusChange={handleStatusChange} onJumpToClass={jumpToClassFromDetail} onOpenTaxonomyFilter={openTaxonomyFilterFromDetail} onOpenComparator={openComparator} onOpenLifeWeb={openLifeWeb} onOpenPhoto={openPhotoRecognition} visitedCountries={visitedCountries} statusMap={statusMap} tutorialStep={tutorialStep} onTutorialAbilityClick={handleTutorialAbilityClick} onTutorialMetricClick={handleTutorialMetricClick} onTutorialStatusClick={handleTutorialStatusClick}/></div> : null;

  if (authLoading) {
    return <ApexBootLoader frameProps={APP_FRAME_PROPS} />;
  }

  if (!user) return <AuthScreen onAuthReady={()=>supabase.auth.getSession().then(({data})=>{setSession(data.session||null);setUser(data.session?.user||null);})} />;

  if (!userProfile && dataLoading) {
    return <ApexBootLoader frameProps={APP_FRAME_PROPS} message="Caricamento profilo…" />;
  }

  if (!userProfile && !dataLoading) {
    setTimeout(() => setUserProfile(buildFallbackProfile(user, false)), 0);
    return <ApexBootLoader frameProps={APP_FRAME_PROPS} message="Apertura Apex…" />;
  }

  if (userProfile && userProfile.onboarding_completed === false) {
    return (
      <div {...APP_FRAME_PROPS} style={{ fontFamily:"'Sora',-apple-system,BlinkMacSystemFont,sans-serif", height:'var(--animaldex-app-height, 100dvh)', maxWidth:480, margin:'0 auto', overflow:'hidden', background:'#111113', position:'relative' }}>
        <OnboardingFlow user={user} animals={animalsData} initialNickname={userProfile.nickname || userProfile.username} onComplete={handleCompleteOnboarding} onFinish={finishOnboarding} />
      </div>
    );
  }

  const renderHomeMenu = () => {
    const dailyDiscoveryAnimal = getDailyAtlasDiscoveryStable(user?.id, animalsData, documentedMap, statusMap, visitedCountries);
    const homeProps = {
      theme,
      menuProgress,
      dailyDiscovery: dailyDiscoveryAnimal ? { animal: dailyDiscoveryAnimal, documented: !!documentedMap[String(dailyDiscoveryAnimal.id)] } : null,
      onDocumentAnimal: (id) => handleDocumentAnimal(id, 'home_daily_discovery'),
      onOpenAnimal: (animal) => {
        setGridPreset(null);
        setGridReturnTarget(null);
        setPage('grid');
        selectAnimal(getEnrichedAnimal({ ...animal, status: getResolvedAnimalStatus(animal, statusMap, visitedCountries) }));
      },
      usageStreak: getUsageStreak(),
      socialSnapshot,
      onOpenFriends: openFriends,
      onOpen: openPage,
      onBack: () => setPage('grid'),
      onLogout: handleLogout,
      tutorialFocus: tutorialStep === 'home' ? 'grid' : null,
      statusMap,
      visitedCountries,
      earnedBadgeIds,
      userProfile,
      user,
      onOpenGridStatus: openGridWithStatus,
      onOpenRegions: () => openPage('regions', 'menu'),
      onQuickSeen: () => { setPage('quickSeen'); maybeShowSectionIntro('quickSeen'); },
      onOpenPhoto: openPhotoRecognition,
      onOpenBadge: (badgeId) => {
        setToastOpenBadgeId(normalizeBadgeId(badgeId));
        setSectionReturnPage('menu');
        setPage('badges');
        maybeShowSectionIntro('badges');
      },
    };
    const HomeComponent = homeVariant === HOME_VARIANTS.v2 ? MainMenuV2 : MainMenuClassic;
    return <HomeComponent {...homeProps} />;
  };

  const renderPage = () => {
	    if (page === 'menu') return renderHomeMenu();
    if (page === 'quickSeen') return <QuickSeenPage theme={theme} onBack={()=>setPage('menu')} animals={animalsData} statusMap={statusMap} visitedCountries={visitedCountries} onStatusChange={handleStatusChange} onSelect={selectAnimal} user={user} userProfile={userProfile} />;
    if (page === 'compare') return (
      <FeaturePageErrorBoundary theme={theme} title="Comparatore" onBack={()=>returnFromFeaturePage('menu')} resetKey={`compare-${theme}-${animalsData?.length || 0}-${comparatorInitialAnimal?.id || ''}`}>
        <ComparatorPage theme={theme} onBack={()=>returnFromFeaturePage('menu')} animals={animalsWithStatus} statusMap={statusMap} visitedCountries={visitedCountries} initialAnimal={comparatorInitialAnimal} />
      </FeaturePageErrorBoundary>
    );
    if (page === 'friends') return <FriendsPage theme={theme} accessToken={session?.access_token || ''} initialTab={friendsInitialTab} initialSnapshot={socialSnapshot} menuProgress={menuProgress} onSocialChange={setSocialSnapshot} onBack={()=>returnFromSection('menu')} user={user} userProfile={userProfile} statusMap={statusMap} visitedCountries={visitedCountries} earnedBadgeIds={earnedBadgeIds} />;
    if (page === 'profile') return <ProfilePage theme={theme} onBack={()=>setPage('menu')} pendingFriendRequestCount={socialAlertCount} animalsWithStatus={animalsWithStatus} statusMap={statusMap} visitedCountries={visitedCountries} earnedBadgeIds={earnedBadgeIds} userProfile={userProfile} user={user} onLogout={handleLogout} onOpenGridStatus={openGridWithStatus} onOpenBadges={()=>openPage('badges', 'profile')} onOpenRegions={()=>openPage('regions', 'profile')} onOpenGallery={()=>openPage('gallery', 'profile')} onOpenFriends={openFriends} />;
	    if (page === 'badges') return <BadgesPage theme={theme} onBack={()=>returnFromSection('menu')} statusMap={statusMap} visitedCountries={visitedCountries} earnedBadgeIds={earnedBadgeIds} awardMetrics={awardMetrics} unlockedAwards={unlockedAwards} openBadgeId={toastOpenBadgeId} onBadgeOpened={()=>setToastOpenBadgeId(null)} tutorialActive={activeSectionGuide==='badges'} onTutorialBadgeOpen={()=>setActiveSectionGuide(null)} />;
    if (page === 'regions') return <div style={{ height:'100%', position:'relative', overflow:'hidden' }}><FeaturePageErrorBoundary theme={theme} title="Territori" onBack={()=>returnFromSection('menu')} resetKey={`regions-${theme}-${regionsInitialView || 'planet'}`}><RegionsPage theme={theme} animalsWithStatus={animalsWithStatus} onBack={()=>returnFromSection('menu')} statusMap={statusMap} visitedCountries={visitedCountries} onVisitedCountriesChange={handleVisitedCountriesChange} onRemoveDestination={handleRemoveDestination} initialView={regionsInitialView} onSelect={selectAnimal} onOpenCountry={(code)=>openGridWithGeography(code, getCountryDisplayName(code), 'countries')} onOpenRegion={(value,label)=>openGridWithGeography(value, label, 'continents')} onAddDestination={handleAddDestination} destinationsLoading={destinationsLoading} onOpenHabitatGrid={openHabitatGrid} user={user} /></FeaturePageErrorBoundary>{renderDetailOverlay()}</div>;
    if (page === 'gallery') return <div style={{ height:'100%', position:'relative', overflow:'hidden' }}><GalleryPage theme={theme} onBack={()=>returnFromSection('profile')} statusMap={statusMap} onSelect={selectAnimal} />{renderDetailOverlay()}</div>;
    if (page === 'lifeweb') return <div style={{ height:'100%', position:'relative', overflow:'hidden' }}><StandaloneLifeWebPage theme={theme} statusMap={statusMap} visitedCountries={visitedCountries} onBack={()=>returnFromFeaturePage('grid')} animals={animalsData} initialAnimal={lifeWebInitialAnimal} onOpenAnimal={selectAnimal} />{renderDetailOverlay()}</div>;
    if (page === 'taxonomy') return <div style={{ height:'100%', position:'relative', overflow:'hidden' }}><TaxonomyErrorBoundary theme={theme} onBack={()=>setPage('menu')} resetKey={`${theme}-${animalsWithStatus?.length || 0}-${taxonomyInitialAnimal?.id || ''}`}><TaxonomyExplorer theme={theme} animals={animalsWithStatus} statusMap={statusMap} visitedCountries={visitedCountries} initialAnimal={taxonomyInitialAnimal} onBack={()=>setPage('menu')} onOpenAnimal={selectAnimal} onOpenTaxonomyFilter={openTaxonomyFilterFromDetail} /></TaxonomyErrorBoundary>{renderDetailOverlay()}</div>;
    if (page === 'settings') return <SettingsPage onBack={()=>setPage('menu')} onStartInitialOnboarding={startInitialOnboardingFromSettings} onStartOperationalTutorial={startOperationalTutorialFromSettings} theme={theme} onThemeChange={setTheme} homeVariant={homeVariant} onHomeVariantChange={handleHomeVariantChange} />;
    if (page === 'abilities') return <AbilitiesPage theme={theme} onBack={()=>setPage('menu')} onOpenAbility={openGridWithCategory} tutorialActive={activeSectionGuide==='abilities'} onTutorialAbilityOpen={()=>setActiveSectionGuide(null)} />;
    return <div style={{ height:'100%', position:'relative', overflow:'hidden' }}><Grid theme={theme} animals={animalsWithStatus} onSelect={selectAnimal} statusMap={statusMap} visitedCountries={visitedCountries} onHome={()=>openPage('menu')} onOpenRegions={()=>openPage('regions')} preset={gridPreset} onBackToOrigin={gridReturnTarget ? returnFromFilteredGrid : null} tutorialActive={tutorialStep==='grid-open'} tutorialStep={tutorialStep} tutorialAnimalId={tutorialAnimalId} onTutorialAnimalSelect={handleTutorialAnimalSelect} />{renderDetailOverlay()}</div>;
  };

  return (
    <div id="animaldex-app-root" className="animaldex-app-frame" data-theme={theme} style={{ fontFamily:"'Sora',-apple-system,BlinkMacSystemFont,sans-serif", height:'var(--animaldex-app-height, 100dvh)', maxWidth:480, margin:'0 auto', display:'flex', flexDirection:'column', overflow:'hidden', background:theme==='light'?LIGHT_APP_BG:'#1C1C1E', position:'relative' }}>
	      <div key={page} className="animaldex-page-dive" style={{ height:'100%', minHeight:0, overflow:'hidden' }}>{renderPage()}</div>
	      {tutorialStep && <OperationalTutorialOverlay step={tutorialStep} animal={getCurrentTutorialAnimal()} homeGridLabel={homeVariant === HOME_VARIANTS.v2 ? 'Esplora Dex' : 'I tuoi animali'} onNext={handleTutorialNext} onPrev={handleTutorialPrev} onFinish={completeOperationalTutorial} onSkip={completeOperationalTutorial} />}
	      {sectionIntro && !tutorialStep && <SectionIntroModal section={sectionIntro} onClose={()=>{ const guided = sectionIntro; markSectionIntroSeen(guided); setSectionIntro(null); if (guided === 'badges' || guided === 'abilities') setActiveSectionGuide(guided); }} />}
      <InstallPromptBanner suppressed={!!tutorialStep || userProfile?.has_completed_tutorial === false} />
	      {dataError && user && <SwipeDismissNotice onDismiss={()=>setDataError('')} style={{ position:'absolute', left:12, right:12, bottom:12, zIndex:250, borderRadius:14, padding:'10px 12px', background:'rgba(255,59,48,.92)', color:'white', fontSize:11, fontWeight:800, boxShadow:'0 10px 30px rgba(0,0,0,.35)' }}>{dataError}</SwipeDismissNotice>}
      {expeditionNotice && <SwipeDismissNotice onDismiss={()=>setExpeditionNotice('')} style={{ position:'absolute', left:12, right:12, bottom:12, zIndex:252, borderRadius:14, padding:'10px 12px', background:'linear-gradient(135deg,rgba(240,168,64,.96),rgba(200,121,85,.96))', color:'#1A1000', fontSize:11.5, fontWeight:900, boxShadow:'0 10px 30px rgba(0,0,0,.35)' }}>{expeditionNotice}</SwipeDismissNotice>}
      {activeAwardToast && <AwardToast award={activeAwardToast} onOpen={openAwardFromToast} onDismiss={()=>setAwardQueue(prev => prev.slice(1))} />}
      {photoTarget && <PhotoRecognitionModal animal={photoTarget?.id ? photoTarget : null} animals={animalsData} user={user} onClose={()=>setPhotoTarget(null)} onConfirm={confirmPhotoRecognition} onRequestAddAnimal={requestAnimalAdd} />}
      {expeditionGift && <ExpeditionGiftModal gift={expeditionGift} onClose={()=>setExpeditionGift(null)} />}
      {countryVisitPrompt && <CountryVisitPromptModal animal={countryVisitPrompt} visitedCountries={visitedCountries} onClose={()=>setCountryVisitPrompt(null)} onConfirm={confirmPromptCountries} />}
    </div>
  );
}
